INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f5beb19-67e2-4773-b8f8-5effef828301', '奉酬張洪州九齡江上見贈', '奉酬張洪州九齡江上见贈', '86611608-9c82-4893-b90e-6187dd3a6e2d', '唐', '["受命讞封疆，逢君牧豫章。","於焉審虞芮，復爾共舟航。","悵別秋陰盡，懷歸客思長。","江臯枉離贈，持此慰他鄉。"]', '["受命讞封疆，逢君牧豫章。","於焉審虞芮，复爾共舟航。","悵別秋陰尽，懷归客思长。","江臯枉離贈，持此慰他乡。"]', '诗', 'shi', '', NULL, '奉酬張洪州九齡江上見贈 孫翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12f78bb0-5e00-475f-82d8-06be38002050', '古意贈孫翃', '古意贈孫翃', '4b5b42cd-cd05-4878-bddb-7751144e3372', '唐', '["南望緱氏嶺，山居共澗陰。","東西十數里，緬邈方寸心。","雲日落廣廈，鶯花對孤琴。","琴中多苦調，悽切誰復尋。"]', '["南望緱氏嶺，山居共澗陰。","东西十數里，緬邈方寸心。","云日落廣廈，鶯花对孤琴。","琴中多苦調，悽切誰复尋。"]', '诗', 'shi', '', NULL, '古意贈孫翃 徐仁友 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a96b44c1-6739-43b1-972b-23ffe9cb582d', '奉和姚令公駕幸溫湯喜雪應制', '奉和姚令公駕幸溫湯喜雪應制', 'dbcc0132-8ccf-4459-9e6e-d2fc7e42303d', '唐', '["漢主新豐邑，周王尚父師。","雲符沛童唱，雪應海神期。","林變驚春早，山明訝夕遲。","況逢溫液霈，恩重御裘詩。"]', '["漢主新豐邑，周王尚父師。","云符沛童唱，雪應海神期。","林变驚春早，山明訝夕遲。","況逢溫液霈，恩重御裘诗。"]', '诗', 'shi', '', NULL, '奉和姚令公駕幸溫湯喜雪應制 蘇綰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76b2b7f8-8748-4cdb-99db-2385a0e93721', '詠月', '詠月', '23664e9c-7d2f-4565-bd02-07023787991c', '唐', '["天使下西樓，光含萬里秋。","臺前疑挂鏡，簾外似懸鉤。","張尹將眉學，班姬取扇儔。","佳期應借問，爲報在刀頭。"]', '["天使下西楼，光含万里秋。","台前疑挂镜，簾外似懸鉤。","張尹將眉学，班姬取扇儔。","佳期應借问，爲報在刀头。"]', '诗', 'shi', '', NULL, '詠月 康庭芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee0836be-5444-4e92-bdcd-012b9e633cea', '山行見孤松成詠', '山行见孤松成詠', '008b841b-c947-48b0-94c9-0657220be994', '唐', '["孤松鬱山椒，肅爽凌清霄。","既挺千丈幹，亦生百尺條。","青青恆一色，落落非一朝。","大廈今已構，惜哉無人招。","寒霜十二月，枝葉獨不凋。"]', '["孤松鬱山椒，肅爽凌清霄。","既挺千丈幹，亦生百尺條。","青青恆一色，落落非一朝。","大廈今已構，惜哉無人招。","寒霜十二月，枝葉独不凋。"]', '诗', 'shi', '', NULL, '山行見孤松成詠 張宣明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caf76db9-d31b-429e-b8f4-4364e68e8014', '使至三姓咽麵', '使至三姓咽麵', '008b841b-c947-48b0-94c9-0657220be994', '唐', '["昔聞班家子，筆硯忽然投。","一朝撫長劒，萬里入荒陬。","豈不服艱險，只思清國讐。","山川去何歲，霜露幾逢秋。","玉塞已遐廓，鐵關方阻修。","東都日窅窅，西海此悠悠。","卒使功名建，長封萬里侯。"]', '["昔闻班家子，笔硯忽然投。","一朝撫长劒，万里入荒陬。","豈不服艱險，只思清国讐。","山川去何歲，霜露幾逢秋。","玉塞已遐廓，鐵关方阻修。","东都日窅窅，西海此悠悠。","卒使功名建，长封万里侯。"]', '诗', 'shi', '', NULL, '使至三姓咽麵 張宣明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69cbee7e-a72f-40d5-b1d8-45c6a2de2b87', '新都南亭別郭大元振', '新都南亭別郭大元振', 'c29c6262-fafd-40a9-9697-8f3771cbc544', '唐', '["竹徑女蘿蹊，蓮洲文石隄。","靜深人俗斷，尋翫往還迷。","碧潭秀初月，素林驚夕棲。","褰幌納鳥侶，罷琴聽猨啼。","佳辰改宿昔，勝寄在暌攜。","長懷賞心愛，如玉復如珪。"]', '["竹徑女蘿蹊，蓮洲文石隄。","静深人俗斷，尋翫往還迷。","碧潭秀初月，素林驚夕棲。","褰幌納鸟侶，罷琴听猨啼。","佳辰改宿昔，勝寄在暌携。","长懷賞心愛，如玉复如珪。"]', '诗', 'shi', '', NULL, '新都南亭別郭大元振 盧崇道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64e5a06a-f81d-49c7-9a5d-b6c4fdbbcd91', '登翅頭山題儼公石壁', '登翅头山題儼公石壁', 'c763e618-2c3a-47b7-a22a-2af2f7a12f1a', '唐', '["晨登翅頭山，山曛黃霧起。","却瞻迷向背，直下失城市。","暾日銜東郊，朝光生邑里。","掃除諸煙氛，照出衆樓雉。","青爲洞庭山，白是太湖水。","蒼茫遠郊樹，倏忽不相似。","萬象以區別，森然共盈几。","坐令開心胸，漸覺落塵滓。","北巖千餘仞，結廬誰家子。","願陪中峯遊，朝暮白雲裏。"]', '["晨登翅头山，山曛黄霧起。","却瞻迷向背，直下失城市。","暾日銜东郊，朝光生邑里。","掃除諸煙氛，照出衆楼雉。","青爲洞庭山，白是太湖水。","蒼茫远郊樹，倏忽不相似。","万象以區別，森然共盈几。","坐令开心胸，漸覺落塵滓。","北巖千餘仞，結廬誰家子。","願陪中峯游，朝暮白云裏。"]', '诗', 'shi', '', NULL, '登翅頭山題儼公石壁 包融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb1e768a-e763-4ebc-99bb-55846f117ad3', '阮公嘯臺', '阮公嘯台', 'c763e618-2c3a-47b7-a22a-2af2f7a12f1a', '唐', '["荒臺森荆杞，蒙籠無上路。","傳是古人跡，阮公長嘯處。","至今清風來，時時動林樹。","逝者共已遠，升攀想遺趣。","靜然荒榛門，久之若有悟。","靈光未歇滅，千載知仰慕。"]', '["荒台森荆杞，蒙籠無上路。","傳是古人跡，阮公长嘯处。","至今清风来，时时动林樹。","逝者共已远，升攀想遺趣。","静然荒榛门，久之若有悟。","靈光未歇滅，千載知仰慕。"]', '诗', 'shi', '', NULL, '阮公嘯臺 包融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47e1bba9-990a-4008-a8b1-aa2bcd8a2778', '酬忠公林亭', '酬忠公林亭', 'c763e618-2c3a-47b7-a22a-2af2f7a12f1a', '唐', '["江外有真隱，寂居歲已侵。","結廬近西術，種樹久成陰。","人迹乍及戶，車聲遙隔林。","自言解塵事，咫尺能輜塵。","爲道豈廬霍，會靜由吾心。","方秋院木落，仰望日蕭森。","持我興來趣，采菊行相尋。","塵念到門盡，遠情對君深。","一談入理窟，再索破幽襟。","安得山中信，致書移尚禽。"]', '["江外有真隐，寂居歲已侵。","結廬近西術，種樹久成陰。","人迹乍及戶，车声遙隔林。","自言解塵事，咫尺能輜塵。","爲道豈廬霍，會静由吾心。","方秋院木落，仰望日蕭森。","持我兴来趣，采菊行相尋。","塵念到门尽，远情对君深。","一談入理窟，再索破幽襟。","安得山中信，致书移尚禽。"]', '诗', 'shi', '', NULL, '酬忠公林亭 包融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eef64c3d-cdab-48ca-a00f-41052c7c3ce2', '送國子張主簿', '送国子張主簿', 'c763e618-2c3a-47b7-a22a-2af2f7a12f1a', '唐', '["湖岸纜初解，鶯啼別離處。","遙見舟中人，時時一迴顧。","坐悲芳歲晚，花落青軒樹。","春夢隨我心，悠揚逐君去。"]', '["湖岸纜初解，鶯啼別離处。","遙见舟中人，时时一迴顧。","坐悲芳歲晚，花落青軒樹。","春梦隨我心，悠揚逐君去。"]', '诗', 'shi', '', NULL, '送國子張主簿 包融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7e28bc0-5783-4899-af12-9baceec134f8', '和陳校書省中翫雪', '和陳校书省中翫雪', 'c763e618-2c3a-47b7-a22a-2af2f7a12f1a', '唐', '["芸閣朝來雪，飄颻正滿空。","褰開明月下，校理落花中。","色向懷鉛白，光因翰簡融。","能令草玄者，迴思入流風。"]', '["芸閣朝来雪，飄颻正满空。","褰开明月下，校理落花中。","色向懷鉛白，光因翰簡融。","能令草玄者，迴思入流风。"]', '诗', 'shi', '', NULL, '和陳校書省中翫雪 包融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc5fff54-81e0-4a6a-8611-db52356cb40b', '和崔會稽詠王兵曹廳前湧泉勢城中字', '和崔會稽詠王兵曹廳前湧泉勢城中字', 'c763e618-2c3a-47b7-a22a-2af2f7a12f1a', '唐', '["茂德來徵應，流泉入詠歌。","含靈符上善，作字表中和。","有草恆垂露，無風欲偃波。","爲看人共水，清白定誰多。"]', '["茂德来徵應，流泉入詠歌。","含靈符上善，作字表中和。","有草恆垂露，無风欲偃波。","爲看人共水，清白定誰多。"]', '诗', 'shi', '', NULL, '和崔會稽詠王兵曹廳前湧泉勢城中字 包融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0eb73c7c-ae62-4e2e-9050-c1b67cd5bcd2', '賦得岸花臨水發', '賦得岸花臨水發', 'c763e618-2c3a-47b7-a22a-2af2f7a12f1a', '唐', '["笑笑傍溪花，叢叢逐岸斜。","朝開川上日，夜發浦中霞。","照灼如臨鏡，䒠茸勝浣紗。","春來武陵道，幾樹落仙家。"]', '["笑笑傍溪花，叢叢逐岸斜。","朝开川上日，夜發浦中霞。","照灼如臨镜，䒠茸勝浣紗。","春来武陵道，幾樹落仙家。"]', '诗', 'shi', '', NULL, '賦得岸花臨水發 包融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a01291fb-dbf6-478b-a177-2e8bbb9c5584', '武陵桃源送人', '武陵桃源送人', 'c763e618-2c3a-47b7-a22a-2af2f7a12f1a', '唐', '["武陵川徑入幽遐，中有雞犬秦人家。","先時見者爲誰耶，源水今流桃復花。"]', '["武陵川徑入幽遐，中有雞犬秦人家。","先时见者爲誰耶，源水今流桃复花。"]', '诗', 'shi', '', NULL, '武陵桃源送人 包融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c17ce38-a6c8-4d25-8d82-f762b7c6b59d', '和薦福寺英公新搆禪堂', '和薦福寺英公新搆禪堂', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["上人久棄世，中道自忘筌。","寂照出羣有，了心清衆緣。","所以於此地，築館開青蓮。","果藥羅砌下，煙虹垂戶前。","咒中灑甘露，指處流香泉。","禪遠目無事，體清宵不眠。","枳聞廬山法，松入漢陽禪。","一枕西山外，虛舟常浩然。"]', '["上人久棄世，中道自忘筌。","寂照出羣有，了心清衆緣。","所以於此地，築館开青蓮。","果藥羅砌下，煙虹垂戶前。","咒中灑甘露，指处流香泉。","禪远目無事，體清宵不眠。","枳闻廬山法，松入漢陽禪。","一枕西山外，虛舟常浩然。"]', '诗', 'shi', '', NULL, '和薦福寺英公新搆禪堂 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d596b388-593f-43f7-aa91-e09e6fd59413', '贈朱中書', '贈朱中书', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["十年種田濱五湖，十年遭澇盡爲蕪。","頻年井稅常不足，今年緡錢誰爲輸。","東鄰轉穀五之利，西鄰販繒日已貴。","而我守道不遷業，誰能肯敢效此事。","紫微侍郎白虎殿，出入通籍迴天眷。","晨趨綵筆柏梁篇，晝出雕盤大官膳。","會應憐爾居素約，可即長年守貧賤。"]', '["十年種田濱五湖，十年遭澇尽爲蕪。","頻年井稅常不足，今年緡錢誰爲輸。","东鄰轉穀五之利，西鄰販繒日已貴。","而我守道不遷業，誰能肯敢效此事。","紫微侍郎白虎殿，出入通籍迴天眷。","晨趨綵笔柏梁篇，晝出雕盤大官膳。","會應怜爾居素約，可即长年守貧賤。"]', '诗', 'shi', '', NULL, '贈朱中書 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfb0ae5e-0ca1-48af-ac89-4ada2cc1f1f3', '戲贈姚侍御', '戲贈姚侍御', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["繁霜曉幕鳴柏烏，待子獸炭然金爐。","重門啟鎖紫髯胡，新披驄馬隴西駒。","頭戴獬豸急晨趨，明光殿前見天子，今日應彈佞倖夫。"]', '["繁霜晓幕鳴柏烏，待子獸炭然金爐。","重门啟鎖紫髯胡，新披驄马隴西駒。","头戴獬豸急晨趨，明光殿前见天子，今日應彈佞倖夫。"]', '诗', 'shi', '', NULL, '戲贈姚侍御 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6b5b537-3c6d-4c76-bb3d-c1f765308578', '餘杭醉歌贈吳山人', '餘杭醉歌贈吳山人', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["曉幕紅襟燕，春城白項烏。","只來梁上語，不向府中趨。","城頭坎坎鼓聲曙，滿庭新種櫻桃樹。","桃花昨夜撩亂開，當軒發色映樓臺。","十千兌得餘杭酒，二月春城長命杯。","酒後留君待明月，還將明月送君回。"]', '["晓幕紅襟燕，春城白項烏。","只来梁上語，不向府中趨。","城头坎坎鼓声曙，满庭新種櫻桃樹。","桃花昨夜撩亂开，當軒發色映楼台。","十千兌得餘杭酒，二月春城长命杯。","酒後留君待明月，還將明月送君回。"]', '诗', 'shi', '', NULL, '餘杭醉歌贈吳山人 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4145adde-b933-4175-8a83-b567f42e55cd', '京中守歲', '京中守歲', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["守歲多然燭，通宵莫掩扉。","客愁當暗滿，春色向明歸。","玉斗巡初匝，銀河落漸微。","開正獻歲酒，千里間庭闈。"]', '["守歲多然燭，通宵莫掩扉。","客愁當暗满，春色向明归。","玉斗巡初匝，銀河落漸微。","开正獻歲酒，千里间庭闈。"]', '诗', 'shi', '', NULL, '京中守歲 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5b38f6a-08a9-4942-ae35-5dd9f94304bf', '渡揚子江', '渡揚子江', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["桂檝中流望，空波兩畔明。","林開揚子驛，山出潤州城。","海盡邊陰靜，江寒朔吹生。","更聞風葉下，淅瀝度秋聲。"]', '["桂檝中流望，空波兩畔明。","林开揚子驛，山出潤州城。","海尽邊陰静，江寒朔吹生。","更闻风葉下，淅瀝度秋声。"]', '诗', 'shi', '', NULL, '渡揚子江 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ab5083b-3274-40a4-8c4c-1c5815f99470', '長寧公主舊山池', '长寧公主旧山池', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["平陽舊池館，寂寞使人愁。","座卷流黃簟，簾垂白玉鉤。","庭閑花自落，門閉水空流。","追想吹簫處，應隨仙鶴遊。"]', '["平陽旧池館，寂寞使人愁。","座卷流黄簟，簾垂白玉鉤。","庭闲花自落，门閉水空流。","追想吹簫处，應隨仙鹤游。"]', '诗', 'shi', '', NULL, '長寧公主舊山池 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5ee9ca8-b098-4217-9b6b-6d39355e2aba', '剡谿館聞笛', '剡谿館闻笛', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["夜久聞羗笛，寥寥虛客堂。","山空響不散，谿靜曲宜長。","草木生邊氣，城池泛夕涼。","虛然異風出，髣髴宿平陽。"]', '["夜久闻羗笛，寥寥虛客堂。","山空响不散，谿静曲宜长。","草木生邊氣，城池泛夕涼。","虛然異风出，髣髴宿平陽。"]', '诗', 'shi', '', NULL, '剡谿館聞笛 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a04e286d-365c-465f-be1e-6bd6497c38f9', '越裳貢白雉', '越裳貢白雉', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["聖哲承休運，伊夔列上台。","覃恩丹徼遠，入貢素翬來。","北闕欣初見，南枝顧未迴。","歛容殘雪淨，矯翼片雲開。","馴擾將無懼，翻飛幸不猜。","甘從上林裏，飲啄自徘徊。"]', '["聖哲承休運，伊夔列上台。","覃恩丹徼远，入貢素翬来。","北闕欣初见，南枝顧未迴。","歛容殘雪淨，矯翼片云开。","馴擾將無懼，翻飞幸不猜。","甘從上林裏，饮啄自徘徊。"]', '诗', 'shi', '', NULL, '越裳貢白雉 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('177a290b-ab04-46ac-a70e-6e8c3e1563d9', '江南曲五首 一', '江南曲五首 一', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["長干斜路北，近浦是兒家。","有意來相訪，明朝出浣紗。"]', '["长干斜路北，近浦是兒家。","有意来相訪，明朝出浣紗。"]', '诗', 'shi', '', NULL, '江南曲五首 一 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('749747c0-70c3-4cdf-b69f-c04b0f9a3c1a', '江南曲五首 二', '江南曲五首 二', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["發向橫塘口，船開值急流。","知郎舊時意，且請攏船頭。"]', '["發向橫塘口，船开值急流。","知郎旧时意，且請攏船头。"]', '诗', 'shi', '', NULL, '江南曲五首 二 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7af78fae-7826-4eeb-af76-0c6a4a3e9b8f', '江南曲五首 三', '江南曲五首 三', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["昨暝逗南陵，風聲波浪阻。","入浦不逢人，歸家誰信汝。"]', '["昨暝逗南陵，风声波浪阻。","入浦不逢人，归家誰信汝。"]', '诗', 'shi', '', NULL, '江南曲五首 三 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0db62e12-9ab8-44ca-beee-630539346037', '江南曲五首 四', '江南曲五首 四', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["未曉已成妝，乘潮去茫茫。","因從京口渡，使報邵陵王。"]', '["未晓已成妝，乘潮去茫茫。","因從京口渡，使報邵陵王。"]', '诗', 'shi', '', NULL, '江南曲五首 四 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a3f1a5a-ec6d-4d68-bc7c-1076f0e0b6c2', '江南曲五首 五', '江南曲五首 五', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["始下芙蓉樓，言發瑯琊岸。","急爲打船開，惡許傍人見。"]', '["始下芙蓉楼，言發瑯琊岸。","急爲打船开，惡許傍人见。"]', '诗', 'shi', '', NULL, '江南曲五首 五 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00c502e9-0d35-412a-87cd-9569751b56c6', '句', '句', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["窮花常閉戶，秋城聞搗衣。","樹迴早秋色，川長遲落暉。"]', '["窮花常閉戶，秋城闻捣衣。","樹迴早秋色，川长遲落暉。"]', '诗', 'shi', '', NULL, '句 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07e89d25-01be-46f0-a638-cd4456fc6276', '石橋琪樹', '石橋琪樹', 'fa507594-a886-4a2e-a16b-86dd052ee862', '唐', '["山上天將近，人間路漸遙。","誰當雲裏見，知欲渡仙橋。"]', '["山上天將近，人间路漸遙。","誰當云裏见，知欲渡仙橋。"]', '诗', 'shi', '', NULL, '石橋琪樹 蔡隱丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd7d8cf4-1601-4c21-9058-b47c99900863', '句', '句', 'fa507594-a886-4a2e-a16b-86dd052ee862', '唐', '["整巾千嶂聳，曳履百泉鳴。"]', '["整巾千嶂聳，曳履百泉鳴。"]', '诗', 'shi', '', NULL, '句 蔡隱丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ec575c9-fa85-4e55-81ae-b0fd03de06aa', '奉和扈從溫泉宮承恩賜浴', '奉和扈從溫泉宮承恩賜浴', 'a7f115ec-6e1f-4e5b-a5c3-b27d06ec50ae', '唐', '["天行雲從指驪宮，浴日餘波錫詔同。","綵殿氤氳擁香溜，紗窗宛轉閉和風。","來將蘭氣衝皇澤，去引星文捧碧空。","自憐遇坎便能止，願托仙槎路未通。"]', '["天行云從指驪宮，浴日餘波錫詔同。","綵殿氤氳擁香溜，紗窗宛轉閉和风。","来將蘭氣衝皇澤，去引星文捧碧空。","自怜遇坎便能止，願托仙槎路未通。"]', '诗', 'shi', '', NULL, '奉和扈從溫泉宮承恩賜浴 蔡希周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba63b5b7-5201-41f8-9d57-e2258a8d3d01', '同家兄題渭南王公別業', '同家兄題渭南王公別業', '181c8f3f-39df-4f86-8488-91810ee13064', '唐', '["好閑知在家，退跡何必深。","不出人境外，蕭條江海心。","軒車自來往，空名對清陰。","川涘將釣玉，鄉亭期散金。","素暉射流瀨，翠色緜森林。","曾爲詩書癖，寧惟耕稼任。","吾兄許微尚，枉道來相尋。","朝慶老萊服，夕閑安道琴。","文章遙頌美，寤寐增所欽。","既鬱蒼生望，明時豈陸沈。"]', '["好闲知在家，退跡何必深。","不出人境外，蕭條江海心。","軒车自来往，空名对清陰。","川涘將釣玉，乡亭期散金。","素暉射流瀨，翠色緜森林。","曾爲诗书癖，寧惟耕稼任。","吾兄許微尚，枉道来相尋。","朝慶老萊服，夕闲安道琴。","文章遙頌美，寤寐增所欽。","既鬱蒼生望，明时豈陸沈。"]', '诗', 'shi', '', NULL, '同家兄題渭南王公別業 蔡希寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8192f25-446d-4ab4-801f-6a095dd511b9', '登福先寺上方然公禪室', '登福先寺上方然公禪室', '181c8f3f-39df-4f86-8488-91810ee13064', '唐', '["名都標佛剎，梵構臨河干。","舉目上方峻，森森青翠攢。","步登諸劫盡，忽造浮雲端。","當暑敞扃闥，却嫌絺綌寒。","禪房最高頂，靜者殊閑安。","疎雨向空城，數峯簾外盤。","午鐘振衣坐，招我同一餐。","真味雜飴露，衆香唯茝蘭。","晚來恣偃俛，茶果仍留歡。"]', '["名都標佛剎，梵構臨河干。","舉目上方峻，森森青翠攢。","步登諸劫尽，忽造浮云端。","當暑敞扃闥，却嫌絺綌寒。","禪房最高頂，静者殊闲安。","疎雨向空城，數峯簾外盤。","午鐘振衣坐，招我同一餐。","真味杂飴露，衆香唯茝蘭。","晚来恣偃俛，茶果仍留歡。"]', '诗', 'shi', '', NULL, '登福先寺上方然公禪室 蔡希寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14f9b10b-83ed-407d-b6ab-90784434eda9', '陝中作', '陝中作', '181c8f3f-39df-4f86-8488-91810ee13064', '唐', '["西別秦關近，東行陝服長。","川原餘讓畔，歌吹憶遺棠。","河水流城下，山雲起路傍。","更憐棲泊處，池館繞林篁。"]', '["西別秦关近，东行陝服长。","川原餘讓畔，歌吹憶遺棠。","河水流城下，山云起路傍。","更怜棲泊处，池館繞林篁。"]', '诗', 'shi', '', NULL, '陝中作 蔡希寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a866c5e-cec4-4ae5-ba65-010f97788cde', '洛陽客舍逢祖詠留宴', '洛陽客舍逢祖詠留宴', '181c8f3f-39df-4f86-8488-91810ee13064', '唐', '["緜緜鐘漏洛陽城，客舍貧居絕送迎。","逢君貰酒因成醉，醉後焉知世上情。"]', '["緜緜鐘漏洛陽城，客舍貧居絕送迎。","逢君貰酒因成醉，醉後焉知世上情。"]', '诗', 'shi', '', NULL, '洛陽客舍逢祖詠留宴 蔡希寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('210e4b4a-f6b8-4761-8dba-9e3ff50293d8', '贈張敬微', '贈張敬微', '181c8f3f-39df-4f86-8488-91810ee13064', '唐', '["大河東北望桃林，雜樹冥冥結翠陰。","不知君作神仙尉，特訝行來雲霧深。"]', '["大河东北望桃林，杂樹冥冥結翠陰。","不知君作神仙尉，特訝行来云霧深。"]', '诗', 'shi', '', NULL, '贈張敬微 蔡希寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08b9dea0-7e08-4ae3-a558-5db3ebaa8d9f', '江風行', '江风行', '9087015e-af3e-4a1b-8b16-7c5d8331d190', '唐', '["壻貧如珠玉，壻富如埃塵。","貧時不忘舊，富日多寵新。","妾本富家女，與君爲偶匹。","惠好一何深，中門不曾出。","妾有繡衣裳，葳蕤金縷光。","念君貧且賤，易此從遠方。","遠方三千里，思君心未已。","日暮情更來，空望去時水。","孟夏麥始秀，江上多南風。","商賈歸欲盡，君今尚巴東。","巴東有巫山，窈窕神女顏。","常恐遊此方，果然不知還。"]', '["壻貧如珠玉，壻富如埃塵。","貧时不忘旧，富日多寵新。","妾本富家女，與君爲偶匹。","惠好一何深，中门不曾出。","妾有繡衣裳，葳蕤金縷光。","念君貧且賤，易此從远方。","远方三千里，思君心未已。","日暮情更来，空望去时水。","孟夏麦始秀，江上多南风。","商賈归欲尽，君今尚巴东。","巴东有巫山，窈窕神女顏。","常恐游此方，果然不知還。"]', '诗', 'shi', '', NULL, '江風行 張潮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fe8fb13-d2f7-4f59-9cc0-d4b52d2c6b8b', '襄陽行', '襄陽行', '9087015e-af3e-4a1b-8b16-7c5d8331d190', '唐', '["玉盤轉明珠，君心無定準。","昨見襄陽客，剩說襄陽好無盡。","襄漢水，峴山垂，漢水東流風北吹。","只言一世長嬌寵，那悟今朝見別離。","君渡清羗渚，知人獨不語。","妾見鳥棲林，憶君相思深。","莫作雲間鴻，離聲顧儔侶。","尚如匣中劒，分形會同處。","是君婦，識君情，怨君恨君爲此行。","下牀一宿不可保，況乃萬里襄陽城。","襄陽傳近大堤北，君到襄陽莫回惑。","大堤諸女兒，憐錢不憐德。"]', '["玉盤轉明珠，君心無定準。","昨见襄陽客，剩说襄陽好無尽。","襄漢水，峴山垂，漢水东流风北吹。","只言一世长嬌寵，那悟今朝见別離。","君渡清羗渚，知人独不語。","妾见鸟棲林，憶君相思深。","莫作云间鴻，離声顧儔侶。","尚如匣中劒，分形會同处。","是君婦，識君情，怨君恨君爲此行。","下牀一宿不可保，況乃万里襄陽城。","襄陽傳近大堤北，君到襄陽莫回惑。","大堤諸女兒，怜錢不怜德。"]', '诗', 'shi', '', NULL, '襄陽行 張潮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('127c8d97-6aa4-4bfe-bbb8-b73e6c984cee', '采蓮詞', '采蓮词', '9087015e-af3e-4a1b-8b16-7c5d8331d190', '唐', '["朝出沙頭日正紅，晚來雲起半江中。","賴逢鄰女曾相識，並著蓮舟不畏風。"]', '["朝出沙头日正紅，晚来云起半江中。","賴逢鄰女曾相識，並著蓮舟不畏风。"]', '诗', 'shi', '', NULL, '采蓮詞 張潮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('501fed64-f4bf-40aa-8e79-b15610ecaa0a', '江南行', '江南行', '9087015e-af3e-4a1b-8b16-7c5d8331d190', '唐', '["茨菰葉爛別西灣，蓮子花開猶未還。","妾夢不離江水上，人傳郎在鳳凰山。"]', '["茨菰葉爛別西灣，蓮子花开猶未還。","妾梦不離江水上，人傳郎在鳳凰山。"]', '诗', 'shi', '', NULL, '江南行 張潮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fefba2a-49be-45fc-9575-166b0567930e', '長干行', '长干行', '9087015e-af3e-4a1b-8b16-7c5d8331d190', '唐', '["憶昔深閨裏，煙塵不曾識。","嫁與長干人，沙頭候風色。","五月南風興，思君下巴陵。","八月西風起，想君發[揚]子。","去來悲如何，見少離別多。","湘潭幾日到，妾夢越風波。","昨夜狂風度，吹折江頭樹。","淼淼暗無邊，行人在何處。","北客真三公，朱衣滿江中。","薄暮來投宿，數朝不肯東。","好乘浮雲驄，佳期蘭渚東。","鴛鴦綠浦上，翡翠錦屏中。","自憐十五餘，顏色桃花紅。","那作商人婦，愁水復愁風。"]', '["憶昔深閨裏，煙塵不曾識。","嫁與长干人，沙头候风色。","五月南风兴，思君下巴陵。","八月西风起，想君發[揚]子。","去来悲如何，见少離別多。","湘潭幾日到，妾梦越风波。","昨夜狂风度，吹折江头樹。","淼淼暗無邊，行人在何处。","北客真三公，朱衣满江中。","薄暮来投宿，數朝不肯东。","好乘浮云驄，佳期蘭渚东。","鴛鴦綠浦上，翡翠錦屏中。","自怜十五餘，顏色桃花紅。","那作商人婦，愁水复愁风。"]', '诗', 'shi', '', NULL, '長干行 張潮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf892243-b038-4aca-a78d-30114fcb1125', '句', '句', '9087015e-af3e-4a1b-8b16-7c5d8331d190', '唐', '["寒林苞晚橘，風絮露垂楊。"]', '["寒林苞晚橘，风絮露垂楊。"]', '诗', 'shi', '', NULL, '句 張潮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92f9905a-855c-40c1-ac2a-854b61b1566d', '遊棲霞寺', '游棲霞寺', '228d7b43-01db-4fd9-88d2-d31627d5c0db', '唐', '["躋險入幽林，翠微含竹殿。","泉聲無休歇，山色時隱見。","潮來雜風雨，梅落成霜霰。","一從方外遊，頓覺塵心變。"]', '["躋險入幽林，翠微含竹殿。","泉声無休歇，山色时隐见。","潮来杂风雨，梅落成霜霰。","一從方外游，頓覺塵心变。"]', '诗', 'shi', '', NULL, '遊棲霞寺 張翬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a7136ae-e46a-48fe-818a-3ccd4538fa2e', '絕句', '絕句', '228d7b43-01db-4fd9-88d2-d31627d5c0db', '唐', '["茫茫煙上水，日暮陰雲飛。","孤坐正愁緒，湖南誰擣衣。"]', '["茫茫煙上水，日暮陰云飞。","孤坐正愁緒，湖南誰擣衣。"]', '诗', 'shi', '', NULL, '絕句 張翬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eed79f1-49ed-4848-8df8-7f77613f00b4', '潘司馬別業', '潘司马別業', 'b313fd54-cf04-44a1-ba94-2c333106c03d', '唐', '["門對青山近，汀牽綠草長。","寒深包晚橘，風緊落垂楊。","湖畔聞漁唱，天邊數鴈行。","蕭然有高士，清思滿書堂。"]', '["门对青山近，汀牽綠草长。","寒深包晚橘，风緊落垂楊。","湖畔闻漁唱，天邊數鴈行。","蕭然有高士，清思满书堂。"]', '诗', 'shi', '', NULL, '潘司馬別業 周瑀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4880b25c-7b97-489c-adc7-68049ef84083', '送潘三入京', '送潘三入京', 'b313fd54-cf04-44a1-ba94-2c333106c03d', '唐', '["故人嗟此別，相送出煙坰。","柳色分官路，荷香入水亭。","離歌未盡曲，酌酒共忘形。","把手河橋上，孤山日暮青。"]', '["故人嗟此別，相送出煙坰。","柳色分官路，荷香入水亭。","離歌未尽曲，酌酒共忘形。","把手河橋上，孤山日暮青。"]', '诗', 'shi', '', NULL, '送潘三入京 周瑀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86c29e00-f2a1-4f6c-a94e-b0e34c2cff6f', '臨川山行', '臨川山行', 'b313fd54-cf04-44a1-ba94-2c333106c03d', '唐', '["朝見青山雪，暮見青山雲。","雲山無斷絕，秋思日紛紛。"]', '["朝见青山雪，暮见青山云。","云山無斷絕，秋思日紛紛。"]', '诗', 'shi', '', NULL, '臨川山行 周瑀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74b8473f-9ca2-436f-a3d7-cd0e4acfa909', '清谿館作', '清谿館作', 'e88554f4-2198-48f2-a7ef-815f221991d0', '唐', '["指途清谿裏，左右唯深林。","雲蔽望鄉處，雨愁爲客心。","遇人多物役，聽鳥時幽音。","何必滄浪水，庶茲浣塵襟。"]', '["指途清谿裏，左右唯深林。","云蔽望乡处，雨愁爲客心。","遇人多物役，听鸟时幽音。","何必滄浪水，庶茲浣塵襟。"]', '诗', 'shi', '', NULL, '清谿館作 談戭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('785e8cf2-185e-4843-b539-7bae8c4e64b8', '句', '句', 'e88554f4-2198-48f2-a7ef-815f221991d0', '唐', '["清清江潭樹，日夕增所思。"]', '["清清江潭樹，日夕增所思。"]', '诗', 'shi', '', NULL, '句 談戭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f67279c0-fbec-4a62-a5be-16f1c58eb60f', '塞上', '塞上', '929a09b1-ba43-4245-a8e7-af95eda1cd9f', '唐', '["萬里隤城在，三邊虜氣衰。","沙填孤嶂角，燒斷故關碑。","馬色經寒慘，鵰聲帶晚悲。","將軍正閑暇，留客換歌辭。"]', '["万里隤城在，三邊虜氣衰。","沙填孤嶂角，燒斷故关碑。","马色經寒慘，鵰声带晚悲。","將軍正闲暇，留客換歌辞。"]', '诗', 'shi', '', NULL, '塞上 殷遙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88a6a7aa-6a5b-4ce9-9b51-9187cf3a5a76', '送友人下第歸省', '送友人下第归省', '929a09b1-ba43-4245-a8e7-af95eda1cd9f', '唐', '["君此卜行日，高堂應夢歸。","莫將和氏淚，滴著老萊衣。","嶽雨連河細，田禽出麥飛。","到家調膳後，吟好送斜暉。"]', '["君此卜行日，高堂應梦归。","莫將和氏泪，滴著老萊衣。","嶽雨連河細，田禽出麦飞。","到家調膳後，吟好送斜暉。"]', '诗', 'shi', '', NULL, '送友人下第歸省 殷遙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29601924-1af4-441b-9a95-9d59e3ea20f7', '送杜士瞻楚州覲省', '送杜士瞻楚州覲省', '929a09b1-ba43-4245-a8e7-af95eda1cd9f', '唐', '["風流與才思，俱似晉時人。","淮月歸心促，江花入興新。","雲深蒼海暮，柳暗白門春。","共道官猶小，憐君孝養親。"]', '["风流與才思，俱似晉时人。","淮月归心促，江花入兴新。","云深蒼海暮，柳暗白门春。","共道官猶小，怜君孝養親。"]', '诗', 'shi', '', NULL, '送杜士瞻楚州覲省 殷遙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6565de4f-4eb4-4645-9ec4-e49462bbcbb7', '友人山亭', '友人山亭', '929a09b1-ba43-4245-a8e7-af95eda1cd9f', '唐', '["故人雖薄宦，往往涉清溪。","鑿牖對山月，褰裳拂澗霓。","遊魚逆水上，宿鳥向風棲。","一見桃花發，能令秦漢迷。"]', '["故人雖薄宦，往往涉清溪。","鑿牖对山月，褰裳拂澗霓。","游鱼逆水上，宿鸟向风棲。","一见桃花發，能令秦漢迷。"]', '诗', 'shi', '', NULL, '友人山亭 殷遙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57cc79ae-2171-4b30-8834-1ca6e7fdb865', '春晚山行', '春晚山行', '929a09b1-ba43-4245-a8e7-af95eda1cd9f', '唐', '["寂歷青山晚，山行趣不稀。","野花成子落，江燕引雛飛。","暗草薰苔徑，晴楊掃石磯。","俗人猶語此，余亦轉忘歸。"]', '["寂歷青山晚，山行趣不稀。","野花成子落，江燕引雛飞。","暗草薰苔徑，晴楊掃石磯。","俗人猶語此，余亦轉忘归。"]', '诗', 'shi', '', NULL, '春晚山行 殷遙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceac2818-1ba1-44a5-aafd-22c93a3309b4', '寄張徵古', '寄張徵古', '5b5ff452-a12b-43af-802f-ab8218c6c9e6', '唐', '["寂歷遠山意，微冥半空碧。","綠蘿無冬春，彩雲竟朝夕。","張子海內奇，久爲巖中客。","聖君當夢想，安得老松石。"]', '["寂歷远山意，微冥半空碧。","綠蘿無冬春，彩云竟朝夕。","張子海內奇，久爲巖中客。","聖君當梦想，安得老松石。"]', '诗', 'shi', '', NULL, '寄張徵古 沈如筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f26ce3f-5ee1-4ee8-86ff-5518745202b7', '閨怨二首 一', '閨怨二首 一', '5b5ff452-a12b-43af-802f-ab8218c6c9e6', '唐', '["鴈盡書難寄，愁多夢不成。","願隨孤月影，流照伏波營。"]', '["鴈尽书难寄，愁多梦不成。","願隨孤月影，流照伏波營。"]', '诗', 'shi', '', NULL, '閨怨二首 一 沈如筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaa74fb2-a2e1-460e-86a0-e00d5b78066b', '閨怨二首 二', '閨怨二首 二', '5b5ff452-a12b-43af-802f-ab8218c6c9e6', '唐', '["隴底嗟長別，流襟一動君。","何言幽咽所，更作死生分。"]', '["隴底嗟长別，流襟一动君。","何言幽咽所，更作死生分。"]', '诗', 'shi', '', NULL, '閨怨二首 二 沈如筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d3e6ed1-b1fe-4cca-ad4e-7e4b7ad61d9c', '寄天台司馬道士', '寄天台司马道士', '5b5ff452-a12b-43af-802f-ab8218c6c9e6', '唐', '["河洲花豔爚，庭樹光彩蒨。","白雲天台山，可思不可見。"]', '["河洲花豔爚，庭樹光彩蒨。","白云天台山，可思不可见。"]', '诗', 'shi', '', NULL, '寄天台司馬道士 沈如筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f52b1bcf-63cb-47a5-915e-ce13083964e2', '句', '句', '5b5ff452-a12b-43af-802f-ab8218c6c9e6', '唐', '["思酸寒鴈斷，淅瀝秋樹空。","漁陽燕舊都，美女花不如。"]', '["思酸寒鴈斷，淅瀝秋樹空。","漁陽燕旧都，美女花不如。"]', '诗', 'shi', '', NULL, '句 沈如筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fc9de56-4aca-4cbb-8abe-4cfcdb96d3a6', '詠黃鶯', '詠黄鶯', 'ff872886-34c2-434f-bd91-add5eb426b0e', '唐', '["欲囀聲猶澀，將飛羽未調。","高風不借便，何處得遷喬。"]', '["欲囀声猶澀，將飞羽未調。","高风不借便，何处得遷喬。"]', '诗', 'shi', '', NULL, '詠黃鶯 孫處玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('197bdcd7-6fc5-4644-a965-96cafe102d90', '失題', '失題', 'ff872886-34c2-434f-bd91-add5eb426b0e', '唐', '["漢家輕壯士，無狀殺彭王。","一遇風塵起，令誰守四方。"]', '["漢家轻壯士，無狀殺彭王。","一遇风塵起，令誰守四方。"]', '诗', 'shi', '', NULL, '失題 孫處玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca20df22-e548-4a99-9f4c-1f78d0c301f5', '句', '句', 'ff872886-34c2-434f-bd91-add5eb426b0e', '唐', '["殘花與露落，墮葉隨風翻。","日側南澗幽，風凝北林暮。"]', '["殘花與露落，墮葉隨风翻。","日側南澗幽，风凝北林暮。"]', '诗', 'shi', '', NULL, '句 孫處玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c4b7c86-882b-4525-a284-f3b3812546d4', '折楊柳', '折楊柳', '9efe6b62-2ed4-4ca7-b582-e148c9ba907e', '唐', '["大道連國門，東西種楊柳。","葳蕤君不見，嫋娜垂來久。","緣枝棲暝禽，雄去雌獨吟。","餘花怨春盡，微月起秋陰。","坐望窗中蝶，起攀枝上葉。","好風吹長條，婀娜何如妾。","妾見柳園新，高樓四五春。","莫吹胡塞曲，愁殺隴頭人。"]', '["大道連国门，东西種楊柳。","葳蕤君不见，嫋娜垂来久。","緣枝棲暝禽，雄去雌独吟。","餘花怨春尽，微月起秋陰。","坐望窗中蝶，起攀枝上葉。","好风吹长條，婀娜何如妾。","妾见柳园新，高楼四五春。","莫吹胡塞曲，愁殺隴头人。"]', '诗', 'shi', '', NULL, '折楊柳 徐延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57f3cd85-28f7-47ba-accb-b9d2b7d10f1d', '南州行', '南州行', '9efe6b62-2ed4-4ca7-b582-e148c9ba907e', '唐', '["搖艇至南國，國門連大江。","中洲西邊岸，數步一垂楊。","金釧越溪女，羅衣胡粉香。","織縑春卷幔，采蕨暝提筐。","弄瑟嬌垂幌，迎人笑下堂。","河頭浣衣處，無數紫鴛鴦。"]', '["搖艇至南国，国门連大江。","中洲西邊岸，數步一垂楊。","金釧越溪女，羅衣胡粉香。","织縑春卷幔，采蕨暝提筐。","弄瑟嬌垂幌，迎人笑下堂。","河头浣衣处，無數紫鴛鴦。"]', '诗', 'shi', '', NULL, '南州行 徐延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d7bd64d-8899-4188-80fe-58b3a0063af2', '人日剪綵', '人日剪綵', '9efe6b62-2ed4-4ca7-b582-e148c9ba907e', '唐', '["閨婦持刀坐，自憐裁剪新。","葉催情綴色，花寄手成春。","帖燕留妝戶，黏雞待餉人。","擎來問夫壻，何處不如真。"]', '["閨婦持刀坐，自怜裁剪新。","葉催情綴色，花寄手成春。","帖燕留妝戶，黏雞待餉人。","擎来问夫壻，何处不如真。"]', '诗', 'shi', '', NULL, '人日剪綵 徐延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05548d45-5c9e-475e-bd89-e10dbf89a995', '南中感懷', '南中感懷', '987f1566-fec9-41de-af4d-e1441f78a8e9', '唐', '["南路磋跎客未回，常嗟物候暗相催。","四時不變江頭草，十月先開嶺上梅。"]', '["南路磋跎客未回，常嗟物候暗相催。","四时不变江头草，十月先开嶺上梅。"]', '诗', 'shi', '', NULL, '南中感懷 樊晃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8928ce05-1d1d-4a58-a334-f4f8b624e6b8', '句', '句', '987f1566-fec9-41de-af4d-e1441f78a8e9', '唐', '["巧裁蟬鬢畏風吹，盡作蛾眉恐人妒。"]', '["巧裁蟬鬢畏风吹，尽作蛾眉恐人妒。"]', '诗', 'shi', '', NULL, '句 樊晃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e4c5e1e-96f2-4339-9789-4e45f6f170ba', '和戶部楊員外伯成寓直', '和戶部楊員外伯成寓直', 'd5b6cb75-8dc3-452a-a303-dc6311a94503', '唐', '["落日彌綸地，公才畫省郎。","詞驚起草筆，坐引護衣香。","雙闕天河近，千門夕漏長。","遙知臺上宿，不獨有文強。"]', '["落日彌綸地，公才畫省郎。","词驚起草笔，坐引護衣香。","雙闕天河近，千门夕漏长。","遙知台上宿，不独有文強。"]', '诗', 'shi', '', NULL, '和戶部楊員外伯成寓直 李憕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d10809a9-e7c1-4d27-8759-b4b32fe17fd4', '同望幸新亭賜錢公宴', '同望幸新亭賜錢公宴', 'd5b6cb75-8dc3-452a-a303-dc6311a94503', '唐', '["感夢通玄化，覃恩降紫宸。","賜錢開漢府，分帛醉堯人。","地隔朝宗慶，亭臨卜洛新。","行看廣雲雨，二月次東巡。"]', '["感梦通玄化，覃恩降紫宸。","賜錢开漢府，分帛醉堯人。","地隔朝宗慶，亭臨卜洛新。","行看廣云雨，二月次东巡。"]', '诗', 'shi', '', NULL, '同望幸新亭賜錢公宴 李憕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7074ac6-6297-4761-ba43-5b3e76de300c', '奉和聖製從蓬萊向興慶閣道中留春雨中春望之作應制', '奉和聖製從蓬萊向兴慶閣道中留春雨中春望之作應制', 'd5b6cb75-8dc3-452a-a303-dc6311a94503', '唐', '["別館春還淑氣催，三宮路轉鳳皇臺。","雲飛北闕輕陰散，雨歇南山積翠來。","御柳遙隨天仗發，林花不待曉風開。","已知聖澤深無限，更喜年芳入睿才。"]', '["別館春還淑氣催，三宮路轉鳳皇台。","云飞北闕轻陰散，雨歇南山積翠来。","御柳遙隨天仗發，林花不待晓风开。","已知聖澤深無限，更喜年芳入睿才。"]', '诗', 'shi', '', NULL, '奉和聖製從蓬萊向興慶閣道中留春雨中春望之作應制 李憕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a58b5cf-8779-4148-b8eb-e5dd3cad0594', '銅雀妓', '銅雀妓', 'f48b5408-126d-4e8d-af9c-3d91a7c24766', '唐', '["西陵望何及，弦管徒在茲。","誰言死者樂，但令生者悲。","丈夫有餘志，兒女焉足私。","擾擾多俗情，投迹互相師。","直節豈感激，荒淫乃淒其。","潁水有許由，西山有伯夷。","頌聲何寥寥，唯聞銅雀詩。","君舉良未易，永爲後代嗤。"]', '["西陵望何及，弦管徒在茲。","誰言死者乐，但令生者悲。","丈夫有餘志，兒女焉足私。","擾擾多俗情，投迹互相師。","直節豈感激，荒淫乃淒其。","潁水有許由，西山有伯夷。","頌声何寥寥，唯闻銅雀诗。","君舉良未易，永爲後代嗤。"]', '诗', 'shi', '', NULL, '銅雀妓 李邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('902a9ae8-7f5f-4a23-9204-52aa739e7c12', '詠雲', '詠云', 'f48b5408-126d-4e8d-af9c-3d91a7c24766', '唐', '["綵雲驚歲晚，繚繞孤山頭。","散作五般色，凝爲一段愁。","影雖沈澗底，形在天際遊。","風動必飛去，不應長此留。"]', '["綵云驚歲晚，繚繞孤山头。","散作五般色，凝爲一段愁。","影雖沈澗底，形在天際游。","风动必飞去，不應长此留。"]', '诗', 'shi', '', NULL, '詠雲 李邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d213db65-8a6b-4c37-a5e5-798519744192', '登歷下古城員外孫新亭', '登歷下古城員外孫新亭', 'f48b5408-126d-4e8d-af9c-3d91a7c24766', '唐', '["吾宗固神秀，體物寫謀長。","形制開古跡，曾冰延樂方。","太山雄地理，巨壑眇雲莊。","高興汨煩促，永懷清典常。","含弘知四大，出入見三光。","負郭喜秔稻，安時歌吉祥。"]', '["吾宗固神秀，體物寫謀长。","形制开古跡，曾冰延乐方。","太山雄地理，巨壑眇云莊。","高兴汨煩促，永懷清典常。","含弘知四大，出入见三光。","負郭喜秔稻，安时歌吉祥。"]', '诗', 'shi', '', NULL, '登歷下古城員外孫新亭 李邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe2277d7-42fb-4069-b4d2-c69887a0b629', '奉和初春幸太平公主南莊應制', '奉和初春幸太平公主南莊應制', 'f48b5408-126d-4e8d-af9c-3d91a7c24766', '唐', '["傳聞銀漢支機石，復見金輿出紫微。","織女橋邊烏鵲起，仙人樓上鳳皇飛。","流風入座飄歌扇，瀑水侵階濺舞衣。","今日還同犯牛斗，乘槎共逐海潮歸。"]', '["傳闻銀漢支機石，复见金輿出紫微。","织女橋邊烏鵲起，仙人楼上鳳皇飞。","流风入座飄歌扇，瀑水侵階濺舞衣。","今日還同犯牛斗，乘槎共逐海潮归。"]', '诗', 'shi', '', NULL, '奉和初春幸太平公主南莊應制 李邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4c75dc6-6c7d-4141-a878-7d8786d4bebb', '奉使登終南山', '奉使登終南山', '006ee8e4-f29d-4ced-8e5c-b9392f9d8b26', '唐', '["常愛南山遊，因而盡原隰。","數朝至林嶺，百仞登嵬岌。","石壯馬徑窮，苔色步緣入。","物奇春狀改，氣遠天香集。","虛洞策杖鳴，低雲拂衣濕。","倚巖見廬舍，入戶欣拜揖。","問性矜勤勞，示心教澄習。","玉英時共飯，芝草爲余拾。","境絕人不行，潭深鳥空立。","一乘從此授，九轉兼是給。","辭處若輕飛，憩來唯吐吸。","閑襟超已勝，迴路倏而及。","煙色松上深，水流山下急。","漸平逢車騎，向晚睨城邑。","峯在野趣繁，塵飄宦情澁。","辛苦久爲吏，勞生何妄執。","日暮懷此山，悠然賦斯什。"]', '["常愛南山游，因而尽原隰。","數朝至林嶺，百仞登嵬岌。","石壯马徑窮，苔色步緣入。","物奇春狀改，氣远天香集。","虛洞策杖鳴，低云拂衣濕。","倚巖见廬舍，入戶欣拜揖。","问性矜勤勞，示心教澄習。","玉英时共飯，芝草爲余拾。","境絕人不行，潭深鸟空立。","一乘從此授，九轉兼是給。","辞处若轻飞，憩来唯吐吸。","闲襟超已勝，迴路倏而及。","煙色松上深，水流山下急。","漸平逢车騎，向晚睨城邑。","峯在野趣繁，塵飄宦情澁。","辛苦久爲吏，勞生何妄執。","日暮懷此山，悠然賦斯什。"]', '诗', 'shi', '', NULL, '奉使登終南山 王灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f25a9d9e-3d21-4565-af59-e4e97bd1eed1', '晚夏馬嵬卿叔池亭即事寄京都一二知己', '晚夏马嵬卿叔池亭即事寄京都一二知己', '006ee8e4-f29d-4ced-8e5c-b9392f9d8b26', '唐', '["忝職畿甸淹，濫陪時俊後。","才輕策疲劣，勢薄常驅走。","牽役勞風塵，秉心在巖藪。","宗賢開別業，形勝代希偶。","竹繞清渭濱，泉流白渠口。","逡巡期賞會，揮忽變星斗。","逮此乘務閑，因而訪幽叟。","入來殊景物，行復洗紛垢。","林靜秋色多，潭深月光厚。","盛香蓮近拆，新味瓜初剖。","滯拙懷隱淪，書之寄良友。"]', '["忝職畿甸淹，濫陪时俊後。","才轻策疲劣，勢薄常驱走。","牽役勞风塵，秉心在巖藪。","宗賢开別業，形勝代希偶。","竹繞清渭濱，泉流白渠口。","逡巡期賞會，揮忽变星斗。","逮此乘務闲，因而訪幽叟。","入来殊景物，行复洗紛垢。","林静秋色多，潭深月光厚。","盛香蓮近拆，新味瓜初剖。","滯拙懷隐淪，书之寄良友。"]', '诗', 'shi', '', NULL, '晚夏馬嵬卿叔池亭即事寄京都一二知己 王灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('076db65b-9bc5-42e9-b146-28e50e39fc50', '麗正殿賜宴同勒天前煙年四韻應制', '丽正殿賜宴同勒天前煙年四韻應制', '006ee8e4-f29d-4ced-8e5c-b9392f9d8b26', '唐', '["金殿忝陪賢，瓊羞忽降天。","鼎羅仙掖裏，觴拜瑣闈前。","院逼青霄路，廚和紫禁煙。","酒酣空忭舞，何以荅昌年。"]', '["金殿忝陪賢，瓊羞忽降天。","鼎羅仙掖裏，觴拜瑣闈前。","院逼青霄路，廚和紫禁煙。","酒酣空忭舞，何以荅昌年。"]', '诗', 'shi', '', NULL, '麗正殿賜宴同勒天前煙年四韻應制 王灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31df5224-a5fc-449d-ad93-17de30f6e9cc', '奉和賀監林月清酌', '奉和賀監林月清酌', '006ee8e4-f29d-4ced-8e5c-b9392f9d8b26', '唐', '["華月當秋滿，朝英假興同。","淨林新霽入，規院小涼通。","碎影行筵裏，搖花落酒中。","清宵凝爽意，倂此助文雄。"]', '["华月當秋满，朝英假兴同。","淨林新霽入，規院小涼通。","碎影行筵裏，搖花落酒中。","清宵凝爽意，倂此助文雄。"]', '诗', 'shi', '', NULL, '奉和賀監林月清酌 王灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bb5c590-5de8-4bfb-aee6-30bc4bcdf99a', '次北固山下', '次北固山下', '006ee8e4-f29d-4ced-8e5c-b9392f9d8b26', '唐', '["客路青山外，行舟綠水前。","潮平兩岸闊，風正一帆懸。","海日生殘夜，江春入舊年。","鄉書何處達，歸雁洛陽邊。"]', '["客路青山外，行舟綠水前。","潮平兩岸闊，风正一帆懸。","海日生殘夜，江春入旧年。","乡书何处達，归雁洛陽邊。"]', '诗', 'shi', '', NULL, '次北固山下 王灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea4b6d44-baf2-4afc-9554-c48284940ccc', '觀搊箏', '观搊箏', '006ee8e4-f29d-4ced-8e5c-b9392f9d8b26', '唐', '["虛室有秦箏，箏新月復清。","弦多弄委曲，柱促語分明。","曉怨凝繁手，春嬌入曼聲。","近來唯此樂，傳得美人情。"]', '["虛室有秦箏，箏新月复清。","弦多弄委曲，柱促語分明。","晓怨凝繁手，春嬌入曼声。","近来唯此乐，傳得美人情。"]', '诗', 'shi', '', NULL, '觀搊箏 王灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2db81524-6e32-4f96-b553-86b51abc429a', '晚春詣蘇州敬贈武員外', '晚春詣蘇州敬贈武員外', '006ee8e4-f29d-4ced-8e5c-b9392f9d8b26', '唐', '["蘇臺憶季常，飛櫂歷江鄉。","持此功曹掾，初離華省郎。","貴門生禮樂，明代秉文章。","嘉郡位先進，鴻儒名重揚。","爰從姻婭貶，豈失忠信防。","萬里行驥足，十年暌鳳翔。","迴遷翊元聖，入拜佇惟良。","別業對南浦，羣書滿北堂。","意深投轄盛，才重接筵光。","陋學叨鉛簡，弱齡許翰場。","神馳勞舊國，顏展別殊方。","際曉雜氛散，殘春衆物芳。","煙和疎樹滿，雨續小谿長。","旅拙感成慰，通賢顧不忘。","從來琴曲罷，開匣爲君張。"]', '["蘇台憶季常，飞櫂歷江乡。","持此功曹掾，初離华省郎。","貴门生禮乐，明代秉文章。","嘉郡位先進，鴻儒名重揚。","爰從姻婭貶，豈失忠信防。","万里行驥足，十年暌鳳翔。","迴遷翊元聖，入拜佇惟良。","別業对南浦，羣书满北堂。","意深投轄盛，才重接筵光。","陋学叨鉛簡，弱齡許翰場。","神驰勞旧国，顏展別殊方。","際晓杂氛散，殘春衆物芳。","煙和疎樹满，雨續小谿长。","旅拙感成慰，通賢顧不忘。","從来琴曲罷，开匣爲君張。"]', '诗', 'shi', '', NULL, '晚春詣蘇州敬贈武員外 王灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebfa17b6-afc5-4123-81cd-62f7f9625597', '秋夜寓直即事懷贈蕭令公裴侍郎兼通簡南省諸友人', '秋夜寓直即事懷贈蕭令公裴侍郎兼通簡南省諸友人', '006ee8e4-f29d-4ced-8e5c-b9392f9d8b26', '唐', '["聖主萬年興，賢臣數載升。","古靈傳嶽秀，宏量稟川澄。","畿甸舉長策，風霜秉直繩。","出車遙俗震，登閣滿朝稱。","賦簡流亡輯，農安政理憑。","還家新長幼，巡壠舊溝塍。","忠梗大勛立，寰瀛墮業懲。","焚香兼御史，懸鏡委中丞。","旟隼當朝立，臺驄發郡乘。","司徒漢家重，國典潁川徵。","雲路俄平入，台階忽上凌。","秉鈞調造化，宣綍慰黎烝。","金省方秋作，瑤軒直夜凭。","中書贈陳準，右相簡王陵。","三傑賢更穆，百僚歡且兢。","搖懷及賓友，計曲辨淄澠。","閶闔暝陰散，鉤陳爽氣凝。","月深宮樹轉，河近禁樓冰。","卑吏夙驅策，微涓效斗升。","望麾宵繼火，書板曙懷蒸。","彼此雖流盼，規模轉服膺。","惠將霄漢隔，勞或歲時矜。","位重恩寧濫，才輕懾不勝。","林巒甘獨往，疵賤苦相仍。","敢忘銜花雀，思同附驥蠅。","平生逐鳥雀，何日嗣蒼鷹。"]', '["聖主万年兴，賢臣數載升。","古靈傳嶽秀，宏量稟川澄。","畿甸舉长策，风霜秉直繩。","出车遙俗震，登閣满朝稱。","賦簡流亡輯，農安政理憑。","還家新长幼，巡壠旧溝塍。","忠梗大勛立，寰瀛墮業懲。","焚香兼御史，懸镜委中丞。","旟隼當朝立，台驄發郡乘。","司徒漢家重，国典潁川徵。","云路俄平入，台階忽上凌。","秉鈞調造化，宣綍慰黎烝。","金省方秋作，瑤軒直夜凭。","中书贈陳準，右相簡王陵。","三傑賢更穆，百僚歡且兢。","搖懷及賓友，計曲辨淄澠。","閶闔暝陰散，鉤陳爽氣凝。","月深宮樹轉，河近禁楼冰。","卑吏夙驱策，微涓效斗升。","望麾宵繼火，书板曙懷蒸。","彼此雖流盼，規模轉服膺。","惠將霄漢隔，勞或歲时矜。","位重恩寧濫，才轻懾不勝。","林巒甘独往，疵賤苦相仍。","敢忘銜花雀，思同附驥蠅。","平生逐鸟雀，何日嗣蒼鷹。"]', '诗', 'shi', '', NULL, '秋夜寓直即事懷贈蕭令公裴侍郎兼通簡南省諸友人 王灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e88124ec-8947-407d-a166-3888dc12d228', '哭補闕亡友綦毋學士', '哭補闕亡友綦毋学士', '006ee8e4-f29d-4ced-8e5c-b9392f9d8b26', '唐', '["明代資多士，儒林得異才。","書從金殿出，人向玉墀來。","詞學張平子，風儀褚彥回。","崇儀希上德，近侍接元台。","曩契心期早，今遊宴賞陪。","屢遷君擢桂，分尉我從梅。","忽遇乘軺客，云傾構廈材。","泣爲洹水化，歎作泰山頹。","冀善初將慰，尋言半始猜。","位聯情易感，交密痛難裁。","遠日寒旌暗，長風古挽哀。","寰中無舊業，行處有新苔。","反哭魂猶寄，終喪子尚孩。","葬田門吏給，墳木路人栽。","遽洩悲成往，俄傳寵令迴。","玄經貽石室，朱紱耀泉臺。","地古春長閉，天明夜不開。","登山一臨哭，揮淚滿蒿萊。"]', '["明代資多士，儒林得異才。","书從金殿出，人向玉墀来。","词学張平子，风儀褚彥回。","崇儀希上德，近侍接元台。","曩契心期早，今游宴賞陪。","屢遷君擢桂，分尉我從梅。","忽遇乘軺客，云傾構廈材。","泣爲洹水化，歎作泰山頹。","冀善初將慰，尋言半始猜。","位聯情易感，交密痛难裁。","远日寒旌暗，长风古挽哀。","寰中無旧業，行处有新苔。","反哭魂猶寄，終喪子尚孩。","葬田门吏給，墳木路人栽。","遽洩悲成往，俄傳寵令迴。","玄經貽石室，朱紱耀泉台。","地古春长閉，天明夜不开。","登山一臨哭，揮泪满蒿萊。"]', '诗', 'shi', '', NULL, '哭補闕亡友綦毋學士 王灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2900cc3-a8f3-4d4b-82b9-e9f22d17c8ab', '閏月七日織女', '閏月七日织女', '006ee8e4-f29d-4ced-8e5c-b9392f9d8b26', '唐', '["耿耿曙河微，神仙此夜稀。","今年七月閏，應得兩回歸。"]', '["耿耿曙河微，神仙此夜稀。","今年七月閏，應得兩回归。"]', '诗', 'shi', '', NULL, '閏月七日織女 王灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d77d022-7335-45c9-aa82-0e1725555536', '句', '句', '006ee8e4-f29d-4ced-8e5c-b9392f9d8b26', '唐', '["月華照杵空隨妾，風響傳砧不到君。"]', '["月华照杵空隨妾，风响傳砧不到君。"]', '诗', 'shi', '', NULL, '句 王灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c339c18-2e14-4988-ba44-43ea5456e44d', '應詔賦得除夜', '應詔賦得除夜', 'cb6bf939-075a-4628-b3fe-497c0987e74e', '唐', '["今歲今宵盡，明年明日催。","寒隨一夜去，春逐五更來。","氣色空中改，容顏暗裏回。","風光人不覺，已著後園梅。"]', '["今歲今宵尽，明年明日催。","寒隨一夜去，春逐五更来。","氣色空中改，容顏暗裏回。","风光人不覺，已著後园梅。"]', '诗', 'shi', '', NULL, '應詔賦得除夜 史青 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa433fe7-1543-4bfd-9898-bde02b490e2f', '汴堤柳', '汴堤柳', '5a703fee-a27f-4eb9-b9ba-5dcfe91dcbf8', '唐', '["隋家天子憶揚州，厭坐深宮傍海游。","穿地鑿山開御路，鳴笳疊鼓泛清流。","流從鞏北分河口，直到淮南種官柳。","功成力盡人旋亡，代謝年移樹空有。","當時綵女侍君王，繡帳旌門對柳行。","青葉交垂連幔色，白花飛度染衣香。","今日摧殘何用道，數里曾無一枝好。","驛騎征帆損更多，山精野魅藏應老。","涼風八月露爲霜，日夜孤舟入帝鄉。","河畔時時聞木落，客中無不淚沾裳。"]', '["隋家天子憶揚州，厭坐深宮傍海游。","穿地鑿山开御路，鳴笳叠鼓泛清流。","流從鞏北分河口，直到淮南種官柳。","功成力尽人旋亡，代謝年移樹空有。","當时綵女侍君王，繡帳旌门对柳行。","青葉交垂連幔色，白花飞度染衣香。","今日摧殘何用道，數里曾無一枝好。","驛騎征帆損更多，山精野魅藏應老。","涼风八月露爲霜，日夜孤舟入帝乡。","河畔时时闻木落，客中無不泪沾裳。"]', '诗', 'shi', '', NULL, '汴堤柳 王泠然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55b45ff4-173f-42d3-82bb-7f9404191f94', '夜光篇', '夜光篇', '5a703fee-a27f-4eb9-b9ba-5dcfe91dcbf8', '唐', '["遊人夜到汝陽間，夜色冥濛不解顏。","誰家暗起寒山燒，因此明中得見山。","山頭山下須臾滿，歷險緣深無暫斷。","焦聲散著羣樹鳴，炎氣傍林一川暖。","是時西北多海風，吹上連天光更雄。","濁煙熏月黑，高豔爇雲紅。","初謂煉丹仙竈裏，還疑鑄劒神谿中。","劃爲飛電來照物，乍作流星併上空。","西山無草光已滅，東頂熒熒猶未絕。","沸湯空谷數道水，融蓋陰崖幾年雪。","兩京貧病若爲居，四壁皆成鑿照餘。","未得貴游同秉燭，唯將半影借披書。"]', '["游人夜到汝陽间，夜色冥濛不解顏。","誰家暗起寒山燒，因此明中得见山。","山头山下須臾满，歷險緣深無暫斷。","焦声散著羣樹鳴，炎氣傍林一川暖。","是时西北多海风，吹上連天光更雄。","濁煙熏月黑，高豔爇云紅。","初謂煉丹仙竈裏，還疑鑄劒神谿中。","劃爲飞電来照物，乍作流星併上空。","西山無草光已滅，东頂熒熒猶未絕。","沸湯空谷數道水，融蓋陰崖幾年雪。","兩京貧病若爲居，四壁皆成鑿照餘。","未得貴游同秉燭，唯將半影借披书。"]', '诗', 'shi', '', NULL, '夜光篇 王泠然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03e63bb4-cad0-4027-b341-bb449e5f0f00', '古木臥平沙', '古木臥平沙', '5a703fee-a27f-4eb9-b9ba-5dcfe91dcbf8', '唐', '["古木臥平沙，摧殘歲月賒。","有根橫水石，無葉拂煙霞。","春至苔爲葉，冬來雪作花。","不逢星漢使，誰辨是靈槎。"]', '["古木臥平沙，摧殘歲月賒。","有根橫水石，無葉拂煙霞。","春至苔爲葉，冬来雪作花。","不逢星漢使，誰辨是靈槎。"]', '诗', 'shi', '', NULL, '古木臥平沙 王泠然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e072273-a90f-49d2-bd63-6da85977707b', '淮南寄舍弟', '淮南寄舍弟', '5a703fee-a27f-4eb9-b9ba-5dcfe91dcbf8', '唐', '["昔予從不調，經歲旅淮源。","念爾長相失，何時返故園。","寄書迷處所，分袂隔涼溫。","遠道俱爲客，他鄉共在原。","歸情春伴雁，愁泣夜隨猨。","愧見高堂上，朝朝獨倚門。"]', '["昔予從不調，經歲旅淮源。","念爾长相失，何时返故园。","寄书迷处所，分袂隔涼溫。","远道俱爲客，他乡共在原。","归情春伴雁，愁泣夜隨猨。","愧见高堂上，朝朝独倚门。"]', '诗', 'shi', '', NULL, '淮南寄舍弟 王泠然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('642529dd-2808-475b-9ca4-ad6985008f89', '句', '句', '5a703fee-a27f-4eb9-b9ba-5dcfe91dcbf8', '唐', '["林狖欺童子，山精試老僧。","陳兵劒閣山將動，飲馬珠江水不流。","官微思倚玉，文淺怯投珠。"]', '["林狖欺童子，山精試老僧。","陳兵劒閣山將动，饮马珠江水不流。","官微思倚玉，文淺怯投珠。"]', '诗', 'shi', '', NULL, '句 王泠然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeec458f-b3b7-4d10-9f85-62dcc40c3a9c', '春江花月夜二首 一', '春江花月夜二首 一', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["林花發岸口，氣色動江新。","此夜江中月，流光花上春。","分明石潭裏，宜照浣紗人。"]', '["林花發岸口，氣色动江新。","此夜江中月，流光花上春。","分明石潭裏，宜照浣紗人。"]', '诗', 'shi', '', NULL, '春江花月夜二首 一 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b99dc5a8-4003-4bb0-9a4d-b088be0d8cb1', '春江花月夜二首 二', '春江花月夜二首 二', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["交甫憐瑤珮，仙妃難重期。","沈沈綠江晚，惆悵碧雲姿。","初逢花上月，言是弄珠時。"]', '["交甫怜瑤珮，仙妃难重期。","沈沈綠江晚，惆悵碧云姿。","初逢花上月，言是弄珠时。"]', '诗', 'shi', '', NULL, '春江花月夜二首 二 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffd4483e-e27d-4f9e-a371-4a62234c1000', '雲陽驛陪崔使君邵道士夜宴', '云陽驛陪崔使君邵道士夜宴', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["一尉東南遠，誰知此夜歡。","諸侯傾皁蓋，仙客整黃冠。","染翰燈花滿，飛觴雲氣寒。","欣承國士遇，更借美人看。"]', '["一尉东南远，誰知此夜歡。","諸侯傾皁蓋，仙客整黄冠。","染翰灯花满，飞觴云氣寒。","欣承国士遇，更借美人看。"]', '诗', 'shi', '', NULL, '雲陽驛陪崔使君邵道士夜宴 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e85481e-fbae-467c-bb19-e7ea6e7846e2', '除夜樂城逢孟浩然', '除夜乐城逢孟浩然', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["遠客襄陽郡，來過海岸家。","樽開柏葉酒，燈發九枝花。","妙曲逢盧女，高才得孟嘉。","東山行樂意，非是競繁華。"]', '["远客襄陽郡，来過海岸家。","樽开柏葉酒，灯發九枝花。","妙曲逢盧女，高才得孟嘉。","东山行乐意，非是競繁华。"]', '诗', 'shi', '', NULL, '除夜樂城逢孟浩然 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3383d17e-05be-4ab5-8c75-5d42cb91b236', '送蘇倩遊天台', '送蘇倩游天台', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["靈異尋滄海，笙歌訪翠微。","江鷗迎共狎，雲鶴待將飛。","琪樹嘗仙果，瓊樓試羽衣。","遙知神女問，獨怪阮郎歸。"]', '["靈異尋滄海，笙歌訪翠微。","江鷗迎共狎，云鹤待將飞。","琪樹嘗仙果，瓊楼試羽衣。","遙知神女问，独怪阮郎归。"]', '诗', 'shi', '', NULL, '送蘇倩遊天台 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2ed4537-3fcb-40ef-8c0f-29c1c46366b3', '泛永嘉江日暮迴舟', '泛永嘉江日暮迴舟', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["無雲天欲暮，輕鷁大江清。","歸路煙中遠，迴舟月上行。","傍潭窺竹暗，出嶼見沙明。","更值微風起，乘流絲管聲。"]', '["無云天欲暮，轻鷁大江清。","归路煙中远，迴舟月上行。","傍潭窺竹暗，出嶼见沙明。","更值微风起，乘流絲管声。"]', '诗', 'shi', '', NULL, '泛永嘉江日暮迴舟 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8626a651-e63a-4a8f-a6b5-62529aab56fc', '永嘉即事寄贛縣袁少府瓘', '永嘉即事寄贛縣袁少府瓘', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["山繞樓臺出，谿通里閈斜。","曾爲謝客郡，多有逐臣家。","海氣朝成雨，江天晚作霞。","題書報賈誼，此濕似長沙。"]', '["山繞楼台出，谿通里閈斜。","曾爲謝客郡，多有逐臣家。","海氣朝成雨，江天晚作霞。","題书報賈誼，此濕似长沙。"]', '诗', 'shi', '', NULL, '永嘉即事寄贛縣袁少府瓘 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('598cb1ef-93c1-498d-a48e-2881058fe1d0', '樂城歲日贈孟浩然', '乐城歲日贈孟浩然', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["土地窮甌越，風光肇建寅。","插桃銷瘴癘，移竹近階墀。","半是吳風俗，仍爲楚歲時。","更逢習鑿齒，言在漢川湄。"]', '["土地窮甌越，风光肇建寅。","插桃銷瘴癘，移竹近階墀。","半是吳风俗，仍爲楚歲时。","更逢習鑿齒，言在漢川湄。"]', '诗', 'shi', '', NULL, '樂城歲日贈孟浩然 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04a6d7f6-abe1-4d73-9e5d-762c5f4781e7', '永嘉作', '永嘉作', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["拙宦從江左，投荒更海邊。","山將孤嶼近，水共惡谿連。","地濕梅多雨，潭蒸竹起煙。","未應悲晚髪，炎瘴苦華年。"]', '["拙宦從江左，投荒更海邊。","山將孤嶼近，水共惡谿連。","地濕梅多雨，潭蒸竹起煙。","未應悲晚髪，炎瘴苦华年。"]', '诗', 'shi', '', NULL, '永嘉作 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('640be62f-649f-4202-94e3-cbf57b6b2e0c', '送孟八浩然歸襄陽二首 一', '送孟八浩然归襄陽二首 一', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["東越相逢地，西亭送別津。","風潮看解纜，雲海去愁人。","鄉在桃林岸，山連楓樹春。","因懷故園意，歸與孟家鄰。"]', '["东越相逢地，西亭送別津。","风潮看解纜，云海去愁人。","乡在桃林岸，山連楓樹春。","因懷故园意，归與孟家鄰。"]', '诗', 'shi', '', NULL, '送孟八浩然歸襄陽二首 一 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4eb0fd5-78f5-4004-bed3-acd3a786062c', '送孟八浩然歸襄陽二首 二', '送孟八浩然归襄陽二首 二', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["杜門不欲出，久與世情疎。","以此爲長策，勸君歸舊廬。","醉歌田舍酒，笑讀古人書。","好是一生事，無勞獻子虛。"]', '["杜门不欲出，久與世情疎。","以此爲长策，勸君归旧廬。","醉歌田舍酒，笑读古人书。","好是一生事，無勞獻子虛。"]', '诗', 'shi', '', NULL, '送孟八浩然歸襄陽二首 二 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42f24b70-ae4d-4633-9a78-d17e619e57bf', '貶樂城尉日作', '貶乐城尉日作', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["竄謫邊窮海，川原近惡谿。","有時聞虎嘯，無夜不猿啼。","地暖花長發，巖高日易低。","故鄉可憶處，遙指斗牛西。"]', '["竄謫邊窮海，川原近惡谿。","有时闻虎嘯，無夜不猿啼。","地暖花长發，巖高日易低。","故乡可憶处，遙指斗牛西。"]', '诗', 'shi', '', NULL, '貶樂城尉日作 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('737d6307-8218-40b5-965e-be6a22e98ede', '自樂城赴永嘉枉路泛白湖寄松陽李少府', '自乐城赴永嘉枉路泛白湖寄松陽李少府', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["西行礙淺石，北轉入谿橋。","樹色煙輕重，湖光風動搖。","百花亂飛雪，萬嶺疊青霄。","猿挂臨潭篠，鷗迎出浦橈。","惟應賞心客，茲路不言遙。"]', '["西行礙淺石，北轉入谿橋。","樹色煙轻重，湖光风动搖。","百花亂飞雪，万嶺叠青霄。","猿挂臨潭篠，鷗迎出浦橈。","惟應賞心客，茲路不言遙。"]', '诗', 'shi', '', NULL, '自樂城赴永嘉枉路泛白湖寄松陽李少府 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ab060e8-afe9-4870-a3b1-a91256bf6263', '九日陪潤州邵使君登北固山', '九日陪潤州邵使君登北固山', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["五馬向西椒，重陽坐麗譙。","徐州帶綠水，楚國在青霄。","張幕連江樹，開筵接海潮。","凌雲詞客語，迴雪無人嬌。","梅福慚仙吏，羊公賞下僚。","新豐酒舊美，況是菊花朝。"]', '["五马向西椒，重陽坐丽譙。","徐州带綠水，楚国在青霄。","張幕連江樹，开筵接海潮。","凌云词客語，迴雪無人嬌。","梅福慚仙吏，羊公賞下僚。","新豐酒旧美，況是菊花朝。"]', '诗', 'shi', '', NULL, '九日陪潤州邵使君登北固山 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('355b1b8e-5bc5-4fc0-a6ed-7612cb49b91d', '璧池望秋月', '璧池望秋月', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["涼夜窺清沼，池空水月秋。","滿輪沈玉鏡，半魄落銀鉤。","蟾影搖輕浪，菱花渡淺流。","漏移光漸潔，雲斂色偏浮。","似璧悲三獻，疑珠怯再投。","能持千里意，來照楚鄉愁。"]', '["涼夜窺清沼，池空水月秋。","满輪沈玉镜，半魄落銀鉤。","蟾影搖轻浪，菱花渡淺流。","漏移光漸潔，云斂色偏浮。","似璧悲三獻，疑珠怯再投。","能持千里意，来照楚乡愁。"]', '诗', 'shi', '', NULL, '璧池望秋月 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8faf26f4-8811-4c7a-b3b2-416d622b49c8', '長安早春', '长安早春', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["開國維東井，城池起北辰。","咸歌太平日，共樂建寅春。","雪盡黃山樹，冰開黑水津。","草迎金埒馬，花伴玉樓人。","鴻漸看無數，鶯歌聽欲頻。","何當桂枝擢，還及柳條新。"]', '["开国維东井，城池起北辰。","咸歌太平日，共乐建寅春。","雪尽黄山樹，冰开黑水津。","草迎金埒马，花伴玉楼人。","鴻漸看無數，鶯歌听欲頻。","何當桂枝擢，還及柳條新。"]', '诗', 'shi', '', NULL, '長安早春 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cf82a91-18a7-4f64-b1c3-c46289755e7b', '贈司勳蕭郎中', '贈司勳蕭郎中', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["作相開黃閣，爲郎奏赤墀。","君臣道合體，父子貴同時。","國以推賢答，家無內舉疑。","鳳池真水鏡，蘭省得華滋。","未覩風流日，先聞新賦詩。","江山清謝朓，花木媚丘遲。","吏部來何暮，王言念在茲。","丹青無不可，霖雨亦相期。","昔我投荒處，孤煙望島夷。","羣鷗終日狎，落葉數年悲。","漁父留歌詠，江妃入興詞。","今將獻知己，相感勿吾欺。"]', '["作相开黄閣，爲郎奏赤墀。","君臣道合體，父子貴同时。","国以推賢答，家無內舉疑。","鳳池真水镜，蘭省得华滋。","未覩风流日，先闻新賦诗。","江山清謝朓，花木媚丘遲。","吏部来何暮，王言念在茲。","丹青無不可，霖雨亦相期。","昔我投荒处，孤煙望島夷。","羣鷗終日狎，落葉數年悲。","漁父留歌詠，江妃入兴词。","今將獻知己，相感勿吾欺。"]', '诗', 'shi', '', NULL, '贈司勳蕭郎中 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0544981f-b304-432b-a31a-6f0ee075e0e3', '巫山', '巫山', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["巫嶺岧嶢天際重，佳期宿昔願相從。","朝雲暮雨連天暗，神女知來第幾峯。"]', '["巫嶺岧嶢天際重，佳期宿昔願相從。","朝云暮雨連天暗，神女知来第幾峯。"]', '诗', 'shi', '', NULL, '巫山 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f5ad030-5bc9-4111-9ca0-757f993ba796', '除日', '除日', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["臘月今知晦，流年此夕除。","拾樵供歲火，帖牖作春書。","柳覺東風至，花疑小雪餘。","忽逢雙鯉贈，言是上冰魚。"]', '["臘月今知晦，流年此夕除。","拾樵供歲火，帖牖作春书。","柳覺东风至，花疑小雪餘。","忽逢雙鯉贈，言是上冰鱼。"]', '诗', 'shi', '', NULL, '除日 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2267fa7-afcf-4584-9372-e3b40dfab931', '清谿泛舟', '清谿泛舟', '6417afa9-6222-4e9c-aadb-238631feb17b', '唐', '["旅人倚征棹，薄暮起勞歌。","笑攬清谿月，清輝不厭多。"]', '["旅人倚征棹，薄暮起勞歌。","笑攬清谿月，清輝不厭多。"]', '诗', 'shi', '', NULL, '清谿泛舟 張旭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f28ab03-8388-4a2f-8c4f-3ce47789e221', '桃花谿', '桃花谿', '6417afa9-6222-4e9c-aadb-238631feb17b', '唐', '["隱隱飛橋隔野煙，石磯西畔問漁船。","桃花盡日隨流水，洞在清谿何處邊。"]', '["隐隐飞橋隔野煙，石磯西畔问漁船。","桃花尽日隨流水，洞在清谿何处邊。"]', '诗', 'shi', '', NULL, '桃花谿 張旭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('717dc2a3-1c78-49d9-a075-ed7c3b76ac77', '山行留客', '山行留客', '6417afa9-6222-4e9c-aadb-238631feb17b', '唐', '["山光物態弄春輝，莫爲輕陰便擬歸。","縱使晴明無雨色，入雲深處亦沾衣。"]', '["山光物態弄春輝，莫爲轻陰便擬归。","縱使晴明無雨色，入云深处亦沾衣。"]', '诗', 'shi', '', NULL, '山行留客 張旭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('435557f1-47d2-4a79-9628-7957533e5e71', '春遊值雨', '春游值雨', '6417afa9-6222-4e9c-aadb-238631feb17b', '唐', '["欲尋軒檻列清尊，江上煙雲向晚昏。","須倩東風吹散雨，明朝却待入華園。"]', '["欲尋軒檻列清尊，江上煙云向晚昏。","須倩东风吹散雨，明朝却待入华园。"]', '诗', 'shi', '', NULL, '春遊值雨 張旭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaebbaed-d62b-4827-b204-f47aa4b9ff98', '春草', '春草', '6417afa9-6222-4e9c-aadb-238631feb17b', '唐', '["春草青青萬里餘，邊城落日見離居。","情知海上三年別，不寄雲間一紙書。"]', '["春草青青万里餘，邊城落日见離居。","情知海上三年別，不寄云间一紙书。"]', '诗', 'shi', '', NULL, '春草 張旭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3b9f51e-1c08-433d-84cb-7bfdd9a7868d', '柳', '柳', '6417afa9-6222-4e9c-aadb-238631feb17b', '唐', '["濯濯煙條拂地垂，城邊樓畔結春思。","請君細看風流意，未減靈和殿裏時。"]', '["濯濯煙條拂地垂，城邊楼畔結春思。","請君細看风流意，未減靈和殿裏时。"]', '诗', 'shi', '', NULL, '柳 張旭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e8bd2e-63df-4bbe-86af-891b31ed15d5', '南山', '南山', 'a4f46bf4-38c2-4e8d-94ed-57197830ca1a', '唐', '["湖北雨初晴，湖南山盡見。","巖巖石帆影，如得海風便。","仙穴茅山峯，彩雲時一見。","邀君共探此，異籙殘幾卷。"]', '["湖北雨初晴，湖南山尽见。","巖巖石帆影，如得海风便。","仙穴茅山峯，彩云时一见。","邀君共探此，異籙殘幾卷。"]', '诗', 'shi', '', NULL, '南山 賀朝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a167e23-f6f5-433d-93e7-0c4ffcb8cd9a', '孤興', '孤兴', 'a4f46bf4-38c2-4e8d-94ed-57197830ca1a', '唐', '["晴日暖珠箔，夭桃色正新。","紅粉青鏡中，娟娟可憐嚬。","君子在遐險，蕙心誰見珍。","羅幕空掩晝，玉顏靜移春。","江瑟語幽獨，再三情未申。","黃鵠千里翅，芳音遲所因。"]', '["晴日暖珠箔，夭桃色正新。","紅粉青镜中，娟娟可怜嚬。","君子在遐險，蕙心誰见珍。","羅幕空掩晝，玉顏静移春。","江瑟語幽独，再三情未申。","黄鵠千里翅，芳音遲所因。"]', '诗', 'shi', '', NULL, '孤興 賀朝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54f3415b-fa5b-4137-b759-e7b5f5529011', '從軍行', '從軍行', 'a4f46bf4-38c2-4e8d-94ed-57197830ca1a', '唐', '["朔胡乘月寇邊城，軍書插羽刺中京。","天子金壇拜飛將，單于玉塞振佳兵。","騎射先鳴推任俠，龍韜決勝佇時英。","聞有河湟客，愔愔理帷帟。","常山啓霸圖，汜水先天策。","銜珠浴鐵向桑乾，釁旗膏劒指烏丸。","鳴雞已報關山曉，來雁遙傳沙塞寒。","直爲甘心從苦節，隴頭流水鳴嗚咽。","邊樹蕭蕭不覺春，天山漠漠長飛雪。","魚麗陣接塞雲平，雁翼營通海月明。","始看晉幕飛鵝入，旋聞齊壘啼烏聲。","自從一戍燕支山，春光幾度晉陽關。","金河未轉青絲騎，玉筯應啼紅粉顏。","鴻歸燕相續，池邊芳草綠。","已見氛清細柳營，莫更春歌落梅曲。","烽沈竈減靜邊亭，海[晏]山空肅已寧。","行望鳳京旋凱捷，重來麟閣畫丹青。"]', '["朔胡乘月寇邊城，軍书插羽刺中京。","天子金壇拜飞將，單于玉塞振佳兵。","騎射先鳴推任俠，龙韜決勝佇时英。","闻有河湟客，愔愔理帷帟。","常山啓霸圖，汜水先天策。","銜珠浴鐵向桑乾，釁旗膏劒指烏丸。","鳴雞已報关山晓，来雁遙傳沙塞寒。","直爲甘心從苦節，隴头流水鳴嗚咽。","邊樹蕭蕭不覺春，天山漠漠长飞雪。","鱼丽陣接塞云平，雁翼營通海月明。","始看晉幕飞鵝入，旋闻齊壘啼烏声。","自從一戍燕支山，春光幾度晉陽关。","金河未轉青絲騎，玉筯應啼紅粉顏。","鴻归燕相續，池邊芳草綠。","已见氛清細柳營，莫更春歌落梅曲。","烽沈竈減静邊亭，海[晏]山空肅已寧。","行望鳳京旋凱捷，重来麟閣畫丹青。"]', '诗', 'shi', '', NULL, '從軍行 賀朝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeec4960-975b-4a73-bd01-53a73eed56cd', '賦得遊人久不歸', '賦得游人久不归', 'a4f46bf4-38c2-4e8d-94ed-57197830ca1a', '唐', '["鄉關眇天末，引領悵懷歸。","羇旅久淫滯，物色屢芳菲。","稍覺出意盡，行看蓬鬢稀。","如何千里外，佇立霑裳衣。"]', '["乡关眇天末，引領悵懷归。","羇旅久淫滯，物色屢芳菲。","稍覺出意尽，行看蓬鬢稀。","如何千里外，佇立霑裳衣。"]', '诗', 'shi', '', NULL, '賦得遊人久不歸 賀朝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3433704-3894-47aa-9d84-3832b7ddc524', '宿香山閣', '宿香山閣', 'a4f46bf4-38c2-4e8d-94ed-57197830ca1a', '唐', '["暝上春山閣，梯雲宿半空。","軒窗閉潮海，枕席拂煙虹。","朱網防棲鴿，紗燈護夕蟲。","一聞雞唱曉，已見日曈曈。"]', '["暝上春山閣，梯云宿半空。","軒窗閉潮海，枕席拂煙虹。","朱網防棲鴿，紗灯護夕蟲。","一闻雞唱晓，已见日曈曈。"]', '诗', 'shi', '', NULL, '宿香山閣 賀朝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1831721-fe6e-4e69-bd1f-f7623a2b714e', '贈酒店胡姬', '贈酒店胡姬', 'a4f46bf4-38c2-4e8d-94ed-57197830ca1a', '唐', '["胡姬春酒店，弦管夜鏘鏘。","紅毾鋪新月，貂裘坐薄霜。","玉盤初鱠鯉，金鼎正烹羊。","上客無勞散，聽歌樂世娘。"]', '["胡姬春酒店，弦管夜鏘鏘。","紅毾鋪新月，貂裘坐薄霜。","玉盤初鱠鯉，金鼎正烹羊。","上客無勞散，听歌乐世娘。"]', '诗', 'shi', '', NULL, '贈酒店胡姬 賀朝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('246e44be-c0e2-4d9b-a03f-c9a03601ba7f', '賦得春鶯送友人二首 一', '賦得春鶯送友人二首 一', 'a4f46bf4-38c2-4e8d-94ed-57197830ca1a', '唐', '["翅掩飛鶯舞，啼惱婕妤悲。","料取金閨意，因君問所思。"]', '["翅掩飞鶯舞，啼惱婕妤悲。","料取金閨意，因君问所思。"]', '诗', 'shi', '', NULL, '賦得春鶯送友人二首 一 賀朝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fe21131-5bae-46ef-bbe8-cec35cf31979', '賦得春鶯送友人二首 二', '賦得春鶯送友人二首 二', 'a4f46bf4-38c2-4e8d-94ed-57197830ca1a', '唐', '["流鶯拂繡羽，二月上林期。","待雪銷金禁，銜花向玉墀。"]', '["流鶯拂繡羽，二月上林期。","待雪銷金禁，銜花向玉墀。"]', '诗', 'shi', '', NULL, '賦得春鶯送友人二首 二 賀朝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f76ec11f-4009-4f44-9362-776f84e358d7', '三日綠潭篇', '三日綠潭篇', '07601c18-c025-4a3b-9e61-3148b420aeb8', '唐', '["春潭滉漾接隋宮，宮闕連延潭水東。","蘋苔嫩色涵波綠，桃李新花照底紅。","垂菱布藻如妝鏡，麗日晴天相照暎。","素影沈沈對蝶飛，金沙礫礫窺魚泳。","佳人祓禊賞韶年，傾國傾城併可憐。","拾翠總來芳樹下，踏青爭遶綠潭邊。","公子王孫恣遊翫，沙陽水曲情無厭。","禽浮似挹羽觴杯，鱗躍疑投水心劒。","金鞍玉勒騁輕肥，落絮紅塵擁路飛。","綠水殘霞催席散，畫樓初月待人歸。"]', '["春潭滉漾接隋宮，宮闕連延潭水东。","蘋苔嫩色涵波綠，桃李新花照底紅。","垂菱布藻如妝镜，丽日晴天相照暎。","素影沈沈对蝶飞，金沙礫礫窺鱼泳。","佳人祓禊賞韶年，傾国傾城併可怜。","拾翠總来芳樹下，踏青爭遶綠潭邊。","公子王孫恣游翫，沙陽水曲情無厭。","禽浮似挹羽觴杯，鱗躍疑投水心劒。","金鞍玉勒騁轻肥，落絮紅塵擁路飞。","綠水殘霞催席散，畫楼初月待人归。"]', '诗', 'shi', '', NULL, '三日綠潭篇 萬齊融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('690277bc-c6d7-4fcf-9261-81910b5100e3', '仗劒行', '仗劒行', '07601c18-c025-4a3b-9e61-3148b420aeb8', '唐', '["昨夜星官動紫微，今年天子用武威。","登車一呼風雷動，遙震陰山撼巍巍。","胡驕子，當見旄頭蝕應死。","願騎單馬仗天威，挼取長繩縛虜歸。","仗劒遙叱路傍子，匈奴頭血濺君衣。"]', '["昨夜星官动紫微，今年天子用武威。","登车一呼风雷动，遙震陰山撼巍巍。","胡驕子，當见旄头蝕應死。","願騎單马仗天威，挼取长繩縛虜归。","仗劒遙叱路傍子，匈奴头血濺君衣。"]', '诗', 'shi', '', NULL, '仗劒行 萬齊融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('956b9e27-b65f-463c-8b7d-b933a02ccd80', '贈別江頭', '贈別江头', '07601c18-c025-4a3b-9e61-3148b420aeb8', '唐', '["東南飛鳥處，言是故鄉天。","江上風花晚，君行定幾千。","計程頻破月，數別屢開年。","明歲潯陽水，相思寄采蓮。"]', '["东南飞鸟处，言是故乡天。","江上风花晚，君行定幾千。","計程頻破月，數別屢开年。","明歲潯陽水，相思寄采蓮。"]', '诗', 'shi', '', NULL, '贈別江頭 萬齊融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea154939-51ab-41f9-91f4-85b006a283c1', '送陳七還廣陵', '送陳七還廣陵', '07601c18-c025-4a3b-9e61-3148b420aeb8', '唐', '["風流誰代子，雖有舊無雙。","歡酒言相送，愁弦意不降。","落花馥河道，垂楊拂水窗。","海潮與春夢，朝夕廣陵江。"]', '["风流誰代子，雖有旧無雙。","歡酒言相送，愁弦意不降。","落花馥河道，垂楊拂水窗。","海潮與春梦，朝夕廣陵江。"]', '诗', 'shi', '', NULL, '送陳七還廣陵 萬齊融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88512e94-1be0-4b4f-b65c-8f5890afd0b8', '遊春', '游春', 'ecaf3d45-272f-4c08-a074-d0ebd733d5ab', '唐', '["海岳三峯古，春皇二月寒。","綠潭漁子釣，紅樹美人攀。","弱蔓環沙嶼，飛花點石關。","谿山遊未厭，琴酌弄晴灣。"]', '["海岳三峯古，春皇二月寒。","綠潭漁子釣，紅樹美人攀。","弱蔓环沙嶼，飞花点石关。","谿山游未厭，琴酌弄晴灣。"]', '诗', 'shi', '', NULL, '遊春 邢巨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbac5349-4f32-45be-8a68-276774d8c68e', '遊宣州琴谿同武平一作', '游宣州琴谿同武平一作', 'ecaf3d45-272f-4c08-a074-d0ebd733d5ab', '唐', '["靈谿非人迹，仙意素所秉。","鱗嶺森翠微，澄潭照秋景。"]', '["靈谿非人迹，仙意素所秉。","鱗嶺森翠微，澄潭照秋景。"]', '诗', 'shi', '', NULL, '遊宣州琴谿同武平一作 邢巨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('587422bf-52ac-4755-97fc-1b22ad6ae626', '春江花月夜', '春江花月夜', 'f309e4dc-8e63-458b-8edf-b5c1873c0bd5', '唐', '["春江潮水連海平，海上明月共潮生。","灩灩隨波千萬里，何處春江無月明？","江流宛轉遶芳甸，月照花林皆似霰。","空裏流霜不覺飛，汀上白沙看不見。","江天一色無纖塵，皎皎空中孤月輪。","江畔何人初見月，江月何年初照人？","人生代代無窮已，江月年年秖相似。","不知江月待何人？但見長江送流水。","白雲一片去悠悠，青楓浦上不勝愁。","誰家今夜扁舟子，何處相思明月樓？","可憐樓上月裴回，應照離人妝鏡臺。","玉戶簾中卷不去，擣衣砧上拂還來。","此時相望不相聞，願逐月華流照君。","鴻雁長飛光不度，魚龍潛躍水成文。","昨夜閑潭夢落花，可憐春半不還家。","江水流春去欲盡，江潭落月復西斜。","斜月沈沈藏海霧，碣石瀟湘無限路。","不知乘月幾人歸，落月搖情滿江樹。"]', '["春江潮水連海平，海上明月共潮生。","灩灩隨波千万里，何处春江無月明？","江流宛轉遶芳甸，月照花林皆似霰。","空裏流霜不覺飞，汀上白沙看不见。","江天一色無纖塵，皎皎空中孤月輪。","江畔何人初见月，江月何年初照人？","人生代代無窮已，江月年年秖相似。","不知江月待何人？但见长江送流水。","白云一片去悠悠，青楓浦上不勝愁。","誰家今夜扁舟子，何处相思明月楼？","可怜楼上月裴回，應照離人妝镜台。","玉戶簾中卷不去，擣衣砧上拂還来。","此时相望不相闻，願逐月华流照君。","鴻雁长飞光不度，鱼龙潛躍水成文。","昨夜闲潭梦落花，可怜春半不還家。","江水流春去欲尽，江潭落月复西斜。","斜月沈沈藏海霧，碣石瀟湘無限路。","不知乘月幾人归，落月搖情满江樹。"]', '诗', 'shi', '', NULL, '春江花月夜 張若虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b5fa0e4-45cb-4371-9141-4cd739574218', '代答閨夢還', '代答閨梦還', 'f309e4dc-8e63-458b-8edf-b5c1873c0bd5', '唐', '["關塞年華早，樓臺別望違。","試衫著煖氣，開鏡覓春暉。","燕入窺羅幕，蜂來上畫衣。","情催桃李豔，心寄管弦飛。","妝洗朝相待，風花暝不歸。","夢魂何處入，寂寂掩重扉。"]', '["关塞年华早，楼台別望違。","試衫著煖氣，开镜覓春暉。","燕入窺羅幕，蜂来上畫衣。","情催桃李豔，心寄管弦飞。","妝洗朝相待，风花暝不归。","梦魂何处入，寂寂掩重扉。"]', '诗', 'shi', '', NULL, '代答閨夢還 張若虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff988a4c-5dba-4907-99c3-c0960e7e7566', '洪州客舍寄柳博士芳', '洪州客舍寄柳博士芳', '9c725ddc-82eb-4d6a-b96b-8bfdee4d3c8e', '唐', '["去年燕巢主人屋，今年花發路傍枝。","年年爲客不到舍，舊國存亡那得知。"]', '["去年燕巢主人屋，今年花發路傍枝。","年年爲客不到舍，旧国存亡那得知。"]', '诗', 'shi', '', NULL, '洪州客舍寄柳博士芳 薛業 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('213e4cab-d7a1-4e33-a8c9-c20c50226dd8', '晚秋贈張折衝', '晚秋贈張折衝', '9c725ddc-82eb-4d6a-b96b-8bfdee4d3c8e', '唐', '["都尉今無事，時清但閉關。","夜霜戎馬瘦，秋草射堂閑。","位以穿楊得，名因折桂還。","馮唐真不遇，歎息鬢毛斑。"]', '["都尉今無事，时清但閉关。","夜霜戎马瘦，秋草射堂闲。","位以穿楊得，名因折桂還。","馮唐真不遇，歎息鬢毛斑。"]', '诗', 'shi', '', NULL, '晚秋贈張折衝 薛業 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('905d012f-ac6d-4ee2-996d-7bd8a9cda463', '和左司張員外自洛使入京中路先赴長安逢立春日贈韋侍御等諸公', '和左司張員外自洛使入京中路先赴长安逢立春日贈韋侍御等諸公', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["拜郎登省闥，奉使馳車乘。","遙瞻使者星，便是郎官應。","臺妙時相許，皇華德彌稱。","二陝聽風謠，三秦望形勝。","此中暌益友，是日多詩興。","寒盡歲陰催，春歸物華證。"]', '["拜郎登省闥，奉使驰车乘。","遙瞻使者星，便是郎官應。","台妙时相許，皇华德彌稱。","二陝听风謠，三秦望形勝。","此中暌益友，是日多诗兴。","寒尽歲陰催，春归物华證。"]', '诗', 'shi', '', NULL, '和左司張員外自洛使入京中路先赴長安逢立春日贈韋侍御等諸公 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d8f4974-52ac-48d7-9c0e-ba35e3341c87', '和登會稽山', '和登會稽山', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["稽山碧湖上，勢入東溟盡。","煙景晝清明，九峰爭隱嶙。","望中厭朱紱，俗內探玄牝。","野老聽鳴騶，山童擁行軫。","仙花寒未落，古蔓柔堪引。","竹磵入山多，松崖向天近。","雲從海天去，日就江村隕。","能賦丘嘗聞，和歌參不敏。","冥搜信沖漠，多士期標準。","願奉濯纓心，長謠反招隱。"]', '["稽山碧湖上，勢入东溟尽。","煙景晝清明，九峰爭隐嶙。","望中厭朱紱，俗內探玄牝。","野老听鳴騶，山童擁行軫。","仙花寒未落，古蔓柔堪引。","竹磵入山多，松崖向天近。","云從海天去，日就江村隕。","能賦丘嘗闻，和歌參不敏。","冥搜信沖漠，多士期標準。","願奉濯纓心，长謠反招隐。"]', '诗', 'shi', '', NULL, '和登會稽山 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45b5a565-7c75-4e92-8d2a-704146d86a85', '送楊法曹按括州', '送楊法曹按括州', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["東海天台山，南方縉雲驛。","溪澄問人隱，巖險煩登陟。","潭壑隨星使，軒車繞春色。","儻尋琪樹人，爲報長相憶。"]', '["东海天台山，南方縉云驛。","溪澄问人隐，巖險煩登陟。","潭壑隨星使，軒车繞春色。","儻尋琪樹人，爲報长相憶。"]', '诗', 'shi', '', NULL, '送楊法曹按括州 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f0ad4d3-f709-4a2c-b05f-e63dca3e6cef', '葛山潭', '葛山潭', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["圓潭寫流月，晴明涵萬象。","仙翁何時還，綠水空蕩漾。","涼哉草木腓，白露沾人衣。","猶醉空山裏，時聞笙鶴飛。"]', '["圓潭寫流月，晴明涵万象。","仙翁何时還，綠水空蕩漾。","涼哉草木腓，白露沾人衣。","猶醉空山裏，时闻笙鹤飞。"]', '诗', 'shi', '', NULL, '葛山潭 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('288c52fa-ce01-48c7-ae4a-760381fef23f', '丹陽行', '丹陽行', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["丹陽古郡洞庭陰，落日扁舟此路尋。","傳是東南舊都處，金陵中斷碧江深。","在昔風塵起，京都亂如燬。","雙闕戎虜間，千門戰場裏。","傳聞一馬化爲龍，南渡衣冠亦願從。","石頭橫帝里，京口拒戎鋒。","青楓林下迴天蹕，杜若洲前轉國容。","都門不見河陽樹，輦道唯聞建業鐘。","中原悠悠幾千里，欲掃欃槍未云已。","英雄傾奪何紛然，一盛一衰如逝川。","可憐宮觀重江裏，金鏡相傳三百年。","自從龍見聖人出，六合車書混爲一。","昔年王氣今何在，併向長安就堯日。","荆榛古木閉荒阡，共道繁華不復全。","赤縣唯餘江樹月，黃圖半入海人煙。","暮來山水登臨遍，覽古愁吟淚如霰。","唯有空城多白雲，春風淡蕩無人見。"]', '["丹陽古郡洞庭陰，落日扁舟此路尋。","傳是东南旧都处，金陵中斷碧江深。","在昔风塵起，京都亂如燬。","雙闕戎虜间，千门戰場裏。","傳闻一马化爲龙，南渡衣冠亦願從。","石头橫帝里，京口拒戎鋒。","青楓林下迴天蹕，杜若洲前轉国容。","都门不见河陽樹，輦道唯闻建業鐘。","中原悠悠幾千里，欲掃欃槍未云已。","英雄傾奪何紛然，一盛一衰如逝川。","可怜宮观重江裏，金镜相傳三百年。","自從龙见聖人出，六合车书混爲一。","昔年王氣今何在，併向长安就堯日。","荆榛古木閉荒阡，共道繁华不复全。","赤縣唯餘江樹月，黄圖半入海人煙。","暮来山水登臨遍，覽古愁吟泪如霰。","唯有空城多白云，春风淡蕩無人见。"]', '诗', 'shi', '', NULL, '丹陽行 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('339e0169-abf5-49fb-be2a-704a9a4a1396', '山陰縣西樓', '山陰縣西楼', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["都邑西樓芳樹間，逶迤霽色遶江山。","山月夜從公署出，江雲晚對訟庭還。","誰知春色朝朝好，二月飛花滿江草。","一見湖邊楊柳風，遙憶青青洛陽道。"]', '["都邑西楼芳樹间，逶迤霽色遶江山。","山月夜從公署出，江云晚对訟庭還。","誰知春色朝朝好，二月飞花满江草。","一见湖邊楊柳风，遙憶青青洛陽道。"]', '诗', 'shi', '', NULL, '山陰縣西樓 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('544ad2e6-3834-4f84-908c-5fcb06ee636d', '夜宿浙江', '夜宿浙江', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["扁舟夜入江潭泊，露白風高氣蕭索。","富春渚上潮未還，天姥岑邊月初落。","煙水茫茫多苦辛，更聞江上越人吟。","洛陽城闕何時見，西北浮雲朝暝深。"]', '["扁舟夜入江潭泊，露白风高氣蕭索。","富春渚上潮未還，天姥岑邊月初落。","煙水茫茫多苦辛，更闻江上越人吟。","洛陽城闕何时见，西北浮云朝暝深。"]', '诗', 'shi', '', NULL, '夜宿浙江 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0565e377-860d-4848-abfe-ff6420c9409f', '春日留別', '春日留別', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["春路逶迤花柳前，孤舟晚泊就人煙。","東山白雲不可見，西陵江月夜娟娟。","春江夜盡潮聲度，征帆遙從此中去。","越國山川看漸無，可憐愁思江南樹。"]', '["春路逶迤花柳前，孤舟晚泊就人煙。","东山白云不可见，西陵江月夜娟娟。","春江夜尽潮声度，征帆遙從此中去。","越国山川看漸無，可怜愁思江南樹。"]', '诗', 'shi', '', NULL, '春日留別 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2753516-44ff-4cc1-9936-bc13cc78602f', '奉和四月三日上陽水窗賜宴應制得春字', '奉和四月三日上陽水窗賜宴應制得春字', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["今日逢初夏，歡遊續舊旬。","氣和先作雨，恩厚別成春。","鳳吹臨清洛，龍輿下紫宸。","此中歌在藻，還見躍潛鱗。"]', '["今日逢初夏，歡游續旧旬。","氣和先作雨，恩厚別成春。","鳳吹臨清洛，龙輿下紫宸。","此中歌在藻，還见躍潛鱗。"]', '诗', 'shi', '', NULL, '奉和四月三日上陽水窗賜宴應制得春字 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccff76d6-4bd6-4bb3-a4b0-59c2c766f9f7', '奉和登會昌山應制', '奉和登會昌山應制', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["巖磴列雲旗，吾君訪道時。","乾行萬物覩，日馭六龍遲。","望遠迴天顧，登高動睿詞。","願因山作壽，長保會昌期。"]', '["巖磴列云旗，吾君訪道时。","乾行万物覩，日馭六龙遲。","望远迴天顧，登高动睿词。","願因山作壽，长保會昌期。"]', '诗', 'shi', '', NULL, '奉和登會昌山應制 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1541ca51-f544-437b-bb53-0d55627ab52d', '正月十五日夜應制', '正月十五日夜應制', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["洛城三五夜，天子萬年春。","綵仗移雙闕，瓊筵會九賓。","舞成蒼頡字，燈作法王輪。","不覺東方日，遙垂御藻新。"]', '["洛城三五夜，天子万年春。","綵仗移雙闕，瓊筵會九賓。","舞成蒼頡字，灯作法王輪。","不覺东方日，遙垂御藻新。"]', '诗', 'shi', '', NULL, '正月十五日夜應制 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f3198af-1f07-47c0-a87f-5e3cc5ebcb26', '奉和御製登鴛鴦樓即目應制', '奉和御製登鴛鴦楼即目應制', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["玉輦下離宮，瓊樓上半空。","方巡五年狩，更闢四門聰。","井邑觀秦野，山河念禹功。","停鑾留睿作，軒檻起南風。"]', '["玉輦下離宮，瓊楼上半空。","方巡五年狩，更闢四门聰。","井邑观秦野，山河念禹功。","停鑾留睿作，軒檻起南风。"]', '诗', 'shi', '', NULL, '奉和御製登鴛鴦樓即目應制 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff99e0d0-d60c-48e0-ac5c-38b24a0eeb30', '進船泛洛水應制', '進船泛洛水應制', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["禁園紆睿覽，仙櫂叶時游。","洛北風花樹，江南彩畫舟。","芳生蘭蕙草，春入鳳凰樓。","興盡離宮暮，煙光起夕流。"]', '["禁园紆睿覽，仙櫂叶时游。","洛北风花樹，江南彩畫舟。","芳生蘭蕙草，春入鳳凰楼。","兴尽離宮暮，煙光起夕流。"]', '诗', 'shi', '', NULL, '進船泛洛水應制 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bb94dce-f83f-4659-9d16-dcbad1592865', '和常州崔使君寒食夜', '和常州崔使君寒食夜', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["聞道清明近，春庭向夕闌。","行遊晝不厭，風物夜宜看。","斗柄更初轉，梅香暗裏殘。","無勞秉華燭，清月在南端。"]', '["闻道清明近，春庭向夕闌。","行游晝不厭，风物夜宜看。","斗柄更初轉，梅香暗裏殘。","無勞秉华燭，清月在南端。"]', '诗', 'shi', '', NULL, '和常州崔使君寒食夜 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8cd2910-f2b2-45b6-8ff3-727e7e416b21', '和韋兄春日南亭宴兄弟', '和韋兄春日南亭宴兄弟', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["臺閣升高位，園林隔舊鄉。","忽聞歌棣萼，還比報瓊芳。","門向宜春近，郊連御宿長。","德星常有會，相望在文昌。"]', '["台閣升高位，园林隔旧乡。","忽闻歌棣萼，還比報瓊芳。","门向宜春近，郊連御宿长。","德星常有會，相望在文昌。"]', '诗', 'shi', '', NULL, '和韋兄春日南亭宴兄弟 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27740b09-a53f-40ec-8e6c-ec678db07f41', '奉和崔司馬遊雲門寺', '奉和崔司马游云门寺', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["繫馬清溪樹，禪門春氣濃。","香臺花下出，講坐竹間逢。","覺路山童引，經行谷鳥從。","更言窮寂滅，回策上南峰。"]', '["繫马清溪樹，禪门春氣濃。","香台花下出，講坐竹间逢。","覺路山童引，經行谷鸟從。","更言窮寂滅，回策上南峰。"]', '诗', 'shi', '', NULL, '奉和崔司馬遊雲門寺 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c99ccfe1-f1eb-4573-9c6b-4611359f3df9', '酬萬八賀九雲門下歸溪中作', '酬万八賀九云门下归溪中作', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["晚從靈境出，林壑曙雲飛。","稍覺清溪盡，回瞻畫剎微。","獨園餘興在，孤櫂宿心違。","更憶登攀處，天香滿袖歸。"]', '["晚從靈境出，林壑曙云飞。","稍覺清溪尽，回瞻畫剎微。","独园餘兴在，孤櫂宿心違。","更憶登攀处，天香满袖归。"]', '诗', 'shi', '', NULL, '酬萬八賀九雲門下歸溪中作 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fa85826-eacc-420c-971e-9ce5f3d353ed', '春初送呂補闕往西嶽勒碑得雲字', '春初送呂補闕往西嶽勒碑得云字', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["刻石記天文，朝推谷子雲。","篋中緘聖札，巖下揖神君。","語別梅初豔，爲期草欲薰。","往來春不盡，離思莫氛氳。"]', '["刻石記天文，朝推谷子云。","篋中緘聖札，巖下揖神君。","語別梅初豔，爲期草欲薰。","往来春不尽，離思莫氛氳。"]', '诗', 'shi', '', NULL, '春初送呂補闕往西嶽勒碑得雲字 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb4e38f6-9e29-4a9c-b209-a3039bde1a1f', '送越州裴參軍充使入京', '送越州裴參軍充使入京', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["日落川徑寒，離心苦未安。","客愁西向盡，鄉夢北歸難。","霜果林中變，秋花水上殘。","明朝渡江後，雲物向南看。"]', '["日落川徑寒，離心苦未安。","客愁西向尽，乡梦北归难。","霜果林中变，秋花水上殘。","明朝渡江後，云物向南看。"]', '诗', 'shi', '', NULL, '送越州裴參軍充使入京 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('403b2fa0-1735-499d-8d34-3ab711de3c05', '送周判官往台州', '送周判官往台州', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["吾宗長作賦，登陸訪天台。","星使行看入，雲仙意轉催。","飲冰攀璀璨，驅傳歷莓苔。","日暮東郊別，真情去不回。"]', '["吾宗长作賦，登陸訪天台。","星使行看入，云仙意轉催。","饮冰攀璀璨，驱傳歷莓苔。","日暮东郊別，真情去不回。"]', '诗', 'shi', '', NULL, '送周判官往台州 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bd0fc18-bedb-4192-a865-06b3578c688e', '送魏騎曹充宇文侍御判官分按山南', '送魏騎曹充宇文侍御判官分按山南', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["雲雨陽臺路，光華驛騎巡。","勸農開夢土，恤隱惠荆人。","樓迥吟黃鶴，江長望白蘋。","觀風布明詔，更是漢南春。"]', '["云雨陽台路，光华驛騎巡。","勸農开梦土，恤隐惠荆人。","楼迥吟黄鹤，江长望白蘋。","观风布明詔，更是漢南春。"]', '诗', 'shi', '', NULL, '送魏騎曹充宇文侍御判官分按山南 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72694080-ba9a-4632-9b7e-3a62cac101fb', '送蘇郎中綰出佐荆州', '送蘇郎中綰出佐荆州', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["神仙久留滯，清切佇飛翻。","忽佐南方牧，何時西掖垣。","高車自蘭省，便道出荆門。","不見河梁別，空銷郢路魂。"]', '["神仙久留滯，清切佇飞翻。","忽佐南方牧，何时西掖垣。","高车自蘭省，便道出荆门。","不见河梁別，空銷郢路魂。"]', '诗', 'shi', '', NULL, '送蘇郎中綰出佐荆州 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc8129c5-f76f-4530-a5df-847d4b6f59dd', '冬末送魏起居赴京', '冬末送魏起居赴京', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["大名將起魏，良史更逢遷。","驛騎朝丹闕，關亭望紫煙。","西京春色近，東觀物華偏。","早赴王正月，揮毫記首年。"]', '["大名將起魏，良史更逢遷。","驛騎朝丹闕，关亭望紫煙。","西京春色近，东观物华偏。","早赴王正月，揮毫記首年。"]', '诗', 'shi', '', NULL, '冬末送魏起居赴京 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee037111-955b-4523-9280-294c7a2c39ac', '送李補闕攝御史充河西節度判官', '送李補闕攝御史充河西節度判官', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["昔年叨補衮，邊地亦埋輪。","官序慙先達，才名畏後人。","西戎雖獻款，上策恥和親。","早赴前軍幕，長清外域塵。"]', '["昔年叨補衮，邊地亦埋輪。","官序慙先達，才名畏後人。","西戎雖獻款，上策恥和親。","早赴前軍幕，长清外域塵。"]', '诗', 'shi', '', NULL, '送李補闕攝御史充河西節度判官 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d49d11e5-8585-4003-807e-4357323c1c2e', '送趙評事攝御史監軍嶺南', '送趙評事攝御史監軍嶺南', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["議獄持邦典，臨戎假憲威。","風從閶闔去，霜入洞庭飛。","篁竹迎金鼓，樓船引繡衣。","明年拜真月，南斗使星歸。"]', '["議獄持邦典，臨戎假憲威。","风從閶闔去，霜入洞庭飞。","篁竹迎金鼓，楼船引繡衣。","明年拜真月，南斗使星归。"]', '诗', 'shi', '', NULL, '送趙評事攝御史監軍嶺南 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('006e732d-2d15-42cf-9e0e-1c9282fd9e30', '送靳十五侍御使蜀', '送靳十五侍御使蜀', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["天使出霜臺，行人擇吏才。","傳車春色送，離興夕陽催。","驛遶巴江轉，關迎劒道開。","西南一何幸，前後二龍來。"]', '["天使出霜台，行人擇吏才。","傳车春色送，離兴夕陽催。","驛遶巴江轉，关迎劒道开。","西南一何幸，前後二龙来。"]', '诗', 'shi', '', NULL, '送靳十五侍御使蜀 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bfafcb5-a3c8-43b7-892d-179ca8445df4', '送李給事歸徐州覲省', '送李給事归徐州覲省', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["列位登青瑣，還鄉復綵衣。","共言晨省日，便是晝遊歸。","春水經梁宋，晴山入海沂。","莫愁東路遠，四牡正騑騑。"]', '["列位登青瑣，還乡复綵衣。","共言晨省日，便是晝游归。","春水經梁宋，晴山入海沂。","莫愁东路远，四牡正騑騑。"]', '诗', 'shi', '', NULL, '送李給事歸徐州覲省 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2668872b-5c8a-45af-9a09-ea9314b30f6e', '送杜侍御赴上都', '送杜侍御赴上都', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["避馬臺中貴，登車嶺外遙。","還因貢賦禮，來謁大明朝。","地入商山路，鄉連渭水橋。","承恩返南越，尊酒重相邀。"]', '["避马台中貴，登车嶺外遙。","還因貢賦禮，来謁大明朝。","地入商山路，乡連渭水橋。","承恩返南越，尊酒重相邀。"]', '诗', 'shi', '', NULL, '送杜侍御赴上都 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e731f0bb-24f2-42fb-ac7a-a79bbe04858a', '送張環攝御史監南選', '送張环攝御史監南選', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["漢使得張綱，威名攝遠方。","恩霑柱下史，榮比選曹郎。","江帶黔中闊，山連峽水長。","莫愁炎暑地，秋至有嚴霜。"]', '["漢使得張綱，威名攝远方。","恩霑柱下史，榮比選曹郎。","江带黔中闊，山連峽水长。","莫愁炎暑地，秋至有嚴霜。"]', '诗', 'shi', '', NULL, '送張環攝御史監南選 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da73c986-de69-47b7-9357-1e98cb5c8ec7', '宴越府陳法曹西亭', '宴越府陳法曹西亭', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["公府西巖下，紅亭間白雲。","雪梅初度臘，煙竹稍迎曛。","水木涵澄景，簾櫳引霽氛。","江南歸思逼，春鴈不堪聞。"]', '["公府西巖下，紅亭间白云。","雪梅初度臘，煙竹稍迎曛。","水木涵澄景，簾櫳引霽氛。","江南归思逼，春鴈不堪闻。"]', '诗', 'shi', '', NULL, '宴越府陳法曹西亭 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05b87ce2-d432-48d8-ae41-e3328cb6008a', '同邢判官尋龍湍觀歸湖中', '同邢判官尋龙湍观归湖中', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["星使下仙京，雲湖喜晝晴。","更從探穴處，還作櫂歌行。","絲管荷風入，簾帷竹氣清。","莫愁歸路遠，水月夜虛明。"]', '["星使下仙京，云湖喜晝晴。","更從探穴处，還作櫂歌行。","絲管荷风入，簾帷竹氣清。","莫愁归路远，水月夜虛明。"]', '诗', 'shi', '', NULL, '同邢判官尋龍湍觀歸湖中 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7854620-bcc1-428e-8b83-a853d86a46df', '尋龍湍', '尋龙湍', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["仙穴尋遺跡，輕舟愛水鄉。","溪流一曲盡，山路九峰長。","漁父歌金洞，江妃舞翠房。","遙憐葛仙宅，真氣共微茫。"]', '["仙穴尋遺跡，轻舟愛水乡。","溪流一曲尽，山路九峰长。","漁父歌金洞，江妃舞翠房。","遙怜葛仙宅，真氣共微茫。"]', '诗', 'shi', '', NULL, '尋龍湍 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61405096-5464-46ed-8161-8eb533ee4a46', '宿雲門寺閣', '宿云门寺閣', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["香閣東山下，煙花象外幽。","懸燈千嶂夕，卷幔五湖秋。","畫壁餘鴻鴈，紗窓宿斗牛。","更疑天路近，夢與白雲遊。"]', '["香閣东山下，煙花象外幽。","懸灯千嶂夕，卷幔五湖秋。","畫壁餘鴻鴈，紗窓宿斗牛。","更疑天路近，梦與白云游。"]', '诗', 'shi', '', NULL, '宿雲門寺閣 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f3b6888-5e5f-4932-83c7-616ad697aebe', '揚子江樓', '揚子江楼', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["揚子何年邑，雄圖作楚關。","江連二妃渚，雲近八公山。","驛道[青]楓外，人煙綠嶼間。","晚來潮正滿，數處落帆還。"]', '["揚子何年邑，雄圖作楚关。","江連二妃渚，云近八公山。","驛道[青]楓外，人煙綠嶼间。","晚来潮正满，數处落帆還。"]', '诗', 'shi', '', NULL, '揚子江樓 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc969e93-b520-4127-868f-c4e000652ab3', '淮陰夜宿二首 一', '淮陰夜宿二首 一', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["水國南無畔，扁舟北未期。","鄉情淮上失，歸夢郢中疑。","木落知寒近，山長見日遲。","客行心緒亂，不及洛陽時。"]', '["水国南無畔，扁舟北未期。","乡情淮上失，归梦郢中疑。","木落知寒近，山长见日遲。","客行心緒亂，不及洛陽时。"]', '诗', 'shi', '', NULL, '淮陰夜宿二首 一 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('103fde91-0c2f-4bc6-8502-de2bf38b26f2', '淮陰夜宿二首 二', '淮陰夜宿二首 二', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["永夕臥煙塘，蕭條天一方。","秋風淮水落，寒夜楚歌長。","宿莽非中土，鱸魚豈我鄉。","孤舟行已倦，南越尚茫茫。"]', '["永夕臥煙塘，蕭條天一方。","秋风淮水落，寒夜楚歌长。","宿莽非中土，鱸鱼豈我乡。","孤舟行已倦，南越尚茫茫。"]', '诗', 'shi', '', NULL, '淮陰夜宿二首 二 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46354a02-69ce-43b9-afd7-12a7b49ae671', '下京口埭夜行', '下京口埭夜行', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["孤帆度綠氛，寒浦落紅曛。","江樹朝來出，吳歌夜漸聞。","南溟接潮水，北斗近鄉雲。","行役從茲去，歸情入鴈羣。"]', '["孤帆度綠氛，寒浦落紅曛。","江樹朝来出，吳歌夜漸闻。","南溟接潮水，北斗近乡云。","行役從茲去，归情入鴈羣。"]', '诗', 'shi', '', NULL, '下京口埭夜行 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73a77401-6195-4226-9dd5-1d4bff2edbe8', '山行遇雨', '山行遇雨', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["驟雨晝氤氳，空天望不分。","暗山唯覺電，窮海但生雲。","涉澗猜行潦，緣崖畏宿氛。","夜來江月霽，櫂唱此中聞。"]', '["驟雨晝氤氳，空天望不分。","暗山唯覺電，窮海但生云。","涉澗猜行潦，緣崖畏宿氛。","夜来江月霽，櫂唱此中闻。"]', '诗', 'shi', '', NULL, '山行遇雨 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15e71264-4ba0-4dfb-9fe1-e874cc5f0063', '夜到潤州', '夜到潤州', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["夜入丹陽郡，天高氣象秋。","海隅雲漢轉，江畔火星流。","城郭傳金柝，閭閻閉綠洲。","客行凡幾夜，新月再如鉤。"]', '["夜入丹陽郡，天高氣象秋。","海隅云漢轉，江畔火星流。","城郭傳金柝，閭閻閉綠洲。","客行凡幾夜，新月再如鉤。"]', '诗', 'shi', '', NULL, '夜到潤州 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8665cd4a-9bc7-40d8-8ea5-8ac3b866d15c', '和常州崔使君詠後庭梅二首 一', '和常州崔使君詠後庭梅二首 一', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["聞唱梅花落，江南春意深。","更傳千里外，來入越人吟。","弱幹紅妝倚，繁香翠羽尋。","庭中自公日，歌舞向芳陰。"]', '["闻唱梅花落，江南春意深。","更傳千里外，来入越人吟。","弱幹紅妝倚，繁香翠羽尋。","庭中自公日，歌舞向芳陰。"]', '诗', 'shi', '', NULL, '和常州崔使君詠後庭梅二首 一 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f9fd0ad-8527-4d0a-8ad1-c8c07c0a8131', '和常州崔使君詠後庭梅二首 二', '和常州崔使君詠後庭梅二首 二', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["梅院重門掩，遙遙歌吹邊。","庭深人不見，春至曲能傳。","花落彈棋處，香來薦枕前。","使君停五馬，行樂此中偏。"]', '["梅院重门掩，遙遙歌吹邊。","庭深人不见，春至曲能傳。","花落彈棋处，香来薦枕前。","使君停五马，行乐此中偏。"]', '诗', 'shi', '', NULL, '和常州崔使君詠後庭梅二首 二 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f35caecc-8e5c-40ca-a748-223a43ca910c', '同和詠樓前海石榴二首 一', '同和詠楼前海石榴二首 一', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["客自新亭郡，朝來數物華。","傳君妓樓好，初落海榴花。","露色珠簾映，香風粉壁遮。","更宜林下雨，日晚逐行車。"]', '["客自新亭郡，朝来數物华。","傳君妓楼好，初落海榴花。","露色珠簾映，香风粉壁遮。","更宜林下雨，日晚逐行车。"]', '诗', 'shi', '', NULL, '同和詠樓前海石榴二首 一 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('712aa8b3-855c-4714-b45e-663d6fa5a374', '同和詠樓前海石榴二首 二', '同和詠楼前海石榴二首 二', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["海上移珍木，樓前詠所思。","遙聞下車日，正在落花時。","舊綠香行蓋，新紅洒步綦。","從來寒不易，終見久逾滋。"]', '["海上移珍木，楼前詠所思。","遙闻下车日，正在落花时。","旧綠香行蓋，新紅洒步綦。","從来寒不易，終见久逾滋。"]', '诗', 'shi', '', NULL, '同和詠樓前海石榴二首 二 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48e266b7-ec77-4468-88c8-4dda6f4bf22a', '故右丞相贈太師燕文貞公挽詞二首 一', '故右丞相贈太師燕文貞公挽词二首 一', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["海內文章伯，朝端禮樂英。","一言興寶運，三入濟羣生。","命與才相偶，年將位不幷。","台星忽已坼，流慟軫皇情。"]', '["海內文章伯，朝端禮乐英。","一言兴寶運，三入濟羣生。","命與才相偶，年將位不幷。","台星忽已坼，流慟軫皇情。"]', '诗', 'shi', '', NULL, '故右丞相贈太師燕文貞公挽詞二首 一 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1bda0f6-5c48-45c6-886a-f68c8781f606', '故右丞相贈太師燕文貞公挽詞二首 二', '故右丞相贈太師燕文貞公挽词二首 二', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["甲第三重戟，高門四列侯。","已成冠蓋里，更有鳳皇樓。","人世方爲樂，生涯遽若休。","空餘掌綸地，傳慶百千秋。"]', '["甲第三重戟，高门四列侯。","已成冠蓋里，更有鳳皇楼。","人世方爲乐，生涯遽若休。","空餘掌綸地，傳慶百千秋。"]', '诗', 'shi', '', NULL, '故右丞相贈太師燕文貞公挽詞二首 二 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c408c2f1-63a3-41f0-8685-70aee6c960b0', '故陳州刺史贈兵部尚書韋公挽詞', '故陳州刺史贈兵部尚书韋公挽词', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["奕葉金章貴，連枝鼎位尊。","台庭爲鳳穴，相府是鴒原。","世閱空悲命，泉幽不返魂。","惟餘漢臣史，繼術贊韋門。"]', '["奕葉金章貴，連枝鼎位尊。","台庭爲鳳穴，相府是鴒原。","世閱空悲命，泉幽不返魂。","惟餘漢臣史，繼術贊韋门。"]', '诗', 'shi', '', NULL, '故陳州刺史贈兵部尚書韋公挽詞 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a0ea00a-a8fa-46e7-8efb-c15ce169c82f', '故程將軍妻南陽郡夫人樊氏挽歌', '故程將軍妻南陽郡夫人樊氏挽歌', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["德配程休甫，名高魯季姜。","寵榮蒼玉珮，宴夢鬱金堂。","白日期偕老，幽泉忽悼亡。","國風猶在詠，江漢近南陽。"]', '["德配程休甫，名高魯季姜。","寵榮蒼玉珮，宴梦鬱金堂。","白日期偕老，幽泉忽悼亡。","国风猶在詠，江漢近南陽。"]', '诗', 'shi', '', NULL, '故程將軍妻南陽郡夫人樊氏挽歌 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3887366a-5ca5-4e31-a43a-276ecef05990', '和上巳連寒食有懷京洛', '和上巳連寒食有懷京洛', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["天津御柳碧遙遙，軒騎相從半下朝。","行樂光輝寒食借，太平歌舞晚春饒。","紅妝樓下東郊道，青草洲邊南渡橋。","坐見司空掃西第，看君侍從落花朝。"]', '["天津御柳碧遙遙，軒騎相從半下朝。","行乐光輝寒食借，太平歌舞晚春饒。","紅妝楼下东郊道，青草洲邊南渡橋。","坐见司空掃西第，看君侍從落花朝。"]', '诗', 'shi', '', NULL, '和上巳連寒食有懷京洛 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af0e436f-57cb-4972-a24a-c8ecc6a328a2', '和左司張員外自洛使入京中路先赴長安逢立春日贈韋侍御等諸公', '和左司張員外自洛使入京中路先赴长安逢立春日贈韋侍御等諸公', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["忽覩雲間數鴈回，更逢山上正花開。","河邊淑氣迎芳草，林下輕風待落梅。","秋憲府中高唱入，春卿署裏和歌來。","共言東閣招賢地，自有西征謝傅才。"]', '["忽覩云间數鴈回，更逢山上正花开。","河邊淑氣迎芳草，林下轻风待落梅。","秋憲府中高唱入，春卿署裏和歌来。","共言东閣招賢地，自有西征謝傅才。"]', '诗', 'shi', '', NULL, '和左司張員外自洛使入京中路先赴長安逢立春日贈韋侍御等諸公 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4761e170-dc78-41ae-816d-0410a6c2bfa8', '和崔司馬登稱心山寺', '和崔司马登稱心山寺', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["郡府乘休日，王城訪道初。","覺花迎步履，香草藉行車。","倚閣觀無際，尋山坐太虛。","巖空迷禹跡，海靜望秦餘。","翡翠巢珠網，鵾雞間綺疏。","地靈資淨土，水若護真如。","寶樹誰攀折，禪雲自卷舒。","晴分五湖勢，煙合九夷居。","生滅紛無象，窺臨已得魚。","嘗聞寶刀贈，今日奉瓊琚。"]', '["郡府乘休日，王城訪道初。","覺花迎步履，香草藉行车。","倚閣观無際，尋山坐太虛。","巖空迷禹跡，海静望秦餘。","翡翠巢珠網，鵾雞间綺疏。","地靈資淨土，水若護真如。","寶樹誰攀折，禪云自卷舒。","晴分五湖勢，煙合九夷居。","生滅紛無象，窺臨已得鱼。","嘗闻寶刀贈，今日奉瓊琚。"]', '诗', 'shi', '', NULL, '和崔司馬登稱心山寺 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3cb24d4-7cc5-47af-bcc5-1cfb41c03f3d', '奉和李右相中書壁畫山水', '奉和李右相中书壁畫山水', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["廟堂多暇日，山水契中情。","欲寫高深趣，還因藻繪成。","九江臨戶牖，三峽繞檐楹。","花柳窮年發，煙雲逐意生。","能令萬里近，不覺四時行。","氣染荀香馥，光含樂鏡清。","詠歌齊出處，圖畫表沖盈。","自保千年遇，何論八載榮。"]', '["廟堂多暇日，山水契中情。","欲寫高深趣，還因藻繪成。","九江臨戶牖，三峽繞檐楹。","花柳窮年發，煙云逐意生。","能令万里近，不覺四时行。","氣染荀香馥，光含乐镜清。","詠歌齊出处，圖畫表沖盈。","自保千年遇，何論八載榮。"]', '诗', 'shi', '', NULL, '奉和李右相中書壁畫山水 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6c82554-53e1-411c-9211-20bdc5147204', '奉和李右相賞會昌林亭', '奉和李右相賞會昌林亭', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["賢相初陪蹕，靈山本降神。","作京雄近縣，開閣寵平津。","地勝林亭好，時清宴賞頻。","百泉縈草木，萬井布郊畛。","德與春和盛，功將造化鄰。","還嗤渭濱叟，歲晚獨垂綸。"]', '["賢相初陪蹕，靈山本降神。","作京雄近縣，开閣寵平津。","地勝林亭好，时清宴賞頻。","百泉縈草木，万井布郊畛。","德與春和盛，功將造化鄰。","還嗤渭濱叟，歲晚独垂綸。"]', '诗', 'shi', '', NULL, '奉和李右相賞會昌林亭 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4b4899e-7941-49e6-8f62-4f84e97031f6', '和左衞武倉曹衞中對雨創韻贈右衞李騎曹', '和左衞武倉曹衞中对雨創韻贈右衞李騎曹', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["林父同官意，宣尼久敬交。","文場刊玉篆，武事掌金鐃。","道合宜連茹，時清豈繫匏。","克勤居簿領，多暇屏讙譊。","美酒懷公讌，玄談俟客嘲。","薄雲生北闕，飛雨自西郊。","院暑便清曠，庭蕪覺漸苞。","高門關詎閉，逸韻柱難膠。","枳棘鸞無歎，椅梧鳳必巢。","忽聞徵竝作，觀海媿堂坳。"]', '["林父同官意，宣尼久敬交。","文場刊玉篆，武事掌金鐃。","道合宜連茹，时清豈繫匏。","克勤居簿領，多暇屏讙譊。","美酒懷公讌，玄談俟客嘲。","薄云生北闕，飞雨自西郊。","院暑便清曠，庭蕪覺漸苞。","高门关詎閉，逸韻柱难膠。","枳棘鸾無歎，椅梧鳳必巢。","忽闻徵竝作，观海媿堂坳。"]', '诗', 'shi', '', NULL, '和左衞武倉曹衞中對雨創韻贈右衞李騎曹 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc8e091b-eb56-45e2-8089-d508fa1a6aaa', '送新羅法師還國', '送新羅法師還国', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["異域今無外，高僧代所稀。","苦心歸寂滅，宴坐得精微。","持鉢何年至，傳燈是日歸。","上卿揮別藻，中禁下禪衣。","海闊杯還度，雲遙錫更飛。","此行迷處所，何以慰虔祈。"]', '["異域今無外，高僧代所稀。","苦心归寂滅，宴坐得精微。","持鉢何年至，傳灯是日归。","上卿揮別藻，中禁下禪衣。","海闊杯還度，云遙錫更飞。","此行迷处所，何以慰虔祈。"]', '诗', 'shi', '', NULL, '送新羅法師還國 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c59a3ffd-f125-4524-8a04-b1b95ad2a55d', '送趙大夫護邊', '送趙大夫護邊', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["外域分都護，中臺命職方。","欲傳清廟略，先取劇曹郎。","已佩登壇印，猶懷伏奏香。","百壺開祖餞，駟牡戒戎裝。","青海連西掖，黃河帶北涼。","關山瞻漢月，戈劒宿胡霜。","體國才先著，論兵策復長。","果持文武術，還繼杜當陽。"]', '["外域分都護，中台命職方。","欲傳清廟略，先取劇曹郎。","已佩登壇印，猶懷伏奏香。","百壺开祖餞，駟牡戒戎裝。","青海連西掖，黄河带北涼。","关山瞻漢月，戈劒宿胡霜。","體国才先著，論兵策复长。","果持文武術，還繼杜當陽。"]', '诗', 'shi', '', NULL, '送趙大夫護邊 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('814d2107-c19e-4287-87cb-e17cde697893', '立秋日題安昌寺北山亭', '立秋日題安昌寺北山亭', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["樓觀倚長霄，登攀及霽朝。","高如石門頂，勝擬赤城標。","天路雲虹近，人寰氣象遙。","山圍伯禹廟，江落伍胥潮。","徂暑迎秋薄，涼風是日飄。","果林餘苦李，萍水覆甘蕉。","覽古嗟夷漫，凌空愛泬寥。","更聞金剎下，鐘梵晚蕭蕭。"]', '["楼观倚长霄，登攀及霽朝。","高如石门頂，勝擬赤城標。","天路云虹近，人寰氣象遙。","山圍伯禹廟，江落伍胥潮。","徂暑迎秋薄，涼风是日飄。","果林餘苦李，萍水覆甘蕉。","覽古嗟夷漫，凌空愛泬寥。","更闻金剎下，鐘梵晚蕭蕭。"]', '诗', 'shi', '', NULL, '立秋日題安昌寺北山亭 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b595c6c8-9229-474b-8d80-0cc988c8a1f6', '登越州城', '登越州城', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["越嶂繞層城，登臨萬象清。","封圻滄海合，廛市碧湖明。","曉日漁歌滿，芳春櫂唱行。","山風吹美箭，田雨潤香秔。","代閱英靈盡，人閑吏隱幷。","贈言王逸少，已見曲池平。"]', '["越嶂繞層城，登臨万象清。","封圻滄海合，廛市碧湖明。","晓日漁歌满，芳春櫂唱行。","山风吹美箭，田雨潤香秔。","代閱英靈尽，人闲吏隐幷。","贈言王逸少，已见曲池平。"]', '诗', 'shi', '', NULL, '登越州城 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70185202-25af-412a-b5f9-5dc38903619d', '江行有懷', '江行有懷', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["秋水明川路，輕舟轉石圻。","霜多山橘熟，寒至浦禽稀。","飛席乘風勢，迴流蕩日暉。","晝行疑海若，夕夢識江妃。","野霽看吳盡，天長望洛非。","不知何歲月，一似暮潮歸。"]', '["秋水明川路，轻舟轉石圻。","霜多山橘熟，寒至浦禽稀。","飞席乘风勢，迴流蕩日暉。","晝行疑海若，夕梦識江妃。","野霽看吳尽，天长望洛非。","不知何歲月，一似暮潮归。"]', '诗', 'shi', '', NULL, '江行有懷 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c7fd6e3-4956-4dad-9c0d-d336cb609602', '長洲苑', '长洲苑', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["吳王初鼎峙，羽獵騁雄才。","輦道閶門出，軍容茂苑來。","山從列嶂轉，江自繞林迴。","劒騎緣汀入，旌門隔嶼開。","合離紛若電，馳逐溢成雷。","勝地虞人守，歸舟漢女陪。","可憐夷漫處，猶在洞庭隈。","山靜吟猿父，城空應雉媒。","戎行委喬木，馬跡盡黃埃。","攬涕問遺老，繁華安在哉。"]', '["吳王初鼎峙，羽獵騁雄才。","輦道閶门出，軍容茂苑来。","山從列嶂轉，江自繞林迴。","劒騎緣汀入，旌门隔嶼开。","合離紛若電，驰逐溢成雷。","勝地虞人守，归舟漢女陪。","可怜夷漫处，猶在洞庭隈。","山静吟猿父，城空應雉媒。","戎行委喬木，马跡尽黄埃。","攬涕问遺老，繁华安在哉。"]', '诗', 'shi', '', NULL, '長洲苑 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1f7ade0-dbf7-42e2-8245-410f06dcb360', '和詠廨署有櫻桃', '和詠廨署有櫻桃', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["上林天禁裏，芳樹有紅櫻。","江國今來見，君門春意生。","香從花綬轉，色繞佩珠明。","海鳥銜初實，吳姬掃落英。","切將稀取貴，羞與衆同榮。","爲此堪攀折，芳蹊處處成。"]', '["上林天禁裏，芳樹有紅櫻。","江国今来见，君门春意生。","香從花綬轉，色繞佩珠明。","海鸟銜初實，吳姬掃落英。","切將稀取貴，羞與衆同榮。","爲此堪攀折，芳蹊处处成。"]', '诗', 'shi', '', NULL, '和詠廨署有櫻桃 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc65010e-e74e-4882-8d76-e1423ed0b200', '同洛陽李少府觀永樂公主入蕃', '同洛陽李少府观永乐公主入蕃', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["邊地鶯花少，年來未覺新。","美人天上落，龍塞始應春。"]', '["邊地鶯花少，年来未覺新。","美人天上落，龙塞始應春。"]', '诗', 'shi', '', NULL, '同洛陽李少府觀永樂公主入蕃 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c775b87-805f-45d4-954e-d0a747ad4c79', '途中口號', '途中口號', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["鄴城東北望陵臺，珠翠繁華去不迴。","無復新妝豔紅粉，空餘故壟滿青苔。"]', '["鄴城东北望陵台，珠翠繁华去不迴。","無复新妝豔紅粉，空餘故壟满青苔。"]', '诗', 'shi', '', NULL, '途中口號 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67866d08-d669-45e3-b804-ec3192aaf75f', '晦日湖塘', '晦日湖塘', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["吉日初成晦，方塘遍是春。","落花迎二月，芳樹歷三旬。","公子能留客，巫陽好解神。","夜還何慮暗，秉燭向城闉。"]', '["吉日初成晦，方塘遍是春。","落花迎二月，芳樹歷三旬。","公子能留客，巫陽好解神。","夜還何慮暗，秉燭向城闉。"]', '诗', 'shi', '', NULL, '晦日湖塘 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('618b91b5-13b0-415c-8402-0fa9ab341591', '句', '句', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["野煙出爐上，山花落鏡中。"]', '["野煙出爐上，山花落镜中。"]', '诗', 'shi', '', NULL, '句 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dc010f6-30c6-4041-a0f5-3b8f33c6e46e', '從軍行', '從軍行', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["塞北胡霜下，營州索兵救。","夜裏偷道行，將軍馬亦瘦。","刀光照塞月，陣色明如晝。","傳聞賊滿山，已共前鋒鬬。"]', '["塞北胡霜下，營州索兵救。","夜裏偷道行，將軍马亦瘦。","刀光照塞月，陣色明如晝。","傳闻賊满山，已共前鋒鬬。"]', '诗', 'shi', '', NULL, '從軍行 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('911c8a71-d6a7-4639-8797-712e47ac1e75', '雜詩', '杂诗', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["逢著平樂兒，論交鞍馬前。","與酤一斗酒，恰用十千錢。","後余在關內，作事多迍邅。","何肯相救援，徒聞寶劒篇。"]', '["逢著平乐兒，論交鞍马前。","與酤一斗酒，恰用十千錢。","後余在关內，作事多迍邅。","何肯相救援，徒闻寶劒篇。"]', '诗', 'shi', '', NULL, '雜詩 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d324e92c-f390-46f6-805e-f1dcd7e81f71', '古意', '古意', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["紅荷楚水曲，彪炳爍晨霞。","未得兩回摘，秋風吹却花。","時芳不待妾，玉珮無處誇。","悔不盛年時，嫁與青樓家。"]', '["紅荷楚水曲，彪炳爍晨霞。","未得兩回摘，秋风吹却花。","时芳不待妾，玉珮無处誇。","悔不盛年时，嫁與青楼家。"]', '诗', 'shi', '', NULL, '古意 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc2e8cd5-0782-414e-bda7-c79da4b3bb34', '宿法華寺', '宿法华寺', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["松雨時復滴，寺門清且涼。","此心竟誰證，回憩支公牀。","壁畫感靈跡，龕經傳異香。","獨遊寄象外，忽忽歸南昌。"]', '["松雨时复滴，寺门清且涼。","此心竟誰證，回憩支公牀。","壁畫感靈跡，龕經傳異香。","独游寄象外，忽忽归南昌。"]', '诗', 'shi', '', NULL, '宿法華寺 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b06879a-c2fb-4643-8115-c6603a019834', '題豫章館', '題豫章館', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["楊柳映春江，江南轉佳麗。","吳門綠波裏，越國青山際。","遊宦常往來，津亭暫臨憩。","驛前蒼石沒，浦外湖沙細。","向晚宴且久，孤舟冏然逝。","雲留西北客，氣歇東南帝。","獨有萋萋心，誰知怨芳歲。"]', '["楊柳映春江，江南轉佳丽。","吳门綠波裏，越国青山際。","游宦常往来，津亭暫臨憩。","驛前蒼石沒，浦外湖沙細。","向晚宴且久，孤舟冏然逝。","云留西北客，氣歇东南帝。","独有萋萋心，誰知怨芳歲。"]', '诗', 'shi', '', NULL, '題豫章館 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a71bbdb-daeb-496b-84f0-38dd78f8d49a', '石頭灘作', '石头灘作', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["悵矣秋風時，余臨石頭瀨。","因高見遠境，盡此數州內。","羽山數點青，海岸雜光碎。","離離樹木少，漭漭湖波大。","日暮千里帆，南飛落天外。","須臾遂入夜，楚色有微靄。","尋遠跡已窮，遺榮事多昧。","一身猶未理，安得濟時代。","且泛朝夕潮，荷衣蕙爲帶。"]', '["悵矣秋风时，余臨石头瀨。","因高见远境，尽此數州內。","羽山數点青，海岸杂光碎。","離離樹木少，漭漭湖波大。","日暮千里帆，南飞落天外。","須臾遂入夜，楚色有微靄。","尋远跡已窮，遺榮事多昧。","一身猶未理，安得濟时代。","且泛朝夕潮，荷衣蕙爲带。"]', '诗', 'shi', '', NULL, '石頭灘作 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24a802b4-2dfd-40c4-b656-a59bc27c1d30', '漂母岸', '漂母岸', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["泗水入淮處，南邊古岸存。","秦時有漂母，於此飯王孫。","王孫初未遇，寄食何足論。","後爲楚王來，黃金答母恩。","事跡遺在此，空傷千載魂。","茫茫水中渚，上有一孤墩。","遙望不可到，蒼蒼煙樹昏。","幾年崩冢色，每日落潮痕。","古地多陻圮，時哉不敢言。","向夕淚霑裳，遂宿蘆洲村。"]', '["泗水入淮处，南邊古岸存。","秦时有漂母，於此飯王孫。","王孫初未遇，寄食何足論。","後爲楚王来，黄金答母恩。","事跡遺在此，空傷千載魂。","茫茫水中渚，上有一孤墩。","遙望不可到，蒼蒼煙樹昏。","幾年崩冢色，每日落潮痕。","古地多陻圮，时哉不敢言。","向夕泪霑裳，遂宿蘆洲村。"]', '诗', 'shi', '', NULL, '漂母岸 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aad9c33-abf8-4236-8508-9907bf16abb9', '對酒吟', '对酒吟', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["行行日將夕，荒村古冢無人跡。","蒙籠荆棘一鳥吟，屢唱提壺沽酒喫。","古人不達酒不足，遺恨精靈傳此曲。","寄言世上諸少年，平生且盡杯中醁。"]', '["行行日將夕，荒村古冢無人跡。","蒙籠荆棘一鸟吟，屢唱提壺沽酒喫。","古人不達酒不足，遺恨精靈傳此曲。","寄言世上諸少年，平生且尽杯中醁。"]', '诗', 'shi', '', NULL, '對酒吟 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46e89ba4-b83f-4183-af4a-1267b3a5afa4', '奉和華清宮觀行香應制', '奉和华清宮观行香應制', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["天子蘂珠宮，樓臺碧落通。","豫遊皆汗漫，齋處即崆峒。","雲物三光裏，君臣一氣中。","道言何所說，寶曆自無窮。"]', '["天子蘂珠宮，楼台碧落通。","豫游皆汗漫，斋处即崆峒。","云物三光裏，君臣一氣中。","道言何所说，寶曆自無窮。"]', '诗', 'shi', '', NULL, '奉和華清宮觀行香應制 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b9796ac-c26f-4488-ab95-c574f1d07966', '七夕', '七夕', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["太守仙潢族，含情七夕多。","扇風生玉漏，置水寫銀河。","閣下陳書籍，閨中曝綺羅。","遙思漢武帝，青鳥幾時過。"]', '["太守仙潢族，含情七夕多。","扇风生玉漏，置水寫銀河。","閣下陳书籍，閨中曝綺羅。","遙思漢武帝，青鸟幾时過。"]', '诗', 'shi', '', NULL, '七夕 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55ac392c-ebd3-4fdb-a9c5-9f0b6c6c0a1d', '宿范浦', '宿范浦', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["月暗潮又落，西陵渡暫停。","村煙和海霧，舟火亂江星。","路轉定山遶，塘連范浦橫。","鴟夷近何去，空山臨滄溟。"]', '["月暗潮又落，西陵渡暫停。","村煙和海霧，舟火亂江星。","路轉定山遶，塘連范浦橫。","鴟夷近何去，空山臨滄溟。"]', '诗', 'shi', '', NULL, '宿范浦 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('031834a5-d244-4311-8c23-9b1c1018960d', '奉和聖製上巳祓禊應制', '奉和聖製上巳祓禊應制', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["元巳秦中節，吾君灞上遊。","鳴鑾通禁苑，別館遶芳洲。","鵷鷺千官列，魚龍百戲浮。","桃花春欲盡，穀雨夜來收。","慶向堯樽祝，歡從楚棹謳。","逸詩何足對，窅作掩東周。"]', '["元巳秦中節，吾君灞上游。","鳴鑾通禁苑，別館遶芳洲。","鵷鷺千官列，鱼龙百戲浮。","桃花春欲尽，穀雨夜来收。","慶向堯樽祝，歡從楚棹謳。","逸诗何足对，窅作掩东周。"]', '诗', 'shi', '', NULL, '奉和聖製上巳祓禊應制 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81588847-ae7f-410b-91b7-56441ccdb81a', '九日侍宴應制', '九日侍宴應制', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["運偶千年聖，時傳九日神。","堯樽列鐘鼓，漢闕闢鉤陳。","金籙三清降，瓊筵五老巡。","始驚蘭佩出，復詠柏梁新。","雲鴈樓前晚，霜花酒裏春。","歡娛無限極，書劒太平人。"]', '["運偶千年聖，时傳九日神。","堯樽列鐘鼓，漢闕闢鉤陳。","金籙三清降，瓊筵五老巡。","始驚蘭佩出，复詠柏梁新。","云鴈楼前晚，霜花酒裏春。","歡娛無限極，书劒太平人。"]', '诗', 'shi', '', NULL, '九日侍宴應制 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91abfcf4-bf83-443d-976f-11f3b1b332f1', '杭州北郭戴氏荷池送侯愉', '杭州北郭戴氏荷池送侯愉', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["秋近萬物肅，況當臨水時。","折花贈歸客，離緒斷荷絲。","誰謂江國永，故人感在茲。","道存過北郭，情極望東菑。","喬木故園意，鳴蟬窮巷悲。","扁舟竟何待，中路每遲遲。"]', '["秋近万物肅，況當臨水时。","折花贈归客，離緒斷荷絲。","誰謂江国永，故人感在茲。","道存過北郭，情極望东菑。","喬木故园意，鳴蟬窮巷悲。","扁舟竟何待，中路每遲遲。"]', '诗', 'shi', '', NULL, '杭州北郭戴氏荷池送侯愉 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2483104b-9d1a-4376-b4af-a864212d0c9d', '怨詞二首 一', '怨词二首 一', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["妾有羅衣裳，秦王在時作。","爲舞春風多，秋來不堪著。"]', '["妾有羅衣裳，秦王在时作。","爲舞春风多，秋来不堪著。"]', '诗', 'shi', '', NULL, '怨詞二首 一 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fba61e93-f905-49a8-b475-cb412860149e', '怨詞二首 二', '怨词二首 二', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["樓頭桃李疎，池上芙蓉落。","織錦猶未成，蛩聲入羅幕。"]', '["楼头桃李疎，池上芙蓉落。","织錦猶未成，蛩声入羅幕。"]', '诗', 'shi', '', NULL, '怨詞二首 二 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd485fea-3025-4224-b8fb-769d56b6cf9a', '古意二首 一', '古意二首 一', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["玉籠薰繡裳，著罷眠洞房。","不能春風裏，吹却蘭麝香。"]', '["玉籠薰繡裳，著罷眠洞房。","不能春风裏，吹却蘭麝香。"]', '诗', 'shi', '', NULL, '古意二首 一 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd57a389-60f1-4019-8b90-bd21ae638695', '古意二首 二', '古意二首 二', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["種棘遮蘼蕪，畏人來采殺。","比至狂夫還，看看幾花發。"]', '["種棘遮蘼蕪，畏人来采殺。","比至狂夫還，看看幾花發。"]', '诗', 'shi', '', NULL, '古意二首 二 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4dab7be-0e5d-4470-b2f4-f611a16a2d5e', '襄陽曲二首 一', '襄陽曲二首 一', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["蕙草嬌紅萼，時光舞碧雞。","城中美年少，相見白銅鞮。"]', '["蕙草嬌紅萼，时光舞碧雞。","城中美年少，相见白銅鞮。"]', '诗', 'shi', '', NULL, '襄陽曲二首 一 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa4076ef-ddda-4c26-ae49-657fba2c3f86', '襄陽曲二首 二', '襄陽曲二首 二', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["少年襄陽地，來往襄陽城。","城中輕薄子，知妾解秦箏。"]', '["少年襄陽地，来往襄陽城。","城中轻薄子，知妾解秦箏。"]', '诗', 'shi', '', NULL, '襄陽曲二首 二 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee46821d-7fb8-4918-9e62-558c884245b6', '魏宮詞', '魏宮词', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["朝日照紅妝，擬上銅雀臺。","畫眉猶未了，魏帝使人催。"]', '["朝日照紅妝，擬上銅雀台。","畫眉猶未了，魏帝使人催。"]', '诗', 'shi', '', NULL, '魏宮詞 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfedded9-b444-499e-8547-d80a5d51feb7', '長信草', '长信草', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["長信宮中草，年年愁處生。","故侵珠履跡，不使玉階行。"]', '["长信宮中草，年年愁处生。","故侵珠履跡，不使玉階行。"]', '诗', 'shi', '', NULL, '長信草 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02f837a3-fc08-4aed-9e43-dbbaa58e6086', '長樂少年行', '长乐少年行', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["遺却珊瑚鞭，白馬驕不行。","章臺折楊柳，春日路傍情。"]', '["遺却珊瑚鞭，白马驕不行。","章台折楊柳，春日路傍情。"]', '诗', 'shi', '', NULL, '長樂少年行 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f4a0b12-ce76-43f9-8e9d-907a0e944e32', '湖南曲', '湖南曲', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["湖南送君去，湖北送君歸。","湖裏鴛鴦鳥，雙雙他自飛。"]', '["湖南送君去，湖北送君归。","湖裏鴛鴦鸟，雙雙他自飞。"]', '诗', 'shi', '', NULL, '湖南曲 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7fbf620-dd82-49d4-afea-a987715c3844', '中流曲', '中流曲', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["歸時日尚早，更欲向芳洲。","渡口水流急，迴船不自由。"]', '["归时日尚早，更欲向芳洲。","渡口水流急，迴船不自由。"]', '诗', 'shi', '', NULL, '中流曲 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fcc8c9e-bbec-450c-9033-ec6376597cb8', '王孫遊', '王孫游', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["自與王孫別，頻看黃鳥飛。","應由春草誤，著處不成歸。"]', '["自與王孫別，頻看黄鸟飞。","應由春草誤，著处不成归。"]', '诗', 'shi', '', NULL, '王孫遊 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ee149ba-d872-4f5d-adbc-a401a261e172', '采蓮曲', '采蓮曲', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["玉漵花爭發，金塘水亂流。","相逢畏相失，並著采蓮舟。"]', '["玉漵花爭發，金塘水亂流。","相逢畏相失，並著采蓮舟。"]', '诗', 'shi', '', NULL, '采蓮曲 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8259dd89-196f-464b-8a94-1655dc7431a3', '子夜冬歌', '子夜冬歌', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["寂寥抱冬心，裁羅又褧褧。","夜久頻挑燈，霜寒剪刀冷。"]', '["寂寥抱冬心，裁羅又褧褧。","夜久頻挑灯，霜寒剪刀冷。"]', '诗', 'shi', '', NULL, '子夜冬歌 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c2c8e94-7297-462c-897a-b737ca886654', '麗人曲', '丽人曲', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["紅顏稱絕代，欲並真無侶。","獨有鏡中人，由來自相許。"]', '["紅顏稱絕代，欲並真無侶。","独有镜中人，由来自相許。"]', '诗', 'shi', '', NULL, '麗人曲 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('861898e7-b6b0-4805-9bc4-a6b6a1ca55a0', '小長干曲', '小长干曲', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["月暗送潮風，相尋路不通。","菱歌唱不徹，知在此塘中。"]', '["月暗送潮风，相尋路不通。","菱歌唱不徹，知在此塘中。"]', '诗', 'shi', '', NULL, '小長干曲 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bb965aa-61a7-47be-8dab-6e3874139c7f', '王昭君', '王昭君', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["漢使南還盡，胡中妾獨存。","紫臺綿望絕，秋草不堪論。"]', '["漢使南還尽，胡中妾独存。","紫台綿望絕，秋草不堪論。"]', '诗', 'shi', '', NULL, '王昭君 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e052475d-0dd9-44e6-b9a3-3ebe4a5fcc49', '秦女卷衣', '秦女卷衣', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["雖入秦帝宮，不上秦帝牀。","夜夜玉窗裏，與他卷衣裳。"]', '["雖入秦帝宮，不上秦帝牀。","夜夜玉窗裏，與他卷衣裳。"]', '诗', 'shi', '', NULL, '秦女卷衣 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8dded1a-e08b-46c9-a122-a2a44444a484', '今別離', '今別離', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["送別未能旋，相望連水口。","船行欲映洲，幾度急搖手。"]', '["送別未能旋，相望連水口。","船行欲映洲，幾度急搖手。"]', '诗', 'shi', '', NULL, '今別離 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71017886-3624-4798-8226-60ea3b816a52', '衞豔詞', '衞豔词', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["淇上桑葉青，青樓含白日。","比時遙望君，車馬城中出。"]', '["淇上桑葉青，青楼含白日。","比时遙望君，车马城中出。"]', '诗', 'shi', '', NULL, '衞豔詞 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75f247a1-875a-48dd-87c2-6e8cd5c13140', '渭水西別李崙', '渭水西別李崙', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["隴右長亭堠，山陰古塞秋。","不知嗚咽水，何事向西流。"]', '["隴右长亭堠，山陰古塞秋。","不知嗚咽水，何事向西流。"]', '诗', 'shi', '', NULL, '渭水西別李崙 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1628d48-46e3-4330-a5fd-7e81bc261629', '古意', '古意', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["淨掃黃金階，飛霜皎如雪。","下簾彈箜篌，不忍見秋月。"]', '["淨掃黄金階，飞霜皎如雪。","下簾彈箜篌，不忍见秋月。"]', '诗', 'shi', '', NULL, '古意 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c034f0a0-07a1-4254-a4ae-b7411adad5a8', '送韓十四被魯王推遞往濟南府', '送韓十四被魯王推遞往濟南府', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["西候情何極，南冠怨有餘。","梁王雖好事，不察獄中書。"]', '["西候情何極，南冠怨有餘。","梁王雖好事，不察獄中书。"]', '诗', 'shi', '', NULL, '送韓十四被魯王推遞往濟南府 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78a84f2a-d55a-4449-8d62-65f0affd23ec', '白紵辭二首 一', '白紵辞二首 一', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["洛陽梨花落如霰，河陽桃葉生復齊。","坐惜玉樓春欲盡，紅綿粉絮裛妝啼。"]', '["洛陽梨花落如霰，河陽桃葉生复齊。","坐惜玉楼春欲尽，紅綿粉絮裛妝啼。"]', '诗', 'shi', '', NULL, '白紵辭二首 一 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('324495ad-2db6-4a39-a9c0-e208bd91d828', '白紵辭二首 二', '白紵辞二首 二', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["董賢女弟在椒風，窈窕繁華貴後宮。","璧帶金釭皆翡翠，一朝零落變成空。"]', '["董賢女弟在椒风，窈窕繁华貴後宮。","璧带金釭皆翡翠，一朝零落变成空。"]', '诗', 'shi', '', NULL, '白紵辭二首 二 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c05b9b5e-b07f-4fad-a6c1-26bb8d32fd12', '九日', '九日', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["江邊楓落菊花黃，少長登高一望鄉。","九日陶家雖載酒，三年楚客已霑裳。"]', '["江邊楓落菊花黄，少长登高一望乡。","九日陶家雖載酒，三年楚客已霑裳。"]', '诗', 'shi', '', NULL, '九日 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('576f5b8e-d99e-43ed-b238-3890abc782c6', '王昭君', '王昭君', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["一回望月一回悲，望月月移人不移。","何時得見漢朝使，爲妾傳書斬畫師。"]', '["一回望月一回悲，望月月移人不移。","何时得见漢朝使，爲妾傳书斬畫師。"]', '诗', 'shi', '', NULL, '王昭君 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfc7ba4a-f19d-48d3-8a9b-5b4f47a0b880', '孤寢怨', '孤寢怨', '76eff425-47dc-436b-8ca5-ad7937d19a58', '唐', '["征戍動經年，含情拂玳筵。","花飛織錦處，月落擣衣邊。","燈暗愁孤坐，牀空怨獨眠。","自君遼海去，玉匣閉春弦。"]', '["征戍动經年，含情拂玳筵。","花飞织錦处，月落擣衣邊。","灯暗愁孤坐，牀空怨独眠。","自君遼海去，玉匣閉春弦。"]', '诗', 'shi', '', NULL, '孤寢怨 崔珪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e51f8be-4533-4312-b0c0-919d4fff2f1c', '題武陵草堂', '題武陵草堂', '3d570f55-5344-4110-9a14-353262ce5ebc', '唐', '["草堂列仙樓，上在青山頂。","戶外窺數峯，階前對雙井。","雨來花盡濕，風度松初冷。","登棧行不疲，入谿語彌靜。","云能去塵服，兼欲事金鼎。","正直心所存，諂諛長自省。","適知幽遁趣，已覺煩慮屏。","更愛雲林間，吾將臥南潁。"]', '["草堂列仙楼，上在青山頂。","戶外窺數峯，階前对雙井。","雨来花尽濕，风度松初冷。","登棧行不疲，入谿語彌静。","云能去塵服，兼欲事金鼎。","正直心所存，諂諛长自省。","適知幽遁趣，已覺煩慮屏。","更愛云林间，吾將臥南潁。"]', '诗', 'shi', '', NULL, '題武陵草堂 楊浚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b37b851-52a1-475a-bed6-7a83fc044ad6', '廣武懷古', '廣武懷古', '3d570f55-5344-4110-9a14-353262ce5ebc', '唐', '["河水城下流，登城望彌愜。","海雲飛不斷，岸草綠相接。","龍門無舊塲，武牢有遺堞。","扼喉兵易守，捫指計何捷。","天奪項氏謀，卒成漢家業。","鄉山遙可見，西顧淚盈睫。"]', '["河水城下流，登城望彌愜。","海云飞不斷，岸草綠相接。","龙门無旧塲，武牢有遺堞。","扼喉兵易守，捫指計何捷。","天奪項氏謀，卒成漢家業。","乡山遙可见，西顧泪盈睫。"]', '诗', 'shi', '', NULL, '廣武懷古 楊浚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('995c93fb-a158-4af9-95f4-7005caf418e3', '贈李郎中', '贈李郎中', '3d570f55-5344-4110-9a14-353262ce5ebc', '唐', '["仙郎早朝退，直省臥南軒。","院竹自成賞，階庭寂不喧。","焚香開後閣，起草閉前門。","禮樂風流美，光華星位尊。","榮兼朱紱貴，交乃布衣存。","是日登龍客，無忘君子恩。"]', '["仙郎早朝退，直省臥南軒。","院竹自成賞，階庭寂不喧。","焚香开後閣，起草閉前门。","禮乐风流美，光华星位尊。","榮兼朱紱貴，交乃布衣存。","是日登龙客，無忘君子恩。"]', '诗', 'shi', '', NULL, '贈李郎中 楊浚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4c038d9-521f-4d90-8e61-d90cf5ae0174', '詠王大娘戴卒', '詠王大娘戴卒', 'd84ded69-f9df-4301-a4e4-a8716f42626f', '唐', '["樓前百戲競爭新，唯有長竿妙入神。","誰謂綺羅[翻]有力，猶自嫌輕更著人。"]', '["楼前百戲競爭新，唯有长竿妙入神。","誰謂綺羅[翻]有力，猶自嫌轻更著人。"]', '诗', 'shi', '', NULL, '詠王大娘戴卒 劉晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('102198f6-fc4f-4183-8e98-85df362362bb', '享太廟樂章', '享太廟乐章', 'd84ded69-f9df-4301-a4e4-a8716f42626f', '唐', '["漢祚惟永，神功中興。","夙驅氛祲，天覆黎蒸。","三光再朗，庶績其凝。","重熙累葉，景命是膺。"]', '["漢祚惟永，神功中兴。","夙驱氛祲，天覆黎蒸。","三光再朗，庶績其凝。","重熙累葉，景命是膺。"]', '诗', 'shi', '', NULL, '享太廟樂章 劉晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b613132b-0a83-44e3-84c0-083d6f47ae96', '鴻門行', '鴻门行', '3271dbbf-23bd-41b6-805c-6739c403ad66', '唐', '["少年買意氣，百金不辭費。","學劒西入秦，結交北遊魏。","秦魏多豪人，與代亦殊倫。","由來不相識，皆是暗相親。","寶馬青絲轡，狐裘貂鼠服。","晨過劇孟游，暮投咸陽宿。","然諾本云云，諸侯莫不聞。","猶思百戰術，更逐李將軍。","始從灞陵下，遙遙度朔野。","北風聞楚歌，南庭見胡馬。","胡馬秋正肥，相邀夜合圍。","戰酣烽火滅，路斷救兵稀。","白刃縱橫逼，黃塵飛不息。","虜騎血灑衣，單于淚沾臆。","獻凱雲臺中，自言塞上雄。","將軍行失勢，部曲遂無功。","新人不如舊，舊人不相救。","萬里長飄颻，十年計不就。","棄置難重論，驅馬度鴻門。","行看楚漢事，不覺風塵昏。","寶劒中夜撫，悲歌聊自舞。","此曲不可終，曲終淚如雨。"]', '["少年買意氣，百金不辞費。","学劒西入秦，結交北游魏。","秦魏多豪人，與代亦殊倫。","由来不相識，皆是暗相親。","寶马青絲轡，狐裘貂鼠服。","晨過劇孟游，暮投咸陽宿。","然諾本云云，諸侯莫不闻。","猶思百戰術，更逐李將軍。","始從灞陵下，遙遙度朔野。","北风闻楚歌，南庭见胡马。","胡马秋正肥，相邀夜合圍。","戰酣烽火滅，路斷救兵稀。","白刃縱橫逼，黄塵飞不息。","虜騎血灑衣，單于泪沾臆。","獻凱云台中，自言塞上雄。","將軍行失勢，部曲遂無功。","新人不如旧，旧人不相救。","万里长飄颻，十年計不就。","棄置难重論，驱马度鴻门。","行看楚漢事，不覺风塵昏。","寶劒中夜撫，悲歌聊自舞。","此曲不可終，曲終泪如雨。"]', '诗', 'shi', '', NULL, '鴻門行 袁瓘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dc587aa-2bc9-4f31-aa81-9165ed6e39c4', '惠文太子挽歌', '惠文太子挽歌', '3271dbbf-23bd-41b6-805c-6739c403ad66', '唐', '["寒仗丹旄引，陰堂白日違。","暗燈明象物，畫水濕靈衣。","羽化淮王去，仙迎太子歸。","空餘燕銜土，朝夕向陵飛。"]', '["寒仗丹旄引，陰堂白日違。","暗灯明象物，畫水濕靈衣。","羽化淮王去，仙迎太子归。","空餘燕銜土，朝夕向陵飞。"]', '诗', 'shi', '', NULL, '惠文太子挽歌 袁瓘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('793e5224-1879-4e24-b316-e772c935a6a4', '從軍行', '從軍行', '4835e3a8-cb3e-406b-bd92-c7fe981bca5b', '唐', '["漢家未得燕支山，征戍年年沙朔間。","塞下長驅汗血馬，雲中恆閉玉門關。","陰山翰海千萬里，此日桑河凍流水。","稽洛川邊胡騎來，漁陽戍裏烽煙起。","長途羽檄何相望，天子按劒思北方。","羽林練士拭金甲，將軍校戰出玉堂。","幽陵異域風煙改，亭障連連古今在。","夜聞鴻雁南渡河，曉望旌旗北臨海。","塞沙飛淅瀝，遙裔連窮磧。","玄漠雲平初合陣，西山月出聞鳴鏑。","城南百戰多苦辛，路傍死臥黃沙人。","戎衣不脫隨霜雪，汗馬䟃𧽼長被鐵。","楊葉樓中不寄書，蓮花劒上空流血。","匈奴未滅不言家，驅逐行行邊徼賒。","歸心海外見明月，別思天邊夢落花。","天邊迴望何悠悠，芳樹無人渡隴頭。","春雲不變陽關雪，桑葉先知胡地秋。","田疇不賣盧龍策，竇憲思勒燕然石。","麾兵靜北垂，此日交河湄。","欲令塞上無干戚，會待單于繫頸時。"]', '["漢家未得燕支山，征戍年年沙朔间。","塞下长驱汗血马，云中恆閉玉门关。","陰山翰海千万里，此日桑河凍流水。","稽洛川邊胡騎来，漁陽戍裏烽煙起。","长途羽檄何相望，天子按劒思北方。","羽林練士拭金甲，將軍校戰出玉堂。","幽陵異域风煙改，亭障連連古今在。","夜闻鴻雁南渡河，晓望旌旗北臨海。","塞沙飞淅瀝，遙裔連窮磧。","玄漠云平初合陣，西山月出闻鳴鏑。","城南百戰多苦辛，路傍死臥黄沙人。","戎衣不脫隨霜雪，汗马䟃𧽼长被鐵。","楊葉楼中不寄书，蓮花劒上空流血。","匈奴未滅不言家，驱逐行行邊徼賒。","归心海外见明月，別思天邊梦落花。","天邊迴望何悠悠，芳樹無人渡隴头。","春云不变陽关雪，桑葉先知胡地秋。","田疇不賣盧龙策，竇憲思勒燕然石。","麾兵静北垂，此日交河湄。","欲令塞上無干戚，會待單于繫頸时。"]', '诗', 'shi', '', NULL, '從軍行 李昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4813666e-41fc-406f-9d4d-8029b21b0543', '賦戚夫人楚舞歌', '賦戚夫人楚舞歌', '4835e3a8-cb3e-406b-bd92-c7fe981bca5b', '唐', '["定陶城中是妾家，妾年二八顏如花。","閨中歌舞未終曲，天下死人如亂麻。","漢王此地因征戰，未出簾櫳人已薦。","風花菡萏落轅門，雲雨裴回入行殿。","日夕悠悠非舊鄉，飄飄處處逐君王。","閨門向裏通歸夢，銀燭迎來在戰場。","相從顧恩不顧己，何異浮萍寄深水。","逐戰曾迷隻輪下，隨君幾陷重圍裏。","此時平楚復平齊，咸陽宮闕到關西。","珠簾夕殿聞鐘磬，白日秋天憶鼓鼙。","君王縱恣翻成誤，呂后由來有深妬。","不奈君王容鬢衰，相存相顧能幾時。","黃泉白骨不可報，雀釵翠羽從此辭。","君楚歌兮妾楚舞，脉脉相看兩心苦。","曲未終兮袂更揚，君流涕兮妾斷腸。","已見儲君歸惠帝，徒留愛子付周昌。"]', '["定陶城中是妾家，妾年二八顏如花。","閨中歌舞未終曲，天下死人如亂麻。","漢王此地因征戰，未出簾櫳人已薦。","风花菡萏落轅门，云雨裴回入行殿。","日夕悠悠非旧乡，飄飄处处逐君王。","閨门向裏通归梦，銀燭迎来在戰場。","相從顧恩不顧己，何異浮萍寄深水。","逐戰曾迷隻輪下，隨君幾陷重圍裏。","此时平楚复平齊，咸陽宮闕到关西。","珠簾夕殿闻鐘磬，白日秋天憶鼓鼙。","君王縱恣翻成誤，呂后由来有深妬。","不奈君王容鬢衰，相存相顧能幾时。","黄泉白骨不可報，雀釵翠羽從此辞。","君楚歌兮妾楚舞，脉脉相看兩心苦。","曲未終兮袂更揚，君流涕兮妾斷腸。","已见儲君归惠帝，徒留愛子付周昌。"]', '诗', 'shi', '', NULL, '賦戚夫人楚舞歌 李昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4411499-60dd-459f-9247-ed4606232249', '句', '句', '4835e3a8-cb3e-406b-bd92-c7fe981bca5b', '唐', '["耳臨清渭洗，心向白雲閑。"]', '["耳臨清渭洗，心向白云闲。"]', '诗', 'shi', '', NULL, '句 李昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78ca6b46-189b-425f-968e-e920be6ec2cb', '夏晚初霽南省寓直用餘字', '夏晚初霽南省寓直用餘字', 'e4c10dc1-99a3-4872-b076-9d46a4715b4e', '唐', '["薄宦因時泰，涼宵寓直初。","沈沈仙閣閉，的的暗更徐。","霽色連空上，炎氛入夜除。","星迴南斗落，月度北窗虛。","待漏殘燈照，含芳襲氣餘。","寐來冠不解，奏罷草仍書。","幕府慙良策，明曹媿散樗。","命輕徒有報，義重更難疎。","燕廈欣成託，鵷行濫所如。","晨趨當及早，復此戒朝車。"]', '["薄宦因时泰，涼宵寓直初。","沈沈仙閣閉，的的暗更徐。","霽色連空上，炎氛入夜除。","星迴南斗落，月度北窗虛。","待漏殘灯照，含芳襲氣餘。","寐来冠不解，奏罷草仍书。","幕府慙良策，明曹媿散樗。","命轻徒有報，義重更难疎。","燕廈欣成託，鵷行濫所如。","晨趨當及早，复此戒朝车。"]', '诗', 'shi', '', NULL, '夏晚初霽南省寓直用餘字 厙狄履溫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79835934-e491-4207-9b1f-e2ca84d2583b', '同皇甫兵曹天官寺浴室新成招友人賞會', '同皇甫兵曹天官寺浴室新成招友人賞會', 'ad482cea-759c-4b6f-bd0f-997c45d67301', '唐', '["溫室歡初就，蘭交托勝因。","共聽無漏法，兼濯有爲塵。","水潔三空性，香沾四大身。","清心多善友，頌德慰同人。"]', '["溫室歡初就，蘭交托勝因。","共听無漏法，兼濯有爲塵。","水潔三空性，香沾四大身。","清心多善友，頌德慰同人。"]', '诗', 'shi', '', NULL, '同皇甫兵曹天官寺浴室新成招友人賞會 寇坦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82ee3cd4-d4dd-4d26-96d8-c9bfcec45aa2', '同張少府和厙狄員外夏晚初霽南省寓直時兼充節度判官之作', '同張少府和厙狄員外夏晚初霽南省寓直时兼充節度判官之作', 'ad482cea-759c-4b6f-bd0f-997c45d67301', '唐', '["黃綬歸休日，仙郎復奏餘。","晏居當夏晚，寓直會晴初。","露散星文發，雲披水鏡虛。","高才推獨唱，嘉會喜連茹。","月色搖春闥，香煙靄暝廬。","千門傳夜警，萬象照階除。","少孺嘉能賦，文強閱賜書。","兼曹謀未展，入幕志方攄。","爲奉靈臺帛，恭先待漏車。","貞標不可仰，空此樂樵漁。"]', '["黄綬归休日，仙郎复奏餘。","晏居當夏晚，寓直會晴初。","露散星文發，云披水镜虛。","高才推独唱，嘉會喜連茹。","月色搖春闥，香煙靄暝廬。","千门傳夜警，万象照階除。","少孺嘉能賦，文強閱賜书。","兼曹謀未展，入幕志方攄。","爲奉靈台帛，恭先待漏车。","貞標不可仰，空此乐樵漁。"]', '诗', 'shi', '', NULL, '同張少府和厙狄員外夏晚初霽南省寓直時兼充節度判官之作 寇坦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aaabec5-7f97-4d5e-9a0c-b418cfbc7eee', '詠銅柱', '詠銅柱', '877ec342-2b6b-4ca3-bd69-5ee7e408c179', '唐', '["天門街裏倒天樞，火急先須卸火珠。","計合一條絲線挽，何勞兩縣索人夫。"]', '["天门街裏倒天樞，火急先須卸火珠。","計合一條絲線挽，何勞兩縣索人夫。"]', '诗', 'shi', '', NULL, '詠銅柱 李休烈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b18b761-a4fe-4ccb-b1e2-978566267463', '送賀監歸四明應制', '送賀監归四明應制', 'd2e5befd-2ea1-44f9-a9b1-2953a4503f5e', '唐', '["挂冠知止足，豈獨漢疏賢。","入道求真侶，辭恩訪列仙。","睿文含日月，宸翰動雲煙。","鶴駕吳鄉遠，遙遙南斗邊。"]', '["挂冠知止足，豈独漢疏賢。","入道求真侶，辞恩訪列仙。","睿文含日月，宸翰动云煙。","鹤駕吳乡远，遙遙南斗邊。"]', '诗', 'shi', '', NULL, '送賀監歸四明應制 李林甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de563514-6444-4aa3-b6e2-917abb4e062c', '奉和聖製次瓊岳應制', '奉和聖製次瓊岳應制', 'd2e5befd-2ea1-44f9-a9b1-2953a4503f5e', '唐', '["東幸從人望，西巡順物回。","雲收二華出，天轉五星來。","十月農初罷，三驅禮復開。","更看瓊岳上，佳氣接神臺。"]', '["东幸從人望，西巡順物回。","云收二华出，天轉五星来。","十月農初罷，三驱禮复开。","更看瓊岳上，佳氣接神台。"]', '诗', 'shi', '', NULL, '奉和聖製次瓊岳應制 李林甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62840254-fc80-4bdc-95dc-b88f0807dcc7', '秋夜望月憶韓席等諸侍郎因以投贈', '秋夜望月憶韓席等諸侍郎因以投贈', 'd2e5befd-2ea1-44f9-a9b1-2953a4503f5e', '唐', '["秋天碧雲夜，明月懸東方。","皓皓庭際色，稍稍林下光。","桂華澄遠近，璧彩散池塘。","鴻雁飛難度，關山曲易長。","揆予秉孤直，虛薄忝文昌。","握鏡慚先照，持衡媿後行。","多才衆君子，載筆久詞場。","作賦推潘岳，題詩許謝康。","當時陪宴語，今夕恨相望。","願欲接高論，清晨朝建章。"]', '["秋天碧云夜，明月懸东方。","皓皓庭際色，稍稍林下光。","桂华澄远近，璧彩散池塘。","鴻雁飞难度，关山曲易长。","揆予秉孤直，虛薄忝文昌。","握镜慚先照，持衡媿後行。","多才衆君子，載笔久词場。","作賦推潘岳，題诗許謝康。","當时陪宴語，今夕恨相望。","願欲接高論，清晨朝建章。"]', '诗', 'shi', '', NULL, '秋夜望月憶韓席等諸侍郎因以投贈 李林甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4066262-a7bc-4f6a-8bb5-46a56d2ffaff', '流崖州至鬼門關作', '流崖州至鬼门关作', '7decedfa-43d3-4356-a96f-75f65ac6109c', '唐', '["一去一萬里，千知千不還。","崖州何處在？生度鬼門關。"]', '["一去一万里，千知千不還。","崖州何处在？生度鬼门关。"]', '诗', 'shi', '', NULL, '流崖州至鬼門關作 楊炎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a7ef146-2953-45fd-94da-ef92db24648f', '贈元載歌妓', '贈元載歌妓', '7decedfa-43d3-4356-a96f-75f65ac6109c', '唐', '["雪面淡眉天上女，鳳簫鸞翅欲飛去。","玉山翹翠步無塵，楚腰如柳不勝春。"]', '["雪面淡眉天上女，鳳簫鸾翅欲飞去。","玉山翹翠步無塵，楚腰如柳不勝春。"]', '诗', 'shi', '', NULL, '贈元載歌妓 楊炎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62d3110d-6e4e-40f8-96b6-4b97fe6dfa41', '別妻王韞秀', '別妻王韞秀', 'bf3d5fe7-81ee-4ae6-9526-510d92c66d99', '唐', '["年來誰不厭龍鍾，雖在侯門似不容。","看取海山寒翠樹，苦遭霜霰到秦封。"]', '["年来誰不厭龙鍾，雖在侯门似不容。","看取海山寒翠樹，苦遭霜霰到秦封。"]', '诗', 'shi', '', NULL, '別妻王韞秀 元載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a09a52a-54da-4cd6-9111-dcb20b85da56', '賦得雲生棟梁間', '賦得云生棟梁间', '0d0f3ea8-9d2e-43d9-8087-28baeee58d9b', '唐', '["一片蒼梧意，氤氳生棟梁。","下簾山足暗，開戶日添光。","偏使衣裘潤，能令枕簟涼。","無心伴行雨，何必夢荆王。"]', '["一片蒼梧意，氤氳生棟梁。","下簾山足暗，开戶日添光。","偏使衣裘潤，能令枕簟涼。","無心伴行雨，何必梦荆王。"]', '诗', 'shi', '', NULL, '賦得雲生棟梁間 陳希烈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('109698aa-a812-4258-aa7f-43a8708c63f9', '奉和聖製三月三日', '奉和聖製三月三日', '0d0f3ea8-9d2e-43d9-8087-28baeee58d9b', '唐', '["上巳迂龍駕，中流泛羽觴。","酒因朝太子，詩爲樂賢王。","錦纜方舟渡，瓊筵大樂張。","風搖垂柳色，花發異林香。","野老歌無事，朝臣飲歲芳。","皇情被羣物，中外洽恩光。"]', '["上巳迂龙駕，中流泛羽觴。","酒因朝太子，诗爲乐賢王。","錦纜方舟渡，瓊筵大乐張。","风搖垂柳色，花發異林香。","野老歌無事，朝臣饮歲芳。","皇情被羣物，中外洽恩光。"]', '诗', 'shi', '', NULL, '奉和聖製三月三日 陳希烈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('291e1334-8c23-495d-b9fc-3b90cd89d2d1', '省試白雲起封中', '省試白云起封中', '0d0f3ea8-9d2e-43d9-8087-28baeee58d9b', '唐', '["千年泰山頂，雲起漢王封。","不作奇峰狀，寧分觸石容。","爲霖雖易得，表聖自難逢。","冉冉排空上，依依疊影重。","素光非曳練，靈貺是從龍。","豈學無心出，東西任所從。"]', '["千年泰山頂，云起漢王封。","不作奇峰狀，寧分觸石容。","爲霖雖易得，表聖自难逢。","冉冉排空上，依依叠影重。","素光非曳練，靈貺是從龙。","豈学無心出，东西任所從。"]', '诗', 'shi', '', NULL, '省試白雲起封中 陳希烈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2840b0a9-5b1c-462e-8069-c5b5d5a96dbf', '朗月行', '朗月行', '2a4ab14b-a5b2-412d-b828-2716a73685a7', '唐', '["朗月照簾幌，清夜有餘姿。","洞房怨孤枕，挾琴愛前墀。","萱草已數葉，梨花復徧枝。","去歲草始榮，與君新相知。","今年花未落，誰分生別離。","代情難重論，人事好乖移。","合比月華滿，分同月易虧。","虧月當再圓，人別星隕天。","吾欲竟此曲，意深不可傳。","歎息孤鸞鳥，傷心明鏡前。"]', '["朗月照簾幌，清夜有餘姿。","洞房怨孤枕，挾琴愛前墀。","萱草已數葉，梨花复徧枝。","去歲草始榮，與君新相知。","今年花未落，誰分生別離。","代情难重論，人事好乖移。","合比月华满，分同月易虧。","虧月當再圓，人別星隕天。","吾欲竟此曲，意深不可傳。","歎息孤鸾鸟，傷心明镜前。"]', '诗', 'shi', '', NULL, '朗月行 張漸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('038a1005-ef07-47c0-b438-0dc4667d709c', '曉次荆江', '晓次荆江', '81551c00-3f01-4f9a-9e06-288be0705146', '唐', '["孤舟大江水，水涉無昏曙。","雨暗迷津時，雲生望鄉處。","漁翁閑自樂，樵客紛多慮。","秋色湖上山，歸心日邊樹。","徒稱竹箭美，未得楓林趣。","向夕垂釣還，吾從落潮去。"]', '["孤舟大江水，水涉無昏曙。","雨暗迷津时，云生望乡处。","漁翁闲自乐，樵客紛多慮。","秋色湖上山，归心日邊樹。","徒稱竹箭美，未得楓林趣。","向夕垂釣還，吾從落潮去。"]', '诗', 'shi', '', NULL, '曉次荆江 宋昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('700474d8-74f7-49ba-934c-bf5e02d2c469', '題石窟寺', '題石窟寺', '81551c00-3f01-4f9a-9e06-288be0705146', '唐', '["梵宇開金地，香龕鑿鐵圍。","影中羣象動，空裏衆靈飛。","簷牖籠朱旭，房廊挹翠微。","瑞蓮生佛步，瑤樹挂天衣。","邀福功雖在，興王代久非。","誰知雲朔外，更覩化胡歸。"]', '["梵宇开金地，香龕鑿鐵圍。","影中羣象动，空裏衆靈飞。","簷牖籠朱旭，房廊挹翠微。","瑞蓮生佛步，瑤樹挂天衣。","邀福功雖在，兴王代久非。","誰知云朔外，更覩化胡归。"]', '诗', 'shi', '', NULL, '題石窟寺 宋昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bba2337f-5b4d-4097-ab92-f1f326570a15', '樟亭觀濤', '樟亭观濤', '81551c00-3f01-4f9a-9e06-288be0705146', '唐', '["濤來勢轉雄，獵獵駕長風。","雷震雲霓裏，山飛霜雪中。","激流起平地，吹澇上侵空。","翕闢乾坤異，盈虛日月同。","艅艎從陸起，洲浦隔阡通。","跳沫噴巖翠，翻波帶景紅。","怒湍初抵北，却浪復歸東。","寂聽堪增勇，晴看自發蒙。","伍生傳或謬，枚叟說難窮。","來信應無已，申威亦匪躬。","衝騰如決勝，迴合似相攻。","委質任平視，誰能涯始終。"]', '["濤来勢轉雄，獵獵駕长风。","雷震云霓裏，山飞霜雪中。","激流起平地，吹澇上侵空。","翕闢乾坤異，盈虛日月同。","艅艎從陸起，洲浦隔阡通。","跳沫噴巖翠，翻波带景紅。","怒湍初抵北，却浪复归东。","寂听堪增勇，晴看自發蒙。","伍生傳或謬，枚叟说难窮。","来信應無已，申威亦匪躬。","衝腾如決勝，迴合似相攻。","委質任平視，誰能涯始終。"]', '诗', 'shi', '', NULL, '樟亭觀濤 宋昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aadd6d4-f0b6-4719-9be5-fd6c9548276e', '贈程秘書', '贈程秘书', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["客自岐陽來，吐音若鳴鳳。","孤飛畏不偶，獨立誰見用。","忽從被褐中，召入承明宮。","聖人借顏色，言事無不通。","殷勤拯黎庶，感激論諸公。","將相猜賈誼，圖書歸馬融。","顧余久寂寞，一歲麒麟閣。","且共歌太平，勿嗟名宦薄。"]', '["客自岐陽来，吐音若鳴鳳。","孤飞畏不偶，独立誰见用。","忽從被褐中，召入承明宮。","聖人借顏色，言事無不通。","殷勤拯黎庶，感激論諸公。","將相猜賈誼，圖书归马融。","顧余久寂寞，一歲麒麟閣。","且共歌太平，勿嗟名宦薄。"]', '诗', 'shi', '', NULL, '贈程秘書 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44dcaf68-5d78-471d-86a7-daaef4152648', '家叔徵君東溪草堂二首 一', '家叔徵君东溪草堂二首 一', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["開山十餘里，青壁森相倚。","欲識堯時天，東溪白雲是。","雷聲轉幽壑，雲氣杳流水。","澗影生龍蛇，巖端翳檉梓。","大道終不易，君恩曷能已。","鶴羨無老時，龜言攝生理。","浮年笑六甲，元化潛一指。","未暇掃雲梯，空慙阮氏子。"]', '["开山十餘里，青壁森相倚。","欲識堯时天，东溪白云是。","雷声轉幽壑，云氣杳流水。","澗影生龙蛇，巖端翳檉梓。","大道終不易，君恩曷能已。","鹤羨無老时，龟言攝生理。","浮年笑六甲，元化潛一指。","未暇掃云梯，空慙阮氏子。"]', '诗', 'shi', '', NULL, '家叔徵君東溪草堂二首 一 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bdfb409-2374-4a99-8afa-65d6dcef8311', '家叔徵君東溪草堂二首 二', '家叔徵君东溪草堂二首 二', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["今朝共遊者，得性閑未歸。","已到仙人家，莫驚鷗鳥飛。","水深嚴子釣，松挂巢父衣。","雲氣轉幽寂，溪流無是非。","名理未足羨，腥臊詎所希。","自惟負貞意，何歲當食薇。"]', '["今朝共游者，得性闲未归。","已到仙人家，莫驚鷗鸟飞。","水深嚴子釣，松挂巢父衣。","云氣轉幽寂，溪流無是非。","名理未足羨，腥臊詎所希。","自惟負貞意，何歲當食薇。"]', '诗', 'shi', '', NULL, '家叔徵君東溪草堂二首 二 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88a1c3c5-57ec-4b3b-8dac-f697baa68182', '鄉試後自鞏還田家因謝鄰友見過之作', '乡試後自鞏還田家因謝鄰友见過之作', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["雞鳴出東邑，馬倦登南巒。","落日見桑柘，翳然丘中寒。","鄰家多舊識，投暝來相看。","且問春稅苦，兼陳行路難。","園場近陰壑，草木易凋殘。","峰晴雪猶積，澗深冰已團。","浮名知何用，歲晏不成歡。","置酒共君飲，當歌聊自寬。"]', '["雞鳴出东邑，马倦登南巒。","落日见桑柘，翳然丘中寒。","鄰家多旧識，投暝来相看。","且问春稅苦，兼陳行路难。","园場近陰壑，草木易凋殘。","峰晴雪猶積，澗深冰已團。","浮名知何用，歲晏不成歡。","置酒共君饮，當歌聊自寬。"]', '诗', 'shi', '', NULL, '鄉試後自鞏還田家因謝鄰友見過之作 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8c3e791-7f9d-4a6e-baf7-664109545d72', '青雀歌', '青雀歌', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["啾啾青雀兒，飛來飛去仰天池。","逍遙飲啄安涯分，何假扶搖九萬爲。"]', '["啾啾青雀兒，飞来飞去仰天池。","逍遙饮啄安涯分，何假扶搖九万爲。"]', '诗', 'shi', '', NULL, '青雀歌 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5be96530-0656-42e0-bf69-a0c7a9c73a58', '雜詩二首 一', '杂诗二首 一', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["家居五原上，征戰是平生。","獨負山西勇，誰當塞下名。","死生遼海戰，雨雪薊門行。","諸將封侯盡，論功獨不成。"]', '["家居五原上，征戰是平生。","独負山西勇，誰當塞下名。","死生遼海戰，雨雪薊门行。","諸將封侯尽，論功独不成。"]', '诗', 'shi', '', NULL, '雜詩二首 一 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efaef8c1-a7b0-424d-87bd-44283b6c4fb8', '雜詩二首 二', '杂诗二首 二', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["君家御溝上，垂柳夾朱門。","列鼎會中貴，鳴珂朝至尊。","死生在片議，窮達由一言。","須識苦寒士，莫矜狐白溫。"]', '["君家御溝上，垂柳夾朱门。","列鼎會中貴，鳴珂朝至尊。","死生在片議，窮達由一言。","須識苦寒士，莫矜狐白溫。"]', '诗', 'shi', '', NULL, '雜詩二首 二 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78da6a5c-2ed0-4db7-bece-86a9486aa6ac', '贈廣川馬先生', '贈廣川马先生', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["經書滿腹中，吾識廣川翁。","年老甘無位，家貧懶發蒙。","人歸洙泗學，歌盛舞雩風。","願接諸生禮，三年事馬融。"]', '["經书满腹中，吾識廣川翁。","年老甘無位，家貧懶發蒙。","人归洙泗学，歌盛舞雩风。","願接諸生禮，三年事马融。"]', '诗', 'shi', '', NULL, '贈廣川馬先生 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd6d6203-ced1-4e25-9d43-7e45918f476c', '峽中作', '峽中作', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["高唐幾百里，樹色接陽臺。","晚見江山霽，宵聞風雨來。","雲從三峽起，天向數峰開。","靈境信難見，輕舟那可回。"]', '["高唐幾百里，樹色接陽台。","晚见江山霽，宵闻风雨来。","云從三峽起，天向數峰开。","靈境信难见，轻舟那可回。"]', '诗', 'shi', '', NULL, '峽中作 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d82c039-389b-4cc3-8253-3c305c66fb44', '竹里館', '竹里館', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["江南冰不閉，山澤氣潛通。","臘月聞山鳥，寒崖見蟄熊。","柳林春半合，荻笋亂無叢。","回首金陵岸，依依向北風。"]', '["江南冰不閉，山澤氣潛通。","臘月闻山鸟，寒崖见蟄熊。","柳林春半合，荻笋亂無叢。","回首金陵岸，依依向北风。"]', '诗', 'shi', '', NULL, '竹里館 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7747363c-1d8d-4f81-9c07-575b27800460', '永城使風', '永城使风', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["長風起秋色，細雨含落暉。","夕鳥向林去，晚帆相逐飛。","蟲聲出亂草，水氣薄行衣。","一別故鄉道，悠悠今始歸。"]', '["长风起秋色，細雨含落暉。","夕鸟向林去，晚帆相逐飞。","蟲声出亂草，水氣薄行衣。","一別故乡道，悠悠今始归。"]', '诗', 'shi', '', NULL, '永城使風 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7b7da24-eab2-4d9f-9fed-bf10c751c1ed', '和徐侍郎叢篠詠', '和徐侍郎叢篠詠', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["中禁夕沈沈，幽篁別作林。","色連雞樹近，影落鳳池深。","爲重凌霜節，能虛應物心。","年年承雨露，長對紫庭陰。"]', '["中禁夕沈沈，幽篁別作林。","色連雞樹近，影落鳳池深。","爲重凌霜節，能虛應物心。","年年承雨露，长对紫庭陰。"]', '诗', 'shi', '', NULL, '和徐侍郎叢篠詠 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f13c70c7-8ae8-48dd-b105-f17276e3bfe3', '駕幸溫泉', '駕幸溫泉', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["傳聞聖主幸新豐，清蹕鳴鑾出禁中。","細草終朝隨步輦，垂楊幾處繞行宮。","千官扈從驪山北，萬國來朝渭水東。","此日小臣徒獻賦，漢家誰復重[揚]雄。"]', '["傳闻聖主幸新豐，清蹕鳴鑾出禁中。","細草終朝隨步輦，垂楊幾处繞行宮。","千官扈從驪山北，万国来朝渭水东。","此日小臣徒獻賦，漢家誰复重[揚]雄。"]', '诗', 'shi', '', NULL, '駕幸溫泉 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea9b31db-da7c-47aa-9717-71ba2ebfe377', '奉和張使君宴加朝散', '奉和張使君宴加朝散', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["佐理星辰貴，分榮渙汗深。","言從大夫後，用荅聖人心。","騎擁軒裳客，鸞驚翰墨林。","停杯歌麥秀，秉燭醉棠陰。","爽氣凌秋笛，輕寒散暝砧。","秪應將四子，講德謝知音。"]', '["佐理星辰貴，分榮渙汗深。","言從大夫後，用荅聖人心。","騎擁軒裳客，鸾驚翰墨林。","停杯歌麦秀，秉燭醉棠陰。","爽氣凌秋笛，轻寒散暝砧。","秪應將四子，講德謝知音。"]', '诗', 'shi', '', NULL, '奉和張使君宴加朝散 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67d60c2f-ad7a-4101-a782-7e9cb01e570e', '贈張均員外', '贈張均員外', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["公門世緒昌，才子冠裴王。","出自平津邸，還爲吏部郎。","神仙餘氣色，列宿動輝光。","夜直南宮靜，朝趨北禁長。","時人歸水鏡，明主賜衣裳。","翰苑飛鸚鵡，天池待鳳凰。","承歡疇日顧，未紀後時傷。","去去圖南遠，微才幸不忘。"]', '["公门世緒昌，才子冠裴王。","出自平津邸，還爲吏部郎。","神仙餘氣色，列宿动輝光。","夜直南宮静，朝趨北禁长。","时人归水镜，明主賜衣裳。","翰苑飞鸚鵡，天池待鳳凰。","承歡疇日顧，未紀後时傷。","去去圖南远，微才幸不忘。"]', '诗', 'shi', '', NULL, '贈張均員外 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('870e3c4a-aad8-4894-9aea-4b370f85f1c3', '送祖詠', '送祖詠', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["田家宜伏臘，歲晏子言歸。","石路雪初下，荒村雞共飛。","東原多煙火，北澗隱寒暉。","滿酌野人酒，倦聞鄰女機。","胡爲困樵采，幾日罷朝衣。"]', '["田家宜伏臘，歲晏子言归。","石路雪初下，荒村雞共飞。","东原多煙火，北澗隐寒暉。","满酌野人酒，倦闻鄰女機。","胡爲困樵采，幾日罷朝衣。"]', '诗', 'shi', '', NULL, '送祖詠 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a44bdecf-5ede-48fe-b212-ffdd445c7ed0', '送綦毋潛', '送綦毋潛', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["夫君不得意，本自滄海來。","高足未云騁，虛舟空復迴。","淮南楓葉落，灞岸桃花開。","出處暫爲耳，沈浮安繫哉。","如何天覆物，還遣世遺才。","欲識秦將漢，嘗聞王與裴。","離筵對寒食，別雨乘春雷。","會有徵書到，荷衣且漫裁。"]', '["夫君不得意，本自滄海来。","高足未云騁，虛舟空复迴。","淮南楓葉落，灞岸桃花开。","出处暫爲耳，沈浮安繫哉。","如何天覆物，還遣世遺才。","欲識秦將漢，嘗闻王與裴。","離筵对寒食，別雨乘春雷。","會有徵书到，荷衣且漫裁。"]', '诗', 'shi', '', NULL, '送綦毋潛 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1d4ecde-af9a-42b3-a9b6-00369331957a', '送趙都護赴安西', '送趙都護赴安西', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["下客候旌麾，元戎復在斯。","門開都護府，兵動羽林兒。","黠虜多翻覆，謀臣有別離。","智同天所授，恩共日相隨。","漢使開賓幕，胡笳送酒巵。","風霜迎馬首，雨雪事魚麗。","上策應無戰，深情屬載馳。","不應行萬里，明主寄安危。"]', '["下客候旌麾，元戎复在斯。","门开都護府，兵动羽林兒。","黠虜多翻覆，謀臣有別離。","智同天所授，恩共日相隨。","漢使开賓幕，胡笳送酒巵。","风霜迎马首，雨雪事鱼丽。","上策應無戰，深情屬載驰。","不應行万里，明主寄安危。"]', '诗', 'shi', '', NULL, '送趙都護赴安西 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a351ea47-24d1-4371-99e1-9b67d41e6b92', '追涼歷下古城西北隅此地有清泉喬木', '追涼歷下古城西北隅此地有清泉喬木', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["謝朓出華省，王祥貽佩刀。","前賢真可慕，衰病意空勞。","貞悔不自卜，遊隨共爾曹。","未能齊得喪，時復誦離騷。","閑蔭七賢地，醉餐三士桃。","蒼苔虞舜井，喬木古城壕。","漁父偏相狎，堯年不可逃。","蟬鳴秋雨霽，雲白曉山高。","咫尺傳雙鯉，吹噓借一毛。","故人皆得路，誰肯念同袍。"]', '["謝朓出华省，王祥貽佩刀。","前賢真可慕，衰病意空勞。","貞悔不自卜，游隨共爾曹。","未能齊得喪，时复誦離騷。","闲蔭七賢地，醉餐三士桃。","蒼苔虞舜井，喬木古城壕。","漁父偏相狎，堯年不可逃。","蟬鳴秋雨霽，云白晓山高。","咫尺傳雙鯉，吹噓借一毛。","故人皆得路，誰肯念同袍。"]', '诗', 'shi', '', NULL, '追涼歷下古城西北隅此地有清泉喬木 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53e554ae-c6f6-4c94-98ef-af18f928df65', '戲贈邵使君張郎', '戲贈邵使君張郎', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["少婦石榴裙，新妝白玉面。","能迷張公子，不許時相見。"]', '["少婦石榴裙，新妝白玉面。","能迷張公子，不許时相见。"]', '诗', 'shi', '', NULL, '戲贈邵使君張郎 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90b23220-6f8f-4c62-9308-fc6a0ce4212a', '同王維過崔處士林亭', '同王維過崔处士林亭', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["映竹時聞轉轆轤，當窗只見網蜘蛛。","主人非病常高臥，環堵蒙籠一老儒。"]', '["映竹时闻轉轆轤，當窗只见網蜘蛛。","主人非病常高臥，环堵蒙籠一老儒。"]', '诗', 'shi', '', NULL, '同王維過崔處士林亭 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6306074-ffac-44d0-848d-eb72dfc04a9b', '寄河上段十六', '寄河上段十六', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["與君相識即相親，聞道君家住孟津。","爲見行舟試借問，客中時有洛陽人。"]', '["與君相識即相親，闻道君家住孟津。","爲见行舟試借问，客中时有洛陽人。"]', '诗', 'shi', '', NULL, '寄河上段十六 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4d4f345-0f61-475f-8195-c0e3f6b54584', '寒食', '寒食', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["子推言避世，山火遂焚身。","四海同寒食，千秋爲一人。","深冤何用道，峻跡古無鄰。","魂魄山河氣，風雷御宇神。","光煙榆柳滅，怨曲龍虵新。","可歎文公霸，平生負此臣。"]', '["子推言避世，山火遂焚身。","四海同寒食，千秋爲一人。","深冤何用道，峻跡古無鄰。","魂魄山河氣，风雷御宇神。","光煙榆柳滅，怨曲龙虵新。","可歎文公霸，平生負此臣。"]', '诗', 'shi', '', NULL, '寒食 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2689fa9d-0e60-4e45-a7e1-4a621c6372fe', '八月十五日象自江東止田園移莊慶會未幾歸汶上小弟幼妹尤嗟其別兼賦是詩三首 一', '八月十五日象自江东止田园移莊慶會未幾归汶上小弟幼妹尤嗟其別兼賦是诗三首 一', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["謝病始告歸，依然入桑梓。","家人皆佇立，相候衡門裏。","疇類皆長年，成人舊童子。","上堂家慶畢，願與親姻邇。","論舊或餘悲，思存且相喜。","田園轉蕪沒，但有寒泉水。","衰柳日蕭條，秋光清邑里。","入門乍如客，休騎非便止。","中飲顧王程，離憂從此始。"]', '["謝病始告归，依然入桑梓。","家人皆佇立，相候衡门裏。","疇類皆长年，成人旧童子。","上堂家慶畢，願與親姻邇。","論旧或餘悲，思存且相喜。","田园轉蕪沒，但有寒泉水。","衰柳日蕭條，秋光清邑里。","入门乍如客，休騎非便止。","中饮顧王程，離憂從此始。"]', '诗', 'shi', '', NULL, '八月十五日象自江東止田園移莊慶會未幾歸汶上小弟幼妹尤嗟其別兼賦是詩三首 一 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13c9fada-ca33-4437-b291-69207a959dc5', '八月十五日象自江東止田園移莊慶會未幾歸汶上小弟幼妹尤嗟其別兼賦是詩三首 二', '八月十五日象自江东止田园移莊慶會未幾归汶上小弟幼妹尤嗟其別兼賦是诗三首 二', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["兩妹日長成，雙鬟將及人。","已能持寶瑟，自解掩羅巾。","念昔別時小，未知疎與親。","今來識離恨，掩淚方殷勤。"]', '["兩妹日长成，雙鬟將及人。","已能持寶瑟，自解掩羅巾。","念昔別时小，未知疎與親。","今来識離恨，掩泪方殷勤。"]', '诗', 'shi', '', NULL, '八月十五日象自江東止田園移莊慶會未幾歸汶上小弟幼妹尤嗟其別兼賦是詩三首 二 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('608f7819-e672-459f-9cbb-b6b3473c326f', '八月十五日象自江東止田園移莊慶會未幾歸汶上小弟幼妹尤嗟其別兼賦是詩三首 三', '八月十五日象自江东止田园移莊慶會未幾归汶上小弟幼妹尤嗟其別兼賦是诗三首 三', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["小弟更孩幼，歸來不相識。","同居雖漸慣，見人猶默默。","宛作越人言，殊鄉甘水食。","別此最爲難，淚盡有餘憶。"]', '["小弟更孩幼，归来不相識。","同居雖漸慣，见人猶默默。","宛作越人言，殊乡甘水食。","別此最爲难，泪尽有餘憶。"]', '诗', 'shi', '', NULL, '八月十五日象自江東止田園移莊慶會未幾歸汶上小弟幼妹尤嗟其別兼賦是詩三首 三 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aba73175-2c2d-41fa-ad97-c9b241417c2a', '歎白髮', '歎白髮', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["我年一何長，鬢髮日已白。","俛仰天地間，能爲幾時客。","惆悵故山雲，裴回空日夕。","何事與時人，東城復南陌。"]', '["我年一何长，鬢髮日已白。","俛仰天地间，能爲幾时客。","惆悵故山云，裴回空日夕。","何事與时人，东城复南陌。"]', '诗', 'shi', '', NULL, '歎白髮 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d305a948-9e29-44d8-9298-1c7a637ca876', '早秋宴張郎中海亭即事', '早秋宴張郎中海亭即事', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["邑有弦歌宰，翔鸞狎野鷗。","眷言華省舊，暫滯海池遊。","鬱島藏深竹，前谿對舞樓。","更聞書即事，雲物是新秋。"]', '["邑有弦歌宰，翔鸾狎野鷗。","眷言华省旧，暫滯海池游。","鬱島藏深竹，前谿对舞楼。","更闻书即事，云物是新秋。"]', '诗', 'shi', '', NULL, '早秋宴張郎中海亭即事 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3951125-52da-4ea2-bd12-c36d6e8f1e98', '句', '句', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["吳越山多秀，新安江甚清。","書名會粹才偏逸，酒號屠蘇味更醇。","初疑輕煙淡古松，又似山開萬仞峰。"]', '["吳越山多秀，新安江甚清。","书名會粹才偏逸，酒號屠蘇味更醇。","初疑轻煙淡古松，又似山开万仞峰。"]', '诗', 'shi', '', NULL, '句 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bedfaf3c-db06-4b7d-9435-a55e394bf8f7', '嵩山十志十首 其一', '嵩山十志十首 其一', '32453514-2fad-43f8-b56b-7bc129ee426c', '唐', '["山爲宅兮草爲堂，芝蘭兮葯房。","羅蘼蕪兮拍薜荔，荃壁兮蘭砌。","蘼蕪薜荔兮成草堂，陰陰邃兮馥馥香。","中有人兮信宜常，讀金書兮飲玉漿，童顏幽操兮不易長。"]', '["山爲宅兮草爲堂，芝蘭兮葯房。","羅蘼蕪兮拍薜荔，荃壁兮蘭砌。","蘼蕪薜荔兮成草堂，陰陰邃兮馥馥香。","中有人兮信宜常，读金书兮饮玉漿，童顏幽操兮不易长。"]', '诗', 'shi', '', NULL, '嵩山十志十首 其一 盧鴻一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2d94964-b281-4dab-b7d0-6f1c2b3a35f1', '嵩山十志十首 其二', '嵩山十志十首 其二', '32453514-2fad-43f8-b56b-7bc129ee426c', '唐', '["天門豁兮仙臺聳，傑屹崒兮零澒湧。","窮三休兮曠一觀，忽若登崑崙兮中期汗漫仙。","聳天關兮倒景臺，鯊顥氣兮軼囂埃。","皎皎之子兮自獨立，雲可朋兮赮可吸，曾何榮辱之所及。"]', '["天门豁兮仙台聳，傑屹崒兮零澒湧。","窮三休兮曠一观，忽若登崑崙兮中期汗漫仙。","聳天关兮倒景台，鯊顥氣兮軼囂埃。","皎皎之子兮自独立，云可朋兮赮可吸，曾何榮辱之所及。"]', '诗', 'shi', '', NULL, '嵩山十志十首 其二 盧鴻一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f7646b-27e6-4ba1-b033-848578a238a1', '嵩山十志十首 其三', '嵩山十志十首 其三', '32453514-2fad-43f8-b56b-7bc129ee426c', '唐', '["紫巖隈兮青谿側，雲松煙蔦兮千古色。","芳靃蘼兮蔭蒙蘢，幽人構館兮在其中。","靃蘼蒙蘢兮開樾館，臥風霄兮坐赮旦。","粵有賓兮時戾止，樵蘇不爨兮清淡已，永歲終朝兮常若此。"]', '["紫巖隈兮青谿側，云松煙蔦兮千古色。","芳靃蘼兮蔭蒙蘢，幽人構館兮在其中。","靃蘼蒙蘢兮开樾館，臥风霄兮坐赮旦。","粵有賓兮时戾止，樵蘇不爨兮清淡已，永歲終朝兮常若此。"]', '诗', 'shi', '', NULL, '嵩山十志十首 其三 盧鴻一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27a2907f-b550-4a46-8973-4e24d5e19dbf', '嵩山十志十首 其四', '嵩山十志十首 其四', '32453514-2fad-43f8-b56b-7bc129ee426c', '唐', '["臨泱漭兮背青熒，吐雲煙兮合窅冥。","怳欻翕兮杳幽靄，意縹緲兮羣仙會。","窅冥仙會兮枕煙庭，竦魂形兮凝視聽。","聞夫至誠必感兮祈此巔，契顥氣，養丹田，終彷像兮覯靈仙。"]', '["臨泱漭兮背青熒，吐云煙兮合窅冥。","怳欻翕兮杳幽靄，意縹緲兮羣仙會。","窅冥仙會兮枕煙庭，竦魂形兮凝視听。","闻夫至誠必感兮祈此巔，契顥氣，養丹田，終彷像兮覯靈仙。"]', '诗', 'shi', '', NULL, '嵩山十志十首 其四 盧鴻一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64d377ec-aa69-468e-8c30-2ccc80b3fbd2', '嵩山十志十首 其五', '嵩山十志十首 其五', '32453514-2fad-43f8-b56b-7bc129ee426c', '唐', '["水攢衝兮石叢聳，煥雲錦兮噴洶湧。","苔駮犖兮草夤緣，芳冪冪兮瀨濺濺。","石攢叢兮雲錦淙，波連珠兮文沓綘。","有潔冥者媚此幽，漱靈液兮樂天休，實獲我心兮夫何求。"]', '["水攢衝兮石叢聳，煥云錦兮噴洶湧。","苔駮犖兮草夤緣，芳冪冪兮瀨濺濺。","石攢叢兮云錦淙，波連珠兮文沓綘。","有潔冥者媚此幽，漱靈液兮乐天休，實獲我心兮夫何求。"]', '诗', 'shi', '', NULL, '嵩山十志十首 其五 盧鴻一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4931b852-e4fd-4473-b014-6308390904a6', '嵩山十志十首 其六', '嵩山十志十首 其六', '32453514-2fad-43f8-b56b-7bc129ee426c', '唐', '["霏微陰壑兮氣騰虹，迤邐危磴兮上凌空。","青霞杪兮紫雲垂，鸞歌鳳舞兮吹參差。","鸞吹鳳舞兮期仙磴，鴻駕迎兮瑤華贈。","山中人兮好神仙，想像聞此兮欲升煙，鑄月煉液兮竚還年。"]', '["霏微陰壑兮氣腾虹，迤邐危磴兮上凌空。","青霞杪兮紫云垂，鸾歌鳳舞兮吹參差。","鸾吹鳳舞兮期仙磴，鴻駕迎兮瑤华贈。","山中人兮好神仙，想像闻此兮欲升煙，鑄月煉液兮竚還年。"]', '诗', 'shi', '', NULL, '嵩山十志十首 其六 盧鴻一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c06b734d-acb4-4a0a-ba70-e9ba22f1678f', '嵩山十志十首 其七', '嵩山十志十首 其七', '32453514-2fad-43f8-b56b-7bc129ee426c', '唐', '["靈磯盤礴兮溜奔錯漱，冷風兮鎮冥壑。","研苔滋兮泉珠潔，一飲一憩兮氣想滅。","磷漣清淬兮滌煩磯，靈仙境兮仁智歸。","中有琴兮徽以玉，峨峨湯湯兮彈此曲，寄聲知音兮同所欲。"]', '["靈磯盤礴兮溜奔錯漱，冷风兮鎮冥壑。","研苔滋兮泉珠潔，一饮一憩兮氣想滅。","磷漣清淬兮滌煩磯，靈仙境兮仁智归。","中有琴兮徽以玉，峨峨湯湯兮彈此曲，寄声知音兮同所欲。"]', '诗', 'shi', '', NULL, '嵩山十志十首 其七 盧鴻一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4699c6a4-e9cb-4315-85ae-882145bdc345', '嵩山十志十首 其八', '嵩山十志十首 其八', '32453514-2fad-43f8-b56b-7bc129ee426c', '唐', '["青崖陰兮月磵曲，重幽疊邃兮隱淪躅。","草樹緜冪兮翠蒙蘢，當其無兮庭在中。","當無有用兮冪翠庭，神可谷兮道可冥。","有幽人兮張素琴，皇徽兮綠水陰，德之愔兮澹多心。"]', '["青崖陰兮月磵曲，重幽叠邃兮隐淪躅。","草樹緜冪兮翠蒙蘢，當其無兮庭在中。","當無有用兮冪翠庭，神可谷兮道可冥。","有幽人兮張素琴，皇徽兮綠水陰，德之愔兮澹多心。"]', '诗', 'shi', '', NULL, '嵩山十志十首 其八 盧鴻一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18e37bbe-ca89-418c-b448-a5fd41e4d72c', '嵩山十志十首 其九', '嵩山十志十首 其九', '32453514-2fad-43f8-b56b-7bc129ee426c', '唐', '["嵐氣肅兮巖翠冥，空陰虛兮戶芳迎。","披蕙帳兮促蘿筵，談空空兮覈元元。","蕙帳蘿筵兮洞元室，祕而幽兮真可吉。","返自然兮道可冥，澤妙思兮草玄經，結幽門兮在黃庭。"]', '["嵐氣肅兮巖翠冥，空陰虛兮戶芳迎。","披蕙帳兮促蘿筵，談空空兮覈元元。","蕙帳蘿筵兮洞元室，祕而幽兮真可吉。","返自然兮道可冥，澤妙思兮草玄經，結幽门兮在黄庭。"]', '诗', 'shi', '', NULL, '嵩山十志十首 其九 盧鴻一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e6bfc79-bfdb-4645-a08b-855124e0e02b', '嵩山十志十首 其十', '嵩山十志十首 其十', '32453514-2fad-43f8-b56b-7bc129ee426c', '唐', '["水碧色兮石金光，灩熠熠兮濙湟湟。","泉葩映兮煙蔦臨，紅灼灼，翠陰陰。","翠相鮮兮金碧潭，霜天洞兮煙景涵。","有幽人兮好冥絕，炳其煥兮凝其潔，悠悠千古長不滅。"]', '["水碧色兮石金光，灩熠熠兮濙湟湟。","泉葩映兮煙蔦臨，紅灼灼，翠陰陰。","翠相鲜兮金碧潭，霜天洞兮煙景涵。","有幽人兮好冥絕，炳其煥兮凝其潔，悠悠千古长不滅。"]', '诗', 'shi', '', NULL, '嵩山十志十首 其十 盧鴻一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06a2961a-ef57-431e-ba01-70fb91a5feac', '書殿賜宴應制', '书殿賜宴應制', '77e145f4-ffdb-4b8b-9220-6aeae7a26319', '唐', '["校文常近日，賜宴忽升天。","酒正傳桮至，饔人捧案前。","玉階鳴溜水，清閣引歸煙。","共惜芸香暮，春風幾萬年。"]', '["校文常近日，賜宴忽升天。","酒正傳桮至，饔人捧案前。","玉階鳴溜水，清閣引归煙。","共惜芸香暮，春风幾万年。"]', '诗', 'shi', '', NULL, '書殿賜宴應制 徐安貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3b708f8-cfaa-4fad-81bd-7219ca1f10ec', '從駕溫泉宮', '從駕溫泉宮', '77e145f4-ffdb-4b8b-9220-6aeae7a26319', '唐', '["神女調溫液，年年待聖人。","試開臨水殿，來洗屬車塵。","暖氣隨明主，恩波浹近臣。","靈威自無極，從此獻千春。"]', '["神女調溫液，年年待聖人。","試开臨水殿，来洗屬车塵。","暖氣隨明主，恩波浹近臣。","靈威自無極，從此獻千春。"]', '诗', 'shi', '', NULL, '從駕溫泉宮 徐安貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc54c1fe-7d4f-447d-bc10-258279a903a9', '送呂向補闕西岳勒碑', '送呂向補闕西岳勒碑', '77e145f4-ffdb-4b8b-9220-6aeae7a26319', '唐', '["聖作西山頌，君其出使年。","勒碑懸日月，驅傳接雲煙。","寒盡函關路，春歸洛水邊。","別離能幾許，朝暮玉墀前。"]', '["聖作西山頌，君其出使年。","勒碑懸日月，驱傳接云煙。","寒尽函关路，春归洛水邊。","別離能幾許，朝暮玉墀前。"]', '诗', 'shi', '', NULL, '送呂向補闕西岳勒碑 徐安貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f822b44c-7b45-4b63-9b1f-cd1a0b05a697', '送丹陽採訪', '送丹陽採訪', '77e145f4-ffdb-4b8b-9220-6aeae7a26319', '唐', '["郡縣分南國，皇華出聖朝。","爲憐鄉櫂近，不道使車遙。","舊俗吳三讓，遺風漢六條。","願言除疾苦，天子聽歌謠。"]', '["郡縣分南国，皇华出聖朝。","爲怜乡櫂近，不道使车遙。","旧俗吳三讓，遺风漢六條。","願言除疾苦，天子听歌謠。"]', '诗', 'shi', '', NULL, '送丹陽採訪 徐安貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e108e6e-25e0-4682-b0c6-c985af3c67f4', '送王判官', '送王判官', '77e145f4-ffdb-4b8b-9220-6aeae7a26319', '唐', '["明月開三峽，花源出五谿。","城池青壁裏，煙火綠林西。","不畏王程促，惟愁仙路迷。","巴東下歸櫂，莫待夜猨啼。"]', '["明月开三峽，花源出五谿。","城池青壁裏，煙火綠林西。","不畏王程促，惟愁仙路迷。","巴东下归櫂，莫待夜猨啼。"]', '诗', 'shi', '', NULL, '送王判官 徐安貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e35fd03-8317-42aa-8fde-a4f8171411a5', '題襄陽圖', '題襄陽圖', '77e145f4-ffdb-4b8b-9220-6aeae7a26319', '唐', '["畫得襄陽郡，依然見昔遊。","峴山思駐馬，漢水憶迴舟。","丹壑常含霽，青林不換秋。","圖書空咫尺，千里意悠悠。"]', '["畫得襄陽郡，依然见昔游。","峴山思駐马，漢水憶迴舟。","丹壑常含霽，青林不換秋。","圖书空咫尺，千里意悠悠。"]', '诗', 'shi', '', NULL, '題襄陽圖 徐安貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff975ce0-5934-4829-b0f2-2137e35c372e', '程將軍夫人挽詩', '程將軍夫人挽诗', '77e145f4-ffdb-4b8b-9220-6aeae7a26319', '唐', '["琴瑟調雙鳳，和鳴不獨飛。","正歌春可樂，行泣露先晞。","環珮聲猶在，房櫳夢不歸。","將軍休沐日，誰勸著新衣。"]', '["琴瑟調雙鳳，和鳴不独飞。","正歌春可乐，行泣露先晞。","环珮声猶在，房櫳梦不归。","將軍休沐日，誰勸著新衣。"]', '诗', 'shi', '', NULL, '程將軍夫人挽詩 徐安貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46a4f158-95b7-46f9-90f9-78bc571ae001', '奉和喜雪應制', '奉和喜雪應制', '77e145f4-ffdb-4b8b-9220-6aeae7a26319', '唐', '["兩宮齋祭近登臨，雨雪紛紛天晝陰。","祗爲經寒無瑞色，頓教正月滿春林。","蓬萊北上旌門暗，花萼南歸馬跡深。","自有三農歌帝力，還將萬庾荅堯心。"]', '["兩宮斋祭近登臨，雨雪紛紛天晝陰。","祗爲經寒無瑞色，頓教正月满春林。","蓬萊北上旌门暗，花萼南归马跡深。","自有三農歌帝力，還將万庾荅堯心。"]', '诗', 'shi', '', NULL, '奉和喜雪應制 徐安貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f5c513a-ea5a-41f3-b2d2-972e2252bee5', '聞鄰家理箏', '闻鄰家理箏', '77e145f4-ffdb-4b8b-9220-6aeae7a26319', '唐', '["北斗橫天夜欲闌，愁人倚月思無端。","忽聞畫閣秦箏逸，知是鄰家趙女彈。","曲成虛憶青蛾斂，調急遙憐玉指寒。","銀鎖重關聽未闢，不如眠去夢中看。"]', '["北斗橫天夜欲闌，愁人倚月思無端。","忽闻畫閣秦箏逸，知是鄰家趙女彈。","曲成虛憶青蛾斂，調急遙怜玉指寒。","銀鎖重关听未闢，不如眠去梦中看。"]', '诗', 'shi', '', NULL, '聞鄰家理箏 徐安貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41868e28-4951-42ea-81a9-ad68ceec1b88', '奉和聖製早度蒲津關', '奉和聖製早度蒲津关', '77e145f4-ffdb-4b8b-9220-6aeae7a26319', '唐', '["仙掌臨秦甸，虹橋闢晉關。","兩都分地險，一曲度河灣。","路得津門要，時稱古戍閑。","城花春正發，岸柳曙堪攀。","後乘猶臨水，前旌欲換山。","長安迴望日，宸御六龍還。"]', '["仙掌臨秦甸，虹橋闢晉关。","兩都分地險，一曲度河灣。","路得津门要，时稱古戍闲。","城花春正發，岸柳曙堪攀。","後乘猶臨水，前旌欲換山。","长安迴望日，宸御六龙還。"]', '诗', 'shi', '', NULL, '奉和聖製早度蒲津關 徐安貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46e9e27f-0f28-4152-8c32-05d172246cfa', '奉和聖製荅二相出雀鼠谷', '奉和聖製荅二相出雀鼠谷', '77e145f4-ffdb-4b8b-9220-6aeae7a26319', '唐', '["兩臣初入夢，二月扈巡邊。","澗北寒猶在，山南春半傳。","頌聲先奉御，辰象復回天。","雲日明千里，旌旗照一川。","柳陰低輦路，草色變新田。","還望汾陽近，宸遊自窅然。"]', '["兩臣初入梦，二月扈巡邊。","澗北寒猶在，山南春半傳。","頌声先奉御，辰象复回天。","云日明千里，旌旗照一川。","柳陰低輦路，草色变新田。","還望汾陽近，宸游自窅然。"]', '诗', 'shi', '', NULL, '奉和聖製荅二相出雀鼠谷 徐安貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('250a51c8-4f9f-4591-8a80-2f9936a6df35', '句', '句', '77e145f4-ffdb-4b8b-9220-6aeae7a26319', '唐', '["暮雨衣猶濕，春風帆正開。"]', '["暮雨衣猶濕，春风帆正开。"]', '诗', 'shi', '', NULL, '句 徐安貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e731e2-f5c3-412d-8aef-36ca8f5bf159', '奉和聖製荅張說南出雀鼠谷', '奉和聖製荅張说南出雀鼠谷', 'f0c0960c-ca89-41b0-b395-82346ffc2970', '唐', '["硤路繞河汾，晴光拂曙氛。","笳吟中嶺樹，仗入半峰雲。","頓覺山原盡，平看邑里分。","早行芳草迥，晚憩好風熏。","嘉頌推英宰，春遊扈聖君。","共欣承睿渥，日月照天文。"]', '["硤路繞河汾，晴光拂曙氛。","笳吟中嶺樹，仗入半峰云。","頓覺山原尽，平看邑里分。","早行芳草迥，晚憩好风熏。","嘉頌推英宰，春游扈聖君。","共欣承睿渥，日月照天文。"]', '诗', 'shi', '', NULL, '奉和聖製荅張說南出雀鼠谷 崔翹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72c5f082-92d4-4edf-9578-6b0d9188f80c', '送友人使夷陵', '送友人使夷陵', 'f0c0960c-ca89-41b0-b395-82346ffc2970', '唐', '["猨鳴三峽裏，行客舊霑裳。","復道從茲去，思君不暫忘。","開襟春葉短，分手夏條長。","獨有幽庭桂，年年空自芳。"]', '["猨鳴三峽裏，行客旧霑裳。","复道從茲去，思君不暫忘。","开襟春葉短，分手夏條长。","独有幽庭桂，年年空自芳。"]', '诗', 'shi', '', NULL, '送友人使夷陵 崔翹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b226af8-5d4f-42ba-8295-ed5c9c7617cc', '鄭郎中山亭', '鄭郎中山亭', 'f0c0960c-ca89-41b0-b395-82346ffc2970', '唐', '["篆筆飛章暇，園亭染翰游。","地奇人境別，事遠俗塵收。","書閣山雲起，琴齋澗月留。","泉清鱗影見，樹密鳥聲幽。","杜馥熏梅雨，荷香送麥秋。","無勞置驛騎，文酒可相求。"]', '["篆笔飞章暇，园亭染翰游。","地奇人境別，事远俗塵收。","书閣山云起，琴斋澗月留。","泉清鱗影见，樹密鸟声幽。","杜馥熏梅雨，荷香送麦秋。","無勞置驛騎，文酒可相求。"]', '诗', 'shi', '', NULL, '鄭郎中山亭 崔翹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99c735da-a0c6-4e4a-95e9-df063087ef5b', '奉和聖製荅張說扈從南出雀鼠谷', '奉和聖製荅張说扈從南出雀鼠谷', '1b88c0f9-2345-47dc-adeb-d239eabfe49d', '唐', '["何意重關道，千年過聖皇。","幽林承睿澤，閑客見清光。","日御仙途遠，山靈壽域長。","寒雲入晉薄，春樹隔汾香。","國佐同時雨，天文屬歲陽。","從來漢家盛，未若此巡方。"]', '["何意重关道，千年過聖皇。","幽林承睿澤，闲客见清光。","日御仙途远，山靈壽域长。","寒云入晉薄，春樹隔汾香。","国佐同时雨，天文屬歲陽。","從来漢家盛，未若此巡方。"]', '诗', 'shi', '', NULL, '奉和聖製荅張說扈從南出雀鼠谷 梁昇卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2e748c2-1c0f-4325-81dd-46e71e875e3f', '白雲溪', '白云溪', '5cb9caf6-23ff-4ea6-b009-ad76455f2820', '唐', '["山徑入修篁，深林蔽日光。","夏雲生嶂遠，瀑水引溪長。","秀跡逢皆勝，清芬坐轉涼。","回看玉樽夕，歸路賞前忘。"]', '["山徑入修篁，深林蔽日光。","夏云生嶂远，瀑水引溪长。","秀跡逢皆勝，清芬坐轉涼。","回看玉樽夕，归路賞前忘。"]', '诗', 'shi', '', NULL, '白雲溪 吳鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bacafdae-4b3f-4a78-8061-931d80385e3a', '題奉國寺', '題奉国寺', 'a36cb2fd-75c5-478b-b05a-8f8712b0d819', '唐', '["新秋夜何爽，露下風轉淒。","一磐竹林外，千燈花塔西。"]', '["新秋夜何爽，露下风轉淒。","一磐竹林外，千灯花塔西。"]', '诗', 'shi', '', NULL, '題奉國寺 陸海 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6971df43-734e-4388-a8d5-1b495931f02e', '題龍門寺', '題龙门寺', 'a36cb2fd-75c5-478b-b05a-8f8712b0d819', '唐', '["窗燈林靄裏，聞磬水聲中。","更與龍華會，爐煙滿夕風。"]', '["窗灯林靄裏，闻磬水声中。","更與龙华會，爐煙满夕风。"]', '诗', 'shi', '', NULL, '題龍門寺 陸海 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aa758a5-a3f4-41e5-b96c-3849ad719b0e', '句', '句', 'a36cb2fd-75c5-478b-b05a-8f8712b0d819', '唐', '["忽然一曲稱君心，破却中人百家產。","城外平人驅欲盡，帳中猶打衮花毬。"]', '["忽然一曲稱君心，破却中人百家產。","城外平人驱欲尽，帳中猶打衮花毬。"]', '诗', 'shi', '', NULL, '句 陸海 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ba0b4c0-83ef-4b26-a295-dbd2d216573c', '白牡丹', '白牡丹', '0bc29f7a-6a76-43da-a22d-9ff1b3325156', '唐', '["長安年少惜春殘，爭認慈恩紫牡丹。","別有玉盤乘露冷，無人起就月中看。"]', '["长安年少惜春殘，爭認慈恩紫牡丹。","別有玉盤乘露冷，無人起就月中看。"]', '诗', 'shi', '', NULL, '白牡丹 裴士淹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('354845c3-7b94-4e64-a220-7b15e747f294', '和從叔祿愔元日早朝', '和從叔祿愔元日早朝', '66fea38f-c75a-45af-a834-426716bfc61d', '唐', '["銅渾變秋節，玉律動年灰。","曖曖城霞旦，隱隱禁門開。","衆靈湊仙府，百神朝帝臺。","葉令雙鳧至，梁王駟馬來。","戈鋋映林闕，歌管拂塵埃。","保章望瑞氣，尚書免火災。","冠冕多秀士，簪裾饒上才。","誰憐張仲蔚，日暮反蒿萊。"]', '["銅渾变秋節，玉律动年灰。","曖曖城霞旦，隐隐禁门开。","衆靈湊仙府，百神朝帝台。","葉令雙鳧至，梁王駟马来。","戈鋋映林闕，歌管拂塵埃。","保章望瑞氣，尚书免火災。","冠冕多秀士，簪裾饒上才。","誰怜張仲蔚，日暮反蒿萊。"]', '诗', 'shi', '', NULL, '和從叔祿愔元日早朝 李元操 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('732e42d4-1fdf-4485-8c32-4cede895edc9', '昭君怨', '昭君怨', 'e12c3791-f522-45b8-a5fb-d995f76cb846', '唐', '["莫將鉛粉匣，不用鏡花光。","一去邊城路，何情更畫妝。","影銷胡地月，衣盡漢宮香。","妾死非關命，都緣怨斷腸。"]', '["莫將鉛粉匣，不用镜花光。","一去邊城路，何情更畫妝。","影銷胡地月，衣尽漢宮香。","妾死非关命，都緣怨斷腸。"]', '诗', 'shi', '', NULL, '昭君怨 顧朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b14551d-2650-480a-8bfd-4e38ec1c4f9e', '西塞山下迴舟作', '西塞山下迴舟作', '42d69bc5-00c6-4d79-a73c-cf6bc36fbc2f', '唐', '["匡廬舊業是誰主，吳越新居安此生。","白髮數莖歸未得，青山一望計還成。","鴉翻楓葉夕陽動，鷺立蘆花秋水明。","從此舍舟何所詣，酒旗歌扇正相迎。"]', '["匡廬旧業是誰主，吳越新居安此生。","白髮數莖归未得，青山一望計還成。","鴉翻楓葉夕陽动，鷺立蘆花秋水明。","從此舍舟何所詣，酒旗歌扇正相迎。"]', '诗', 'shi', '', NULL, '西塞山下迴舟作 陶峴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72fb2b39-9959-4985-8037-f4344492b1af', '酬諸公見過', '酬諸公见過', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["嗟予未喪，哀此孤生。","屏居藍田，薄地躬耕。","歲[晏]輸稅，以奉粢盛。","晨往東臯，草露未晞。","暮看煙火，負擔來歸。","我聞有客，足埽荆扉。","簞食伊何，疈瓜抓棗。","仰廁羣賢，皤然一老。","媿無莞簟，班荆席藁。","汎汎登陂，折彼荷花。","靜觀素鮪，俯映白沙。","山鳥羣飛，日隱輕霞。","登車上馬，倏忽雲散。","雀噪荒村，雞鳴空館。","還復幽獨，重欷累歎。"]', '["嗟予未喪，哀此孤生。","屏居藍田，薄地躬耕。","歲[晏]輸稅，以奉粢盛。","晨往东臯，草露未晞。","暮看煙火，負擔来归。","我闻有客，足埽荆扉。","簞食伊何，疈瓜抓棗。","仰廁羣賢，皤然一老。","媿無莞簟，班荆席藁。","汎汎登陂，折彼荷花。","静观素鮪，俯映白沙。","山鸟羣飞，日隐轻霞。","登车上马，倏忽云散。","雀噪荒村，雞鳴空館。","還复幽独，重欷累歎。"]', '诗', 'shi', '', NULL, '酬諸公見過 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e3f2512-69a6-42ae-ae02-da0f69b91237', '奉和聖製登降聖觀與宰臣等同望應制', '奉和聖製登降聖观與宰臣等同望應制', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["鳳扆朝碧落，龍圖耀金鏡。","維嶽降二臣，戴天臨萬姓。","山川八校滿，井邑三農竟。","比屋皆可封，誰家不相慶。","林疎遠村出，野曠寒山靜。","帝城雲裏深，渭水天邊映。","佳氣含風景，頌聲溢歌詠。","端拱能任賢，彌彰聖君聖。"]', '["鳳扆朝碧落，龙圖耀金镜。","維嶽降二臣，戴天臨万姓。","山川八校满，井邑三農竟。","比屋皆可封，誰家不相慶。","林疎远村出，野曠寒山静。","帝城云裏深，渭水天邊映。","佳氣含风景，頌声溢歌詠。","端拱能任賢，彌彰聖君聖。"]', '诗', 'shi', '', NULL, '奉和聖製登降聖觀與宰臣等同望應制 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf09db89-6a90-49b1-8f84-6cb59100e579', '奉和聖製御春明樓臨右相園亭賦樂賢詩應制', '奉和聖製御春明楼臨右相园亭賦乐賢诗應制', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["複道通長樂，青門臨上路。","遙聞鳳吹喧，闇識龍輿度。","褰旒明四目，伏檻紆三顧。","小苑接侯家，飛甍暎宮樹。","商山原上碧，滻水林端素。","銀漢下天章，瓊筵承湛露。","將非富人寵，信以平戎故。","從來簡帝心，詎得迴天步。"]', '["複道通长乐，青门臨上路。","遙闻鳳吹喧，闇識龙輿度。","褰旒明四目，伏檻紆三顧。","小苑接侯家，飞甍暎宮樹。","商山原上碧，滻水林端素。","銀漢下天章，瓊筵承湛露。","將非富人寵，信以平戎故。","從来簡帝心，詎得迴天步。"]', '诗', 'shi', '', NULL, '奉和聖製御春明樓臨右相園亭賦樂賢詩應制 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba2e464c-6b0f-43f7-8b54-7669e226d8a0', '奉和聖製送不蒙都護兼鴻臚卿歸安西應制', '奉和聖製送不蒙都護兼鴻臚卿归安西應制', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["上卿增命服，都護揚歸斾。","雜虜盡朝周，諸胡皆自鄶。","鳴笳瀚海曲，按節陽關外。","落日下河源，寒山靜秋塞。","萬方氛祲息，六合乾坤大。","無戰是天心，天心同覆載。"]', '["上卿增命服，都護揚归斾。","杂虜尽朝周，諸胡皆自鄶。","鳴笳瀚海曲，按節陽关外。","落日下河源，寒山静秋塞。","万方氛祲息，六合乾坤大。","無戰是天心，天心同覆載。"]', '诗', 'shi', '', NULL, '奉和聖製送不蒙都護兼鴻臚卿歸安西應制 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd3944f6-676d-4c8b-90ca-d694a69f30d9', '扶南曲歌詞五首 一', '扶南曲歌词五首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["翠羽流蘇帳，春眠曙不開。","羞從面色起，嬌逐語聲來。","早向昭陽殿，君王中使催。"]', '["翠羽流蘇帳，春眠曙不开。","羞從面色起，嬌逐語声来。","早向昭陽殿，君王中使催。"]', '诗', 'shi', '', NULL, '扶南曲歌詞五首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('200e8a61-6549-499e-99f4-3cb6a8172a6d', '扶南曲歌詞五首 二', '扶南曲歌词五首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["堂上青弦動，堂前綺席陳。","齊歌盧女曲，雙舞洛陽人。","傾國徒相看，寧知心所親。"]', '["堂上青弦动，堂前綺席陳。","齊歌盧女曲，雙舞洛陽人。","傾国徒相看，寧知心所親。"]', '诗', 'shi', '', NULL, '扶南曲歌詞五首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('628b0aeb-ace3-4f3b-b9af-419d426f3e3f', '扶南曲歌詞五首 三', '扶南曲歌词五首 三', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["香氣傳空滿，妝華影箔通。","歌聞天仗外，舞出御樓中。","日暮歸何處，花間長樂宮。"]', '["香氣傳空满，妝华影箔通。","歌闻天仗外，舞出御楼中。","日暮归何处，花间长乐宮。"]', '诗', 'shi', '', NULL, '扶南曲歌詞五首 三 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('236f6ed6-1bb0-4a8d-8e5b-23a124479863', '扶南曲歌詞五首 四', '扶南曲歌词五首 四', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["宮女還金屋，將眠復畏明。","入春輕衣好，半夜薄妝成。","拂曙朝前殿，玉墀多珮聲。"]', '["宮女還金屋，將眠复畏明。","入春轻衣好，半夜薄妝成。","拂曙朝前殿，玉墀多珮声。"]', '诗', 'shi', '', NULL, '扶南曲歌詞五首 四 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f085c143-e0b5-4598-a619-9b287fa463ae', '扶南曲歌詞五首 五', '扶南曲歌词五首 五', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["朝日照綺窗，佳人坐臨鏡。","散黛恨猶輕，插釵嫌未正。","同心勿遽遊，幸待春妝竟。"]', '["朝日照綺窗，佳人坐臨镜。","散黛恨猶轻，插釵嫌未正。","同心勿遽游，幸待春妝竟。"]', '诗', 'shi', '', NULL, '扶南曲歌詞五首 五 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a2d6357-424d-4ad8-a41e-73e2a4c8f570', '隴西行', '隴西行', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["十里一走馬，五里一揚鞭。","都護軍書至，匈奴圍酒泉。","關山正飛雪，烽戍斷無煙。"]', '["十里一走马，五里一揚鞭。","都護軍书至，匈奴圍酒泉。","关山正飞雪，烽戍斷無煙。"]', '诗', 'shi', '', NULL, '隴西行 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbf3f482-6a67-41a8-85c5-4bb74ff9e446', '從軍行', '從軍行', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["吹角動行人，喧喧行人起。","笳悲馬嘶亂，爭渡金河水。","日暮沙漠陲，戰聲煙塵裏。","盡繫名王頸，歸來獻天子。"]', '["吹角动行人，喧喧行人起。","笳悲马嘶亂，爭渡金河水。","日暮沙漠陲，戰声煙塵裏。","尽繫名王頸，归来獻天子。"]', '诗', 'shi', '', NULL, '從軍行 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('140031f2-d4e0-4555-b23b-92b10980f1ba', '早春行', '早春行', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["紫梅發初遍，黃鳥歌猶澁。","誰家折楊女，弄春如不及。","愛水看妝坐，羞人映花立。","香畏風吹散，衣愁露霑濕。","玉閨青門裏，日落香車入。","游衍益相思，含啼向綵帷。","憶君長入夢，歸晚更生疑。","不及紅簷燕，雙棲綠草時。"]', '["紫梅發初遍，黄鸟歌猶澁。","誰家折楊女，弄春如不及。","愛水看妝坐，羞人映花立。","香畏风吹散，衣愁露霑濕。","玉閨青门裏，日落香车入。","游衍益相思，含啼向綵帷。","憶君长入梦，归晚更生疑。","不及紅簷燕，雙棲綠草时。"]', '诗', 'shi', '', NULL, '早春行 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99c56ac4-c95e-4923-b0b8-b3809e62e1cf', '早朝', '早朝', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["皎潔明星高，蒼茫遠天曙。","槐霧暗不開，城鴉鳴稍去。","始聞高閣聲，莫辨更衣處。","銀燭已成行，金門儼騶馭。"]', '["皎潔明星高，蒼茫远天曙。","槐霧暗不开，城鴉鳴稍去。","始闻高閣声，莫辨更衣处。","銀燭已成行，金门儼騶馭。"]', '诗', 'shi', '', NULL, '早朝 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49f16d59-ce56-4ed7-b3b3-82571018a52a', '獻始興公', '獻始兴公', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["寧棲野樹林，寧飲澗水流。","不用坐[粱]肉，崎嶇見王侯。","鄙哉匹夫節，布褐將白頭。","任智誠則短，守任固其優。","側聞大君子，安問黨與讐。","所不賣公器，動爲蒼生謀。","賤子跪自陳，可爲帳下不。","感激有公議，曲私非所求。"]', '["寧棲野樹林，寧饮澗水流。","不用坐[粱]肉，崎嶇见王侯。","鄙哉匹夫節，布褐將白头。","任智誠則短，守任固其優。","側闻大君子，安问黨與讐。","所不賣公器，动爲蒼生謀。","賤子跪自陳，可爲帳下不。","感激有公議，曲私非所求。"]', '诗', 'shi', '', NULL, '獻始興公 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f24c33e3-89ea-4226-a9cf-b4a96e799784', '贈從弟司庫員外絿', '贈從弟司庫員外絿', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["少年識事淺，強學干名利。","徒聞躍馬年，苦無出人智。","即事豈徒言，累官非不試。","既寡遂性歡，恐招負時累。","清冬見遠山，積雪凝蒼翠。","浩然出東林，發我遺世意。","惠連素清賞，夙語塵外事。","欲緩攜手期，流年一何駛。"]', '["少年識事淺，強学干名利。","徒闻躍马年，苦無出人智。","即事豈徒言，累官非不試。","既寡遂性歡，恐招負时累。","清冬见远山，積雪凝蒼翠。","浩然出东林，發我遺世意。","惠連素清賞，夙語塵外事。","欲緩携手期，流年一何駛。"]', '诗', 'shi', '', NULL, '贈從弟司庫員外絿 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('936413e8-e197-4c55-afdc-35cfd1766e28', '座上走筆贈薛璩慕容損', '座上走笔贈薛璩慕容損', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["希世無高節，絕跡有卑棲。","君徒視人文，吾固和天倪。","緬然萬物始，及與羣物齊。","分地依后稷，用天信重黎。","春風何豫人，令我思東溪。","草色有佳意，花枝稍含荑。","更待風景好，與君藉萋萋。"]', '["希世無高節，絕跡有卑棲。","君徒視人文，吾固和天倪。","緬然万物始，及與羣物齊。","分地依后稷，用天信重黎。","春风何豫人，令我思东溪。","草色有佳意，花枝稍含荑。","更待风景好，與君藉萋萋。"]', '诗', 'shi', '', NULL, '座上走筆贈薛璩慕容損 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a1cc786-251a-45ef-8db5-57daaf8168c4', '贈李頎', '贈李頎', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["聞君餌丹砂，甚有好顏色。","不知從今去，幾時生羽翼。","王母翳華芝，望爾崑崙側。","文螭從赤豹，萬里方一息。","悲哉世上人，甘此羶腥食。"]', '["闻君餌丹砂，甚有好顏色。","不知從今去，幾时生羽翼。","王母翳华芝，望爾崑崙側。","文螭從赤豹，万里方一息。","悲哉世上人，甘此羶腥食。"]', '诗', 'shi', '', NULL, '贈李頎 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcfe7a85-54be-4bed-8184-2500df7f4f5f', '贈劉藍田', '贈劉藍田', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["籬間犬迎吠，出屋候荆扉。","歲晏輸井稅，山村人夜歸。","晚田始家食，餘布成我衣。","詎肯無公事，煩君問是非。"]', '["籬间犬迎吠，出屋候荆扉。","歲晏輸井稅，山村人夜归。","晚田始家食，餘布成我衣。","詎肯無公事，煩君问是非。"]', '诗', 'shi', '', NULL, '贈劉藍田 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c56ad009-5acd-4331-adc9-f529fdbb72bb', '贈房盧氏琯', '贈房盧氏琯', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["達人無不可，忘己愛蒼生。","豈復少十室，弦歌在兩楹。","浮人日已歸，但坐事農耕。","桑榆鬱相望，邑里多雞鳴。","秋山一何淨，蒼翠臨寒城。","視事兼偃臥，對書不簪纓。","蕭條人吏疎，鳥雀下空庭。","鄙夫心所尚，晚節異平生。","將從海岳居，守靜解天刑。","或可累安邑，茅茨君試營。"]', '["達人無不可，忘己愛蒼生。","豈复少十室，弦歌在兩楹。","浮人日已归，但坐事農耕。","桑榆鬱相望，邑里多雞鳴。","秋山一何淨，蒼翠臨寒城。","視事兼偃臥，对书不簪纓。","蕭條人吏疎，鸟雀下空庭。","鄙夫心所尚，晚節異平生。","將從海岳居，守静解天刑。","或可累安邑，茅茨君試營。"]', '诗', 'shi', '', NULL, '贈房盧氏琯 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('480b41ca-28dd-45c9-b5be-7c8720008f47', '贈祖三詠', '贈祖三詠', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["蟏蛸挂虛牖，蟋蟀鳴前除。","歲晏涼風至，君子復何如。","高館闃無人，離居不可道。","閑門寂已閉，落日照秋草。","雖有近音信，千里阻河關。","中復客汝潁，去年歸舊山。","結交二十載，不得一日展。","貧病子既深，契闊余不淺。","仲秋雖未歸，暮秋以爲期。","良會詎幾日，終日長相思。"]', '["蟏蛸挂虛牖，蟋蟀鳴前除。","歲晏涼风至，君子复何如。","高館闃無人，離居不可道。","闲门寂已閉，落日照秋草。","雖有近音信，千里阻河关。","中复客汝潁，去年归旧山。","結交二十載，不得一日展。","貧病子既深，契闊余不淺。","仲秋雖未归，暮秋以爲期。","良會詎幾日，終日长相思。"]', '诗', 'shi', '', NULL, '贈祖三詠 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35fb081d-d481-41c6-8ef3-8eb84fae4134', '春夜竹亭贈錢少府歸藍田', '春夜竹亭贈錢少府归藍田', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["夜靜羣動息，時聞隔林犬。","却憶山中時，人家澗西遠。","羨君明發去，采蕨輕軒冕。"]', '["夜静羣动息，时闻隔林犬。","却憶山中时，人家澗西远。","羨君明發去，采蕨轻軒冕。"]', '诗', 'shi', '', NULL, '春夜竹亭贈錢少府歸藍田 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('076b8da6-83c1-41dc-8893-13425a6dc1e8', '戲贈張五弟諲三首 一', '戲贈張五弟諲三首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["吾弟東山時，心尚一何遠。","日高猶自臥，鐘動始能飯。","領上髪未梳，牀頭書不卷。","清川興悠悠，空林對偃蹇。","青苔石上淨，細草松下軟。","窗外鳥聲閑，階前虎心善。","徒然萬象多，澹爾太虛緬。","一知與物平，自顧爲人淺。","對君忽自得，浮念不煩遣。"]', '["吾弟东山时，心尚一何远。","日高猶自臥，鐘动始能飯。","領上髪未梳，牀头书不卷。","清川兴悠悠，空林对偃蹇。","青苔石上淨，細草松下軟。","窗外鸟声闲，階前虎心善。","徒然万象多，澹爾太虛緬。","一知與物平，自顧爲人淺。","对君忽自得，浮念不煩遣。"]', '诗', 'shi', '', NULL, '戲贈張五弟諲三首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91b6c0f1-eabf-4fe6-9975-ed5a592f7b4f', '戲贈張五弟諲三首 二', '戲贈張五弟諲三首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["張弟五車書，讀書仍隱居。","染翰過草聖，賦詩輕子虛。","閉門二室下，隱居十年餘。","宛是野人野，時從漁夫漁。","秋風自蕭索，五柳高且疎。","望此去人世，渡水向吾廬。","歲晏同攜手，只應君與予。"]', '["張弟五车书，读书仍隐居。","染翰過草聖，賦诗轻子虛。","閉门二室下，隐居十年餘。","宛是野人野，时從漁夫漁。","秋风自蕭索，五柳高且疎。","望此去人世，渡水向吾廬。","歲晏同携手，只應君與予。"]', '诗', 'shi', '', NULL, '戲贈張五弟諲三首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fa97957-588a-4bdc-841b-05ddfcdc0d96', '戲贈張五弟諲三首 三', '戲贈張五弟諲三首 三', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["設罝守毚兔，垂釣伺遊鱗。","此是安口腹，非關慕隱淪。","吾生好清淨，蔬食去情塵。","今子方豪蕩，思爲鼎食人。","我家南山下，動息自遺身。","入鳥不相亂，見獸皆相親。","雲霞成伴侶，虛白侍衣巾。","何事須夫子，邀予谷口真。"]', '["設罝守毚兔，垂釣伺游鱗。","此是安口腹，非关慕隐淪。","吾生好清淨，蔬食去情塵。","今子方豪蕩，思爲鼎食人。","我家南山下，动息自遺身。","入鸟不相亂，见獸皆相親。","云霞成伴侶，虛白侍衣巾。","何事須夫子，邀予谷口真。"]', '诗', 'shi', '', NULL, '戲贈張五弟諲三首 三 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('521c50b8-4eac-4ee4-85a6-f06ac42ed74c', '胡居士臥病遺米因贈', '胡居士臥病遺米因贈', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["了觀四大因，根性何所有。","妄計苟不生，是身孰休咎。","色聲何謂客，陰界復誰守。","徒言蓮花目，豈惡楊枝肘。","既飽香積飯，不醉聲聞酒。","有無斷常見，生滅幻夢受。","即病即實相，趨空定狂走。","無有一法真，無有一法垢。","居士素通達，隨宜善抖擻。","牀上無氊臥，鎘中有粥否。","齋時不乞食，定應空漱口。","聊持數斗米，且救浮生取。"]', '["了观四大因，根性何所有。","妄計苟不生，是身孰休咎。","色声何謂客，陰界复誰守。","徒言蓮花目，豈惡楊枝肘。","既飽香積飯，不醉声闻酒。","有無斷常见，生滅幻梦受。","即病即實相，趨空定狂走。","無有一法真，無有一法垢。","居士素通達，隨宜善抖擻。","牀上無氊臥，鎘中有粥否。","斋时不乞食，定應空漱口。","聊持數斗米，且救浮生取。"]', '诗', 'shi', '', NULL, '胡居士臥病遺米因贈 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6f432a3-b716-4b40-965a-83eb0ce83c44', '贈裴十迪', '贈裴十迪', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["風景日夕佳，與君賦新詩。","澹然望遠空，如意方支頤。","春風動百草，蘭蕙生我籬。","曖曖日暖閨，田家來致詞。","欣欣春還臯，淡淡水生陂。","桃李雖未開，荑萼滿芳枝。","請君理還策，敢告將農時。"]', '["风景日夕佳，與君賦新诗。","澹然望远空，如意方支頤。","春风动百草，蘭蕙生我籬。","曖曖日暖閨，田家来致词。","欣欣春還臯，淡淡水生陂。","桃李雖未开，荑萼满芳枝。","請君理還策，敢告將農时。"]', '诗', 'shi', '', NULL, '贈裴十迪 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bebdd6d-6adb-42aa-9bc3-d3cf41c45687', '與胡居士皆病寄此詩兼示學人二首 一', '與胡居士皆病寄此诗兼示学人二首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["一興微塵念，橫有朝露身。","如是覩陰界，何方置我人。","礙有固爲主，趣空寧捨賓。","洗心詎懸解，悟道正迷津。","因愛果生病，從貪始覺貧。","色聲非彼妄，浮幻即吾真。","四達竟何遣，萬殊安可塵。","胡生但高枕，寂寞與誰鄰。","戰勝不謀食，理齊甘負薪。","予若未始異，詎論疎與親。"]', '["一兴微塵念，橫有朝露身。","如是覩陰界，何方置我人。","礙有固爲主，趣空寧捨賓。","洗心詎懸解，悟道正迷津。","因愛果生病，從貪始覺貧。","色声非彼妄，浮幻即吾真。","四達竟何遣，万殊安可塵。","胡生但高枕，寂寞與誰鄰。","戰勝不謀食，理齊甘負薪。","予若未始異，詎論疎與親。"]', '诗', 'shi', '', NULL, '與胡居士皆病寄此詩兼示學人二首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e475dcae-9e34-4c68-b7b8-3c700418def0', '與胡居士皆病寄此詩兼示學人二首 二', '與胡居士皆病寄此诗兼示学人二首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["浮空徒漫漫，汎有定悠悠。","無乘及乘者，所謂智人舟。","詎捨貧病域，不疲生死流。","無煩君喻馬，任以我爲牛。","植福祠迦葉，求仁笑孔丘。","何津不鼓櫂，何路不摧輈。","念此聞思者，胡爲多阻修。","空虛花聚散，煩惱樹稀稠。","滅相成無記，生心坐有求。","降吳復歸蜀，不到莫相尤。"]', '["浮空徒漫漫，汎有定悠悠。","無乘及乘者，所謂智人舟。","詎捨貧病域，不疲生死流。","無煩君喻马，任以我爲牛。","植福祠迦葉，求仁笑孔丘。","何津不鼓櫂，何路不摧輈。","念此闻思者，胡爲多阻修。","空虛花聚散，煩惱樹稀稠。","滅相成無記，生心坐有求。","降吳复归蜀，不到莫相尤。"]', '诗', 'shi', '', NULL, '與胡居士皆病寄此詩兼示學人二首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2307887c-ece7-4f85-a263-b77871daa4d2', '奉寄韋太守陟', '奉寄韋太守陟', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["荒城自蕭索，萬里山河空。","天高秋日逈，嘹唳聞歸鴻。","寒塘映衰草，高館落疎桐。","臨此歲方[晏]，顧景詠悲翁。","故人不可見，寂寞平陵東。"]', '["荒城自蕭索，万里山河空。","天高秋日逈，嘹唳闻归鴻。","寒塘映衰草，高館落疎桐。","臨此歲方[晏]，顧景詠悲翁。","故人不可见，寂寞平陵东。"]', '诗', 'shi', '', NULL, '奉寄韋太守陟 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edda303d-6668-407b-b213-8dbb0fffd9aa', '林園即事寄舍弟紞', '林园即事寄舍弟紞', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["寓目一蕭散，銷憂冀俄頃。","青草肅澄陂，白雲移翠嶺。","後沔通河渭，前山包鄢郢。","松含風裏聲，花對池中影。","地多齊后㿉，人帶荆州癭。","徒思赤筆書，詎有丹砂井。","心悲常欲絕，髪亂不能整。","青簟日何長，閑門晝方靜。","頹思茅簷下，彌傷好風景。"]', '["寓目一蕭散，銷憂冀俄頃。","青草肅澄陂，白云移翠嶺。","後沔通河渭，前山包鄢郢。","松含风裏声，花对池中影。","地多齊后㿉，人带荆州癭。","徒思赤笔书，詎有丹砂井。","心悲常欲絕，髪亂不能整。","青簟日何长，闲门晝方静。","頹思茅簷下，彌傷好风景。"]', '诗', 'shi', '', NULL, '林園即事寄舍弟紞 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37c9123a-0681-4438-b663-ec71683726cf', '至滑州隔河望黎陽憶丁三宇', '至滑州隔河望黎陽憶丁三宇', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["隔河見桑柘，藹藹黎陽川。","望望行漸遠，孤峰沒雲煙。","故人不可見，河水復悠然。","賴有政聲遠，時聞行路傳。"]', '["隔河见桑柘，藹藹黎陽川。","望望行漸远，孤峰沒云煙。","故人不可见，河水复悠然。","賴有政声远，时闻行路傳。"]', '诗', 'shi', '', NULL, '至滑州隔河望黎陽憶丁三宇 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dcc281d-d43e-499a-8927-8e044ea854b0', '秋夜獨坐懷內弟崔興宗', '秋夜独坐懷內弟崔兴宗', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["夜靜羣動息，蟪蛄聲悠悠。","庭槐北風響，日夕方高秋。","思子整羽翰，及時當雲浮。","吾生將白首，歲晏思滄州。","高足在旦暮，肯爲南畝儔。"]', '["夜静羣动息，蟪蛄声悠悠。","庭槐北风响，日夕方高秋。","思子整羽翰，及时當云浮。","吾生將白首，歲晏思滄州。","高足在旦暮，肯爲南畝儔。"]', '诗', 'shi', '', NULL, '秋夜獨坐懷內弟崔興宗 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1de387b1-582c-4f78-9aa1-d0e343d3ed4c', '和使君五郎西樓望遠思歸', '和使君五郎西楼望远思归', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["高樓望所思，目極情未畢。","枕上見千里，窗中窺萬室。","悠悠長路人，曖曖遠郊日。","惆悵極浦外，迢遞孤煙出。","能賦屬上才，思歸同下秩。","故鄉不可見，雲水空如一。"]', '["高楼望所思，目極情未畢。","枕上见千里，窗中窺万室。","悠悠长路人，曖曖远郊日。","惆悵極浦外，迢遞孤煙出。","能賦屬上才，思归同下秩。","故乡不可见，云水空如一。"]', '诗', 'shi', '', NULL, '和使君五郎西樓望遠思歸 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9250ba9d-bd94-4a04-b1c1-512158537ff3', '酬黎居士淅川作', '酬黎居士淅川作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["儂家真箇去，公定隨儂否。","著處是蓮花，無心變楊柳。","松龕藏藥裹，石脣安茶臼。","氣味當共知，那能不攜手。"]', '["儂家真箇去，公定隨儂否。","著处是蓮花，無心变楊柳。","松龕藏藥裹，石脣安茶臼。","氣味當共知，那能不携手。"]', '诗', 'shi', '', NULL, '酬黎居士淅川作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53ad408a-348f-4d20-9036-d4bb67ead296', '送魏郡李太守赴任', '送魏郡李太守赴任', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["與君伯氏別，又欲與君離。","君行無幾日，當復隔山陂。","蒼茫秦川盡，日落桃林塞。","獨樹臨關門，黃河向天外。","前經洛陽陌，宛洛故人稀。","故人離別盡，淇上轉驂騑。","企予悲送遠，惆悵睢陽路。","古木官渡平，秋城鄴宮故。","想君行縣日，其出從如雲。","遙思魏公子，復憶李將軍。"]', '["與君伯氏別，又欲與君離。","君行無幾日，當复隔山陂。","蒼茫秦川尽，日落桃林塞。","独樹臨关门，黄河向天外。","前經洛陽陌，宛洛故人稀。","故人離別尽，淇上轉驂騑。","企予悲送远，惆悵睢陽路。","古木官渡平，秋城鄴宮故。","想君行縣日，其出從如云。","遙思魏公子，复憶李將軍。"]', '诗', 'shi', '', NULL, '送魏郡李太守赴任 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7762fa57-7362-4dc5-ac5f-dbae7b4db5aa', '送陸員外', '送陸員外', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["郎署有伊人，居然古人風。","天子顧河北，詔書除征東。","拜手辭上官，緩步出南宮。","九河平原外，七國薊門中。","陰風悲枯桑，古塞多飛蓬。","萬里不見虜，蕭條胡地空。","無爲費中國，更欲邀奇功。","遲遲前相送，握手嗟異同。","行當對侯歸，肯訪商山翁。"]', '["郎署有伊人，居然古人风。","天子顧河北，詔书除征东。","拜手辞上官，緩步出南宮。","九河平原外，七国薊门中。","陰风悲枯桑，古塞多飞蓬。","万里不见虜，蕭條胡地空。","無爲費中国，更欲邀奇功。","遲遲前相送，握手嗟異同。","行當对侯归，肯訪商山翁。"]', '诗', 'shi', '', NULL, '送陸員外 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e22d5990-3037-4325-bb6a-a2146d3e8a8e', '送宇文太守赴宣城', '送宇文太守赴宣城', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["寥落雲外山，迢遞舟中賞。","鐃吹發西江，秋空多清響。","地迥古城蕪，月明寒潮廣。","時賽敬亭神，復解罟師網。","何處寄相思？南風吹五兩。"]', '["寥落云外山，迢遞舟中賞。","鐃吹發西江，秋空多清响。","地迥古城蕪，月明寒潮廣。","时賽敬亭神，复解罟師網。","何处寄相思？南风吹五兩。"]', '诗', 'shi', '', NULL, '送宇文太守赴宣城 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4371ef7-c1bd-4b60-af88-48b670052b84', '送綦毋秘書棄官還江東', '送綦毋秘书棄官還江东', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["明時久不達，棄置與君同。","天命無怨色，人生有素風。","念君拂衣去，四海將安窮。","秋天萬里淨，日暮澄江空。","清夜何悠悠，扣舷明月中。","和光魚鳥際，澹爾蒹葭叢。","無庸客昭世，衰鬢日如蓬。","頑疎暗人事，僻陋遠天聰。","微物縱可采，其誰爲至公。","余亦從此去，歸耕爲老農。"]', '["明时久不達，棄置與君同。","天命無怨色，人生有素风。","念君拂衣去，四海將安窮。","秋天万里淨，日暮澄江空。","清夜何悠悠，扣舷明月中。","和光鱼鸟際，澹爾蒹葭叢。","無庸客昭世，衰鬢日如蓬。","頑疎暗人事，僻陋远天聰。","微物縱可采，其誰爲至公。","余亦從此去，归耕爲老農。"]', '诗', 'shi', '', NULL, '送綦毋秘書棄官還江東 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('311012d6-2c74-4277-b53f-b8ef1cc54b9a', '奉送六舅歸陸渾', '奉送六舅归陸渾', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["伯舅吏淮泗，卓魯方喟然。","悠哉自不競，退耕東臯田。","條桑臘月下，種杏春風前。","酌醴賦歸去，共知陶令賢。"]', '["伯舅吏淮泗，卓魯方喟然。","悠哉自不競，退耕东臯田。","條桑臘月下，種杏春风前。","酌醴賦归去，共知陶令賢。"]', '诗', 'shi', '', NULL, '奉送六舅歸陸渾 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31cc87f3-da0f-421d-8674-8753530077e2', '送別', '送別', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["下馬飲君酒，問君何所之。","君言不得意，歸臥南山陲。","但去莫復問，白雲無盡時。"]', '["下马饮君酒，问君何所之。","君言不得意，归臥南山陲。","但去莫复问，白云無尽时。"]', '诗', 'shi', '', NULL, '送別 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b76b81d-f768-4aa8-b566-40d82160ce75', '送張五歸山', '送張五归山', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["送君盡惆悵，復送何人歸。","幾日同攜手，一朝先拂衣。","東山有茅屋，幸爲埽荆扉。","當亦謝官去，豈令心事違。"]', '["送君尽惆悵，复送何人归。","幾日同携手，一朝先拂衣。","东山有茅屋，幸爲埽荆扉。","當亦謝官去，豈令心事違。"]', '诗', 'shi', '', NULL, '送張五歸山 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ae49034-21b0-4273-98d3-fa7abf5a407d', '齊州送祖三', '齊州送祖三', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["相逢方一笑，相送還成泣。","祖帳已傷離，荒城復愁入。","天寒遠山淨，日暮長河急。","解纜君已遙，望君猶佇立。"]', '["相逢方一笑，相送還成泣。","祖帳已傷離，荒城复愁入。","天寒远山淨，日暮长河急。","解纜君已遙，望君猶佇立。"]', '诗', 'shi', '', NULL, '齊州送祖三 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80997560-77bc-4730-b79d-2327a02f088a', '送縉雲苗太守', '送縉云苗太守', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["手疏謝明主，腰章爲長吏。","方從會稽邸，更發汝南騎。","按節下松陽，清江響鐃吹。","露冕見三吳，方知百城貴。"]', '["手疏謝明主，腰章爲长吏。","方從會稽邸，更發汝南騎。","按節下松陽，清江响鐃吹。","露冕见三吳，方知百城貴。"]', '诗', 'shi', '', NULL, '送縉雲苗太守 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b9a9e77-c255-4534-b29a-163153978ceb', '送從弟蕃遊淮南', '送從弟蕃游淮南', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["讀書復騎射，帶劒遊淮陰。","淮陰少年輩，千里遠相尋。","高義難自隱，明時寧陸沈。","島夷九州外，泉館三山深。","席帆聊問罪，卉服盡成擒。","歸來見天子，拜爵賜黃金。","忽思鱸魚鱠，復有滄洲心。","天寒蒹葭渚，日落雲夢林。","江城下楓葉，淮上聞秋砧。","送歸青門外，車馬去駸駸。","惆悵新豐樹，空餘天際禽。"]', '["读书复騎射，带劒游淮陰。","淮陰少年輩，千里远相尋。","高義难自隐，明时寧陸沈。","島夷九州外，泉館三山深。","席帆聊问罪，卉服尽成擒。","归来见天子，拜爵賜黄金。","忽思鱸鱼鱠，复有滄洲心。","天寒蒹葭渚，日落云梦林。","江城下楓葉，淮上闻秋砧。","送归青门外，车马去駸駸。","惆悵新豐樹，空餘天際禽。"]', '诗', 'shi', '', NULL, '送從弟蕃遊淮南 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e791098d-353d-4ae7-abb4-f632f596eacf', '送高適弟耽歸臨淮作', '送高適弟耽归臨淮作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["少年客淮泗，落魄居下邳。","遨遊向燕趙，結客過臨淄。","山東諸侯國，迎送紛交馳。","自爾厭游俠，閉戶方垂帷。","深明戴家禮，頗學毛公詩。","備知輕濟道，高臥陶唐時。","聖主詔天下，賢人不得遺。","公吏奉纁組，安車去茅茨。","君王蒼龍闕，九門十二逵。","羣公朝謁罷，冠劒下丹墀。","野鶴終踉蹌，威鳳徒參差。","或問理人術，但致還山詞。","天書降北闕，賜帛歸東菑。","都門謝親故，行路日逶遲。","孤帆萬里外，淼漫將何之。","江天海陵郡，雲日淮南祠。","杳冥滄洲上，蕩漭無人知。","緯蕭或賣藥，出處安能期。"]', '["少年客淮泗，落魄居下邳。","遨游向燕趙，結客過臨淄。","山东諸侯国，迎送紛交驰。","自爾厭游俠，閉戶方垂帷。","深明戴家禮，頗学毛公诗。","備知轻濟道，高臥陶唐时。","聖主詔天下，賢人不得遺。","公吏奉纁組，安车去茅茨。","君王蒼龙闕，九门十二逵。","羣公朝謁罷，冠劒下丹墀。","野鹤終踉蹌，威鳳徒參差。","或问理人術，但致還山词。","天书降北闕，賜帛归东菑。","都门謝親故，行路日逶遲。","孤帆万里外，淼漫將何之。","江天海陵郡，云日淮南祠。","杳冥滄洲上，蕩漭無人知。","緯蕭或賣藥，出处安能期。"]', '诗', 'shi', '', NULL, '送高適弟耽歸臨淮作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56bec3c2-9c0c-4d40-9750-2e28bdc9a20e', '送綦毋潛落第還鄉', '送綦毋潛落第還乡', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["聖代無隱者，英靈盡來歸。","遂令東山客，不得顧采薇。","既至君門遠，孰云吾道非。","江淮度寒食，京洛縫春衣。","置酒臨長道，同心與我違。","行當浮桂櫂，未幾拂荆扉。","遠樹帶行客，孤村當落暉。","吾謀適不用，勿謂知音稀。"]', '["聖代無隐者，英靈尽来归。","遂令东山客，不得顧采薇。","既至君门远，孰云吾道非。","江淮度寒食，京洛縫春衣。","置酒臨长道，同心與我違。","行當浮桂櫂，未幾拂荆扉。","远樹带行客，孤村當落暉。","吾謀適不用，勿謂知音稀。"]', '诗', 'shi', '', NULL, '送綦毋潛落第還鄉 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b2d6332-f295-45b4-9b7b-fefbea9fa4fa', '送張舍人佐江州同薛璩十韻', '送張舍人佐江州同薛璩十韻', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["束帶趨承明，守官唯謁者。","清晨聽銀蚪，薄暮辭金馬。","受辭未嘗易，當是方知寡。","清範何風流，高文有風雅。","忽佐江上州，當自潯陽下。","逆旅到三湘，長途應百舍。","香爐遠峰出，石鏡澄湖瀉。","董奉杏成林，陶潛菊盈把。","范蠡常好之，廬山我心也。","送君思遠道，欲以數行灑。"]', '["束带趨承明，守官唯謁者。","清晨听銀蚪，薄暮辞金马。","受辞未嘗易，當是方知寡。","清範何风流，高文有风雅。","忽佐江上州，當自潯陽下。","逆旅到三湘，长途應百舍。","香爐远峰出，石镜澄湖瀉。","董奉杏成林，陶潛菊盈把。","范蠡常好之，廬山我心也。","送君思远道，欲以數行灑。"]', '诗', 'shi', '', NULL, '送張舍人佐江州同薛璩十韻 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('331baa90-f69e-48ae-bd7b-42a18a038673', '送韋大夫東京留守', '送韋大夫东京留守', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["人外遺世慮，空端結遐心。","曾是巢許淺，始知堯舜深。","蒼生詎有物，黃屋如喬林。","上德撫神運，沖和穆宸襟。","雲雷康屯難，江海遂飛沈。","天工寄人英，龍衮瞻君臨。","名器苟不假，保釐固其任。","素質貫方領，清景照華簪。","慷慨念王室，從容獻官箴。","雲旗蔽三川，畫角發龍吟。","晨揚天漢聲，夕卷大河陰。","窮人業已寧，逆虜遺之擒。","然後解金組，拂衣東山岑。","給事黃門省，秋光正沈沈。","壯心與身退，老病隨年侵。","君子從相訪，重玄其可尋。"]', '["人外遺世慮，空端結遐心。","曾是巢許淺，始知堯舜深。","蒼生詎有物，黄屋如喬林。","上德撫神運，沖和穆宸襟。","云雷康屯难，江海遂飞沈。","天工寄人英，龙衮瞻君臨。","名器苟不假，保釐固其任。","素質貫方領，清景照华簪。","慷慨念王室，從容獻官箴。","云旗蔽三川，畫角發龙吟。","晨揚天漢声，夕卷大河陰。","窮人業已寧，逆虜遺之擒。","然後解金組，拂衣东山岑。","給事黄门省，秋光正沈沈。","壯心與身退，老病隨年侵。","君子從相訪，重玄其可尋。"]', '诗', 'shi', '', NULL, '送韋大夫東京留守 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('035eeb3b-429d-4d3c-a8e4-ab063632cfa3', '資聖寺送甘二', '資聖寺送甘二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["浮生信如寄，薄宦夫何有。","來往本無歸，別離方此受。","柳色藹春餘，槐陰清夏首。","不覺御溝上，銜悲執桮酒。"]', '["浮生信如寄，薄宦夫何有。","来往本無归，別離方此受。","柳色藹春餘，槐陰清夏首。","不覺御溝上，銜悲執桮酒。"]', '诗', 'shi', '', NULL, '資聖寺送甘二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce428916-fd85-430d-a8dc-1a5d10719a6c', '留別山中溫古上人兄幷示舍弟縉', '留別山中溫古上人兄幷示舍弟縉', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["解薜登天朝，去師偶時哲。","豈惟山中人，兼負松上月。","宿昔同遊止，致身雲霞末。","開軒臨潁陽，臥視飛鳥沒。","好依盤石飯，屢對瀑泉渴。","理齊小狎隱，道勝寧外物。","舍弟官崇高，宗兄此削髪。","荆扉但灑掃，乘閑當過歇。"]', '["解薜登天朝，去師偶时哲。","豈惟山中人，兼負松上月。","宿昔同游止，致身云霞末。","开軒臨潁陽，臥視飞鸟沒。","好依盤石飯，屢对瀑泉渴。","理齊小狎隐，道勝寧外物。","舍弟官崇高，宗兄此削髪。","荆扉但灑掃，乘闲當過歇。"]', '诗', 'shi', '', NULL, '留別山中溫古上人兄幷示舍弟縉 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82838e54-b4dc-4663-91e8-60e0d4f0e9a2', '觀別者', '观別者', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["青青楊柳陌，陌上別離人。","愛子遊燕趙，高堂有老親。","不行無可養，行去百憂新。","切切委兄弟，依依向四鄰。","都門帳飲畢，從此謝親賓。","揮涕逐前侶，含悽動征輪。","車徒望不見，時見起行塵。","吾亦辭家久，看之淚滿巾。"]', '["青青楊柳陌，陌上別離人。","愛子游燕趙，高堂有老親。","不行無可養，行去百憂新。","切切委兄弟，依依向四鄰。","都门帳饮畢，從此謝親賓。","揮涕逐前侶，含悽动征輪。","车徒望不见，时见起行塵。","吾亦辞家久，看之泪满巾。"]', '诗', 'shi', '', NULL, '觀別者 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae1402ee-2613-4d6b-9549-ab7ce6d368f6', '別弟縉後登青龍寺望藍田山', '別弟縉後登青龙寺望藍田山', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["陌上新離別，蒼茫四郊晦。","登高不見君，故山復雲外。","遠樹蔽行人，長天隱秋塞。","心悲宦遊子，何處飛征蓋。"]', '["陌上新離別，蒼茫四郊晦。","登高不见君，故山复云外。","远樹蔽行人，长天隐秋塞。","心悲宦游子，何处飞征蓋。"]', '诗', 'shi', '', NULL, '別弟縉後登青龍寺望藍田山 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9efa6600-aad3-4924-bf55-b9919dfaba62', '別綦毋潛', '別綦毋潛', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["端笏明光宮，歷稔朝雲陛。","詔刊延閣書，高議平津邸。","適意偶輕人，虛心削繁禮。","盛得江左風，彌工建安體。","高張多絕弦，截河有清濟。","嚴冬爽羣木，伊洛方清泚。","渭水冰下流，潼關雪中啓。","荷蓧幾時還，塵纓待君洗。"]', '["端笏明光宮，歷稔朝云陛。","詔刊延閣书，高議平津邸。","適意偶轻人，虛心削繁禮。","盛得江左风，彌工建安體。","高張多絕弦，截河有清濟。","嚴冬爽羣木，伊洛方清泚。","渭水冰下流，潼关雪中啓。","荷蓧幾时還，塵纓待君洗。"]', '诗', 'shi', '', NULL, '別綦毋潛 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28a952f3-fe21-4232-8e5d-a88de7fb638d', '晦日遊大理韋卿城南別業四聲依次用各六韻 一', '晦日游大理韋卿城南別業四声依次用各六韻 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["與世澹無事，自然江海人。","側聞塵外遊，解驂𨋗朱輪。","平野照暄景，上天垂春雲。","張組竟北阜，汎舟過東鄰。","故鄉信高會，牢醴及佳辰。","幸同擊壤樂，心荷堯爲君。"]', '["與世澹無事，自然江海人。","側闻塵外游，解驂𨋗朱輪。","平野照暄景，上天垂春云。","張組竟北阜，汎舟過东鄰。","故乡信高會，牢醴及佳辰。","幸同擊壤乐，心荷堯爲君。"]', '诗', 'shi', '', NULL, '晦日遊大理韋卿城南別業四聲依次用各六韻 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f84ae8c9-b70b-41f0-9be3-e874c0e6c136', '晦日遊大理韋卿城南別業四聲依次用各六韻 二', '晦日游大理韋卿城南別業四声依次用各六韻 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["郊居杜陵下，永日同攜手。","仁里靄川陽，平原見峰首。","園廬鳴春鳩，林薄媚新柳。","上卿始登席，故老前爲壽。","臨當遊南陂，約略執桮酒。","歸歟絀微官，惆悵心自咎。"]', '["郊居杜陵下，永日同携手。","仁里靄川陽，平原见峰首。","园廬鳴春鳩，林薄媚新柳。","上卿始登席，故老前爲壽。","臨當游南陂，約略執桮酒。","归歟絀微官，惆悵心自咎。"]', '诗', 'shi', '', NULL, '晦日遊大理韋卿城南別業四聲依次用各六韻 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16469b22-3690-4c6a-b4f2-7c00e20706e5', '晦日遊大理韋卿城南別業四聲依次用各六韻 三', '晦日游大理韋卿城南別業四声依次用各六韻 三', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["冬中餘雪在，墟上春流駛。","風日暢懷抱，山川多秀氣。","彫胡先晨炊，庖膾亦雲至。","高情浪海嶽，浮生寄天地。","君子外簪纓，埃塵良不啻。","所樂衡門中，陶然忘其貴。"]', '["冬中餘雪在，墟上春流駛。","风日暢懷抱，山川多秀氣。","彫胡先晨炊，庖膾亦云至。","高情浪海嶽，浮生寄天地。","君子外簪纓，埃塵良不啻。","所乐衡门中，陶然忘其貴。"]', '诗', 'shi', '', NULL, '晦日遊大理韋卿城南別業四聲依次用各六韻 三 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdd36dac-cff8-41ed-8cce-409f56c6634c', '晦日遊大理韋卿城南別業四聲依次用各六韻 四', '晦日游大理韋卿城南別業四声依次用各六韻 四', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["高館臨澄陂，曠然蕩心目。","淡蕩動雲天，玲瓏映墟曲。","鵲巢結空林，雉雊響幽谷。","應接無閑暇，徘徊以躑躅。","紆組上春堤，側弁倚喬木。","弦望忽已晦，後期洲應綠。"]', '["高館臨澄陂，曠然蕩心目。","淡蕩动云天，玲瓏映墟曲。","鵲巢結空林，雉雊响幽谷。","應接無闲暇，徘徊以躑躅。","紆組上春堤，側弁倚喬木。","弦望忽已晦，後期洲應綠。"]', '诗', 'shi', '', NULL, '晦日遊大理韋卿城南別業四聲依次用各六韻 四 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e4fe3e-e066-4dfb-97d3-ec55f756c172', '冬日遊覽', '冬日游覽', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["步出城東門，試騁千里目。","青山橫蒼林，赤日團平陸。","渭北走邯鄲，關東出函谷。","秦地萬方會，來朝九州牧。","雞鳴咸陽中，冠蓋相追逐。","丞相過列侯，羣公餞光祿。","相如方老病，獨歸茂陵宿。"]', '["步出城东门，試騁千里目。","青山橫蒼林，赤日團平陸。","渭北走邯鄲，关东出函谷。","秦地万方會，来朝九州牧。","雞鳴咸陽中，冠蓋相追逐。","丞相過列侯，羣公餞光祿。","相如方老病，独归茂陵宿。"]', '诗', 'shi', '', NULL, '冬日遊覽 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0ba8b57-e9a2-4df2-8aa4-30c4dca0420c', '華嶽', '华嶽', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["西嶽出浮雲，積雪在太清。","連天凝黛色，百里遙青冥。","白日爲之寒，森沈華陰城。","昔聞乾坤閉，造化生巨靈。","右足踏方止，左手推削成。","天地忽開拆，大河注東溟。","遂爲西峙嶽，雄雄鎮秦京。","大君包覆載，至德被羣生。","上帝佇昭告，金天思奉迎。","人祇望幸久，何獨禪云亭。"]', '["西嶽出浮云，積雪在太清。","連天凝黛色，百里遙青冥。","白日爲之寒，森沈华陰城。","昔闻乾坤閉，造化生巨靈。","右足踏方止，左手推削成。","天地忽开拆，大河注东溟。","遂爲西峙嶽，雄雄鎮秦京。","大君包覆載，至德被羣生。","上帝佇昭告，金天思奉迎。","人祇望幸久，何独禪云亭。"]', '诗', 'shi', '', NULL, '華嶽 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1640f3a-9511-434e-9ce2-9418275a67e6', '同盧拾遺過韋給事東山別業二十韻給事首春休沐維已陪遊及乎是行亦預聞命會無車馬不果斯諾', '同盧拾遺過韋給事东山別業二十韻給事首春休沐維已陪游及乎是行亦預闻命會無车马不果斯諾', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["托身侍雲陛，昧旦趨華軒。","遂陪鵷鴻侶，霄漢同飛翻。","君子垂惠顧，期我於田園。","側聞景龍際，親降南面尊。","萬乘駐山外，順風祈一言。","高陽多夔龍，荆山積璵璠。","盛德啓前烈，大賢鍾後昆。","侍郎文昌宮，給事東掖垣。","謁帝俱來下，冠蓋盈丘樊。","閨風首邦族，庭訓延鄉村。","采地包山河，樹井竟川原。","巖端回綺檻，谷口開朱門。","階下羣峰首，雲中瀑水源。","鳴玉滿春山，列筵先朝暾。","會舞何颯沓，擊鐘彌朝昏。","是時陽和節，清晝猶未暄。","藹藹樹色深，嚶嚶鳥聲繁。","顧己負宿諾，延頸慙芳蓀。","蹇步守窮巷，高駕難攀援。","素是獨往客，脫冠情彌敦。"]', '["托身侍云陛，昧旦趨华軒。","遂陪鵷鴻侶，霄漢同飞翻。","君子垂惠顧，期我於田园。","側闻景龙際，親降南面尊。","万乘駐山外，順风祈一言。","高陽多夔龙，荆山積璵璠。","盛德啓前烈，大賢鍾後昆。","侍郎文昌宮，給事东掖垣。","謁帝俱来下，冠蓋盈丘樊。","閨风首邦族，庭訓延乡村。","采地包山河，樹井竟川原。","巖端回綺檻，谷口开朱门。","階下羣峰首，云中瀑水源。","鳴玉满春山，列筵先朝暾。","會舞何颯沓，擊鐘彌朝昏。","是时陽和節，清晝猶未暄。","藹藹樹色深，嚶嚶鸟声繁。","顧己負宿諾，延頸慙芳蓀。","蹇步守窮巷，高駕难攀援。","素是独往客，脫冠情彌敦。"]', '诗', 'shi', '', NULL, '同盧拾遺過韋給事東山別業二十韻給事首春休沐維已陪遊及乎是行亦預聞命會無車馬不果斯諾 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c82ac88-be37-4052-9475-e18bfea0d175', '藍田山石門精舍', '藍田山石门精舍', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["落日山水好，漾舟信歸風。","探奇不覺遠，因以緣源窮。","遙愛雲木秀，初疑路不同。","安知清流轉，偶與前山通。","捨舟理輕策，果然愜所適。","老僧四五人，逍遙蔭松栢。","朝梵林未曙，夜禪山更寂。","道心及牧童，世事問樵客。","暝宿長林下，焚香臥瑤席。","澗芳襲人衣，山月暎石壁。","再尋畏迷誤，明發更登歷。","笑謝桃源人，花紅復來覿。"]', '["落日山水好，漾舟信归风。","探奇不覺远，因以緣源窮。","遙愛云木秀，初疑路不同。","安知清流轉，偶與前山通。","捨舟理轻策，果然愜所適。","老僧四五人，逍遙蔭松栢。","朝梵林未曙，夜禪山更寂。","道心及牧童，世事问樵客。","暝宿长林下，焚香臥瑤席。","澗芳襲人衣，山月暎石壁。","再尋畏迷誤，明發更登歷。","笑謝桃源人，花紅复来覿。"]', '诗', 'shi', '', NULL, '藍田山石門精舍 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0576d39-c4ac-4608-a4e2-249b6c31fd1d', '青谿', '青谿', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["言入黃花川，每逐青谿水。","隨山將萬轉，趣途無百里。","聲喧亂石中，色靜深松裏。","漾漾汎菱荇，澄澄映葭葦。","我心素已閑，清川澹如此。","請留盤石上，垂釣將已矣。"]', '["言入黄花川，每逐青谿水。","隨山將万轉，趣途無百里。","声喧亂石中，色静深松裏。","漾漾汎菱荇，澄澄映葭葦。","我心素已闲，清川澹如此。","請留盤石上，垂釣將已矣。"]', '诗', 'shi', '', NULL, '青谿 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0383c43-fecf-4c6a-b3ed-23b157e237f5', '崔濮陽兄季重前山興', '崔濮陽兄季重前山兴', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["秋色有佳興，況君池上閑。","悠悠西林下，自識門前山。","千里橫黛色，數峰出雲間。","嵯峨對秦國，合沓藏荆關。","殘雨斜日照，夕嵐飛鳥還。","故人今尚爾，歎息此頹顏。"]', '["秋色有佳兴，況君池上闲。","悠悠西林下，自識门前山。","千里橫黛色，數峰出云间。","嵯峨对秦国，合沓藏荆关。","殘雨斜日照，夕嵐飞鸟還。","故人今尚爾，歎息此頹顏。"]', '诗', 'shi', '', NULL, '崔濮陽兄季重前山興 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcb17a74-9877-4337-9b01-b0fbd86a4f60', '李處士山居', '李处士山居', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["君子盈天階，小人甘自免。","方隨鍊金客，林上家絕巘。","背嶺花未開，入雲樹深淺。","清晝猶自眠，山鳥時一囀。"]', '["君子盈天階，小人甘自免。","方隨鍊金客，林上家絕巘。","背嶺花未开，入云樹深淺。","清晝猶自眠，山鸟时一囀。"]', '诗', 'shi', '', NULL, '李處士山居 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e298db89-5cd0-4349-97ff-2f3be4160d80', '丁宇田家有贈', '丁宇田家有贈', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["君心尚棲隱，久欲傍歸路。","在朝每爲言，解印果成趣。","晨雞鳴鄰里，羣動從所務。","農夫行餉田，閨妾起縫素。","開軒御衣服，散帙理章句。","時吟招隱詩，或製閑居賦。","新晴望郊郭，日暎桑榆暮。","陰晝小苑城，微明渭川樹。","揆予宅閭井，幽賞何由屢。","道存終不忘，迹異難相遇。","此時惜離別，再來芳菲度。"]', '["君心尚棲隐，久欲傍归路。","在朝每爲言，解印果成趣。","晨雞鳴鄰里，羣动從所務。","農夫行餉田，閨妾起縫素。","开軒御衣服，散帙理章句。","时吟招隐诗，或製闲居賦。","新晴望郊郭，日暎桑榆暮。","陰晝小苑城，微明渭川樹。","揆予宅閭井，幽賞何由屢。","道存終不忘，迹異难相遇。","此时惜離別，再来芳菲度。"]', '诗', 'shi', '', NULL, '丁宇田家有贈 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('204e287b-8194-4c2d-808b-11cc260412ae', '渭川田家', '渭川田家', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["斜陽照墟落，窮巷牛羊歸。","野老念牧童，倚杖候荆扉。","雉雊麥苗秀，蠶眠桑葉稀。","田夫荷鋤至，相見語依依。","即此羨閑逸，悵然吟式微。"]', '["斜陽照墟落，窮巷牛羊归。","野老念牧童，倚杖候荆扉。","雉雊麦苗秀，蠶眠桑葉稀。","田夫荷鋤至，相见語依依。","即此羨闲逸，悵然吟式微。"]', '诗', 'shi', '', NULL, '渭川田家 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8781d18-2288-48aa-9217-75487f4f75aa', '春中田園作', '春中田园作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["屋上春鳩鳴，村邊杏花白。","持斧伐遠揚，荷鋤覘泉脈。","歸燕識故巢，舊人看新曆。","臨觴忽不御，惆悵遠行客。"]', '["屋上春鳩鳴，村邊杏花白。","持斧伐远揚，荷鋤覘泉脈。","归燕識故巢，旧人看新曆。","臨觴忽不御，惆悵远行客。"]', '诗', 'shi', '', NULL, '春中田園作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97fb7180-ab6c-4407-8b2e-7532ea276979', '過李楫宅', '過李楫宅', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["閑門秋草色，終日無車馬。","客來深巷中，犬吠寒林下。","散髪時未簪，道書行尚把。","與我同心人，樂道安貧者。","一罷宜城酌，還歸洛陽社。"]', '["闲门秋草色，終日無车马。","客来深巷中，犬吠寒林下。","散髪时未簪，道书行尚把。","與我同心人，乐道安貧者。","一罷宜城酌，還归洛陽社。"]', '诗', 'shi', '', NULL, '過李楫宅 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65cea96b-411f-4bc8-85aa-9febbeaa4d2c', '韋侍郎山居', '韋侍郎山居', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["幸忝君子顧，遂陪塵外蹤。","閑花滿巖谷，瀑水映杉松。","啼鳥忽臨澗，歸雲時抱峰。","良遊盛簪紱，繼跡多夔龍。","詎枉青門道，胡聞長樂鐘。","清晨去朝謁，車馬何從容。"]', '["幸忝君子顧，遂陪塵外蹤。","闲花满巖谷，瀑水映杉松。","啼鸟忽臨澗，归云时抱峰。","良游盛簪紱，繼跡多夔龙。","詎枉青门道，胡闻长乐鐘。","清晨去朝謁，车马何從容。"]', '诗', 'shi', '', NULL, '韋侍郎山居 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cf746aa-75cb-4436-9674-9c3fada754fe', '飯覆釜山僧', '飯覆釜山僧', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["晚知清淨理，日與人羣疎。","將候遠山僧，先期埽弊廬。","果從雲峰裏，顧我蓬蒿居。","藉草飯松屑，焚香看道書。","然燈晝欲盡，鳴磬夜方初。","一悟寂爲樂，此日閑有餘。","思歸何必深，身世猶空虛。"]', '["晚知清淨理，日與人羣疎。","將候远山僧，先期埽弊廬。","果從云峰裏，顧我蓬蒿居。","藉草飯松屑，焚香看道书。","然灯晝欲尽，鳴磬夜方初。","一悟寂爲乐，此日闲有餘。","思归何必深，身世猶空虛。"]', '诗', 'shi', '', NULL, '飯覆釜山僧 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6619574-2918-45bb-90a4-39c22b9b5636', '謁璿上人', '謁璿上人', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["少年不足言，識道年已長。","事往安可悔，餘生幸能養。","誓從斷臂血，不復嬰世網。","浮名寄纓珮，空性無羈鞅。","夙承大導師，焚香此瞻仰。","頹然居一室，覆載紛萬象。","高柳早鸎啼，長廊春雨響。","牀下阮家屐，窗前筇竹杖。","方將見身雲，陋彼示天壤。","一心在法要，願以無生獎。"]', '["少年不足言，識道年已长。","事往安可悔，餘生幸能養。","誓從斷臂血，不复嬰世網。","浮名寄纓珮，空性無羈鞅。","夙承大導師，焚香此瞻仰。","頹然居一室，覆載紛万象。","高柳早鸎啼，长廊春雨响。","牀下阮家屐，窗前筇竹杖。","方將见身云，陋彼示天壤。","一心在法要，願以無生獎。"]', '诗', 'shi', '', NULL, '謁璿上人 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d50ed5f-0e9d-48db-b114-589a3012f4c8', '瓜園詩', '瓜园诗', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["余適欲鋤瓜，倚鋤聽叩門。","鳴騶導驄馬，常從夾朱軒。","窮巷正傳呼，故人儻相存。","攜手追涼風，放心望乾坤。","藹藹帝王州，宮觀一何繁。","林端出綺道，殿頂搖華幡。","素懷在青山，若值白雲屯。","回風城西雨，返景原上村。","前酌盈尊酒，往往聞清言。","黃鸝囀深木，朱槿照中園。","猶羨松下客，石上聞清猿。"]', '["余適欲鋤瓜，倚鋤听叩门。","鳴騶導驄马，常從夾朱軒。","窮巷正傳呼，故人儻相存。","携手追涼风，放心望乾坤。","藹藹帝王州，宮观一何繁。","林端出綺道，殿頂搖华幡。","素懷在青山，若值白云屯。","回风城西雨，返景原上村。","前酌盈尊酒，往往闻清言。","黄鸝囀深木，朱槿照中园。","猶羨松下客，石上闻清猿。"]', '诗', 'shi', '', NULL, '瓜園詩 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89676d14-1739-4aac-9641-c214f4d3aeb8', '自大散以往深林密竹磴道盤曲四五十里至黃牛嶺見黃花川', '自大散以往深林密竹磴道盤曲四五十里至黄牛嶺见黄花川', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["危徑幾萬轉，數里將三休。","回環見徒侶，隱暎隔林丘。","颯颯松上雨，潺潺石中流。","靜言深谿裏，長嘯高山頭。","望見南山陽，白露靄悠悠。","青臯麗已淨，綠樹鬱如浮。","曾是厭蒙密，曠然銷人憂。"]', '["危徑幾万轉，數里將三休。","回环见徒侶，隐暎隔林丘。","颯颯松上雨，潺潺石中流。","静言深谿裏，长嘯高山头。","望见南山陽，白露靄悠悠。","青臯丽已淨，綠樹鬱如浮。","曾是厭蒙密，曠然銷人憂。"]', '诗', 'shi', '', NULL, '自大散以往深林密竹磴道盤曲四五十里至黃牛嶺見黃花川 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beb41d16-0eee-4916-9f08-c08877959ea3', '新晴野望', '新晴野望', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["新晴原野曠，極目無氛垢。","郭門臨渡頭，村樹連谿口。","白水明田外，碧峰出山後。","農月無閑人，傾家事南畝。"]', '["新晴原野曠，極目無氛垢。","郭门臨渡头，村樹連谿口。","白水明田外，碧峰出山後。","農月無闲人，傾家事南畝。"]', '诗', 'shi', '', NULL, '新晴野望 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04ef8f76-9308-42c0-913a-b83cad843362', '宿鄭州', '宿鄭州', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["朝與周人辭，暮投鄭人宿。","他鄉絕儔侶，孤客親僮僕。","宛洛望不見，秋霖晦平陸。","田父草際歸，村童雨中牧。","主人東臯上，時稼遶茅屋。","蟲思機杼悲，雀喧禾黍熟。","明當渡京水，昨晚猶金谷。","此去欲何言，窮邊狥微祿。"]', '["朝與周人辞，暮投鄭人宿。","他乡絕儔侶，孤客親僮僕。","宛洛望不见，秋霖晦平陸。","田父草際归，村童雨中牧。","主人东臯上，时稼遶茅屋。","蟲思機杼悲，雀喧禾黍熟。","明當渡京水，昨晚猶金谷。","此去欲何言，窮邊狥微祿。"]', '诗', 'shi', '', NULL, '宿鄭州 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df75cf4d-cacd-424a-b043-ebf95cb60639', '早入滎陽界', '早入滎陽界', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["汎舟入滎澤，茲邑乃雄藩。","河曲閭閻隘，川中煙火繁。","因人見風俗，入境聞方言。","秋野田疇盛，朝光市井喧。","漁商波上客，雞犬岸旁村。","前路白雲外，孤帆安可論。"]', '["汎舟入滎澤，茲邑乃雄藩。","河曲閭閻隘，川中煙火繁。","因人见风俗，入境闻方言。","秋野田疇盛，朝光市井喧。","漁商波上客，雞犬岸旁村。","前路白云外，孤帆安可論。"]', '诗', 'shi', '', NULL, '早入滎陽界 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d72cee03-01b5-4d70-ab10-19cbe46761f0', '渡河到清河作', '渡河到清河作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["汎舟大河裏，積水窮天涯。","天波忽開拆，郡邑千萬家。","行復見城市，宛然有桑麻。","回瞻舊鄉國，淼漫連雲霞。"]', '["汎舟大河裏，積水窮天涯。","天波忽开拆，郡邑千万家。","行复见城市，宛然有桑麻。","回瞻旧乡国，淼漫連云霞。"]', '诗', 'shi', '', NULL, '渡河到清河作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d2bb332-a03f-48b2-a067-cefc5ad927e2', '苦熱', '苦熱', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["赤日滿天地，火雲成山嶽。","草木盡焦卷，川澤皆竭涸。","輕紈覺衣重，密樹苦陰薄。","莞簟不可近，絺綌再三濯。","思出宇宙外，曠然在寥廓。","長風萬里來，江海蕩煩濁。","却顧身爲患，始知心未覺。","忽入甘露門，宛然清涼樂。"]', '["赤日满天地，火云成山嶽。","草木尽焦卷，川澤皆竭涸。","轻紈覺衣重，密樹苦陰薄。","莞簟不可近，絺綌再三濯。","思出宇宙外，曠然在寥廓。","长风万里来，江海蕩煩濁。","却顧身爲患，始知心未覺。","忽入甘露门，宛然清涼乐。"]', '诗', 'shi', '', NULL, '苦熱 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ba4b85f-3539-42c6-8cd7-c054d79b9331', '納涼', '納涼', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["喬木萬餘株，清流貫其中。","前臨大川口，豁達來長風。","漣漪涵白沙，素鮪如遊空。","偃臥盤石上，翻濤沃微躬。","漱流復濯足，前對釣魚翁。","貪餌凡幾許，徒思蓮葉東。"]', '["喬木万餘株，清流貫其中。","前臨大川口，豁達来长风。","漣漪涵白沙，素鮪如游空。","偃臥盤石上，翻濤沃微躬。","漱流复濯足，前对釣鱼翁。","貪餌凡幾許，徒思蓮葉东。"]', '诗', 'shi', '', NULL, '納涼 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d6f83e9-8232-4db1-903e-f9e619df5ecb', '西施詠', '西施詠', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["豔色天下重，西施寧久微。","朝仍越溪女，暮作吳宮妃。","賤日豈殊衆，貴來方悟稀。","邀人傅香粉，不自著羅衣。","君寵益嬌態，君憐無是非。","當時浣紗伴，莫得同車歸。","持謝鄰家子，效顰安可希。"]', '["豔色天下重，西施寧久微。","朝仍越溪女，暮作吳宮妃。","賤日豈殊衆，貴来方悟稀。","邀人傅香粉，不自著羅衣。","君寵益嬌態，君怜無是非。","當时浣紗伴，莫得同车归。","持謝鄰家子，效顰安可希。"]', '诗', 'shi', '', NULL, '西施詠 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90da06c8-4252-424a-89f3-f2e6c232e455', '李陵詠', '李陵詠', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["漢家李將軍，三代將門子。","結髮有奇策，少年成壯士。","長驅塞上兒，深入單于壘。","旌旗列相向，簫鼓悲何已。","日暮沙漠陲，戰聲煙塵裏。","將令驕虜滅，豈獨名王侍。","既失大軍援，遂嬰穹廬恥。","少小蒙漢恩，何堪坐思此。","深衷欲有報，投軀未能死。","引領望子卿，非君誰相理。"]', '["漢家李將軍，三代將门子。","結髮有奇策，少年成壯士。","长驱塞上兒，深入單于壘。","旌旗列相向，簫鼓悲何已。","日暮沙漠陲，戰声煙塵裏。","將令驕虜滅，豈独名王侍。","既失大軍援，遂嬰穹廬恥。","少小蒙漢恩，何堪坐思此。","深衷欲有報，投軀未能死。","引領望子卿，非君誰相理。"]', '诗', 'shi', '', NULL, '李陵詠 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0f00c03-fb54-408b-b62b-a11cc62461f2', '濟上四賢詠 崔錄事', '濟上四賢詠 崔錄事', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["解印歸田里，賢哉此丈夫。","少年曾任俠，晚節更爲儒。","遯跡東山下，因家滄海隅。","已聞能狎鳥，余欲共乘桴。"]', '["解印归田里，賢哉此丈夫。","少年曾任俠，晚節更爲儒。","遯跡东山下，因家滄海隅。","已闻能狎鸟，余欲共乘桴。"]', '诗', 'shi', '', NULL, '濟上四賢詠 崔錄事 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce3ddd83-957f-45f5-8aab-8a64a9ec1972', '濟上四賢詠 成文學', '濟上四賢詠 成文学', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["寶劒千金裝，登君白玉堂。","身爲平原客，家有邯鄲娼。","使氣公卿坐，論心遊俠場。","中年不得意，謝病客遊梁。"]', '["寶劒千金裝，登君白玉堂。","身爲平原客，家有邯鄲娼。","使氣公卿坐，論心游俠場。","中年不得意，謝病客游梁。"]', '诗', 'shi', '', NULL, '濟上四賢詠 成文學 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00505454-90e0-4119-afa0-6771bedfe80f', '濟上四賢詠 鄭霍二山人', '濟上四賢詠 鄭霍二山人', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["翩翩繁華子，多出金張門。","幸有先人業，早蒙明主恩。","童年且未學，肉食騖華軒。","豈乏中林士，無人薦至尊。","鄭公老泉石，霍子安丘樊。","賣藥不二價，著書盈萬言。","息陰無惡木，飲水必清源。","吾賤不及議，斯人竟誰論。"]', '["翩翩繁华子，多出金張门。","幸有先人業，早蒙明主恩。","童年且未学，肉食騖华軒。","豈乏中林士，無人薦至尊。","鄭公老泉石，霍子安丘樊。","賣藥不二價，著书盈万言。","息陰無惡木，饮水必清源。","吾賤不及議，斯人竟誰論。"]', '诗', 'shi', '', NULL, '濟上四賢詠 鄭霍二山人 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d05b6e8-b232-40e7-a66d-41d8980f00d5', '過太乙觀賈生房', '過太乙观賈生房', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["昔余棲遯日，之子煙霞鄰。","共攜松葉酒，俱篸竹皮巾。","攀林遍巖洞，采藥無冬春。","謬以道門子，徵爲驂御臣。","常恐丹液就，先我紫陽賓。","夭促萬塗盡，哀傷百慮新。","跡峻不容俗，才多反累真。","泣對雙泉水，還山無主人。"]', '["昔余棲遯日，之子煙霞鄰。","共携松葉酒，俱篸竹皮巾。","攀林遍巖洞，采藥無冬春。","謬以道门子，徵爲驂御臣。","常恐丹液就，先我紫陽賓。","夭促万塗尽，哀傷百慮新。","跡峻不容俗，才多反累真。","泣对雙泉水，還山無主人。"]', '诗', 'shi', '', NULL, '過太乙觀賈生房 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5233e44e-9520-4bf7-aaca-3b3a74dfe81e', '燕子龕禪師', '燕子龕禪師', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["山中燕子龕，路劇羊腸惡。","裂地競盤屈，插天多峭崿。","瀑泉吼而噴，怪石看欲落。","伯禹訪未知，五丁愁不鑿。","上人無生緣，生長居紫閣。","六時自搥磬，一飲常帶索。","種田燒白雲，斫漆響丹壑。","行隨拾栗猿，歸對巢松鶴。","時許山神請，偶逢洞仙博。","救世多慈悲，即心無行作。","周商倦積阻，蜀物多淹泊。","巖腹乍旁穿，澗脣時外拓。","橋因倒樹架，柵值垂藤縛。","鳥道悉已平，龍宮爲之涸。","跳波誰揭厲，絕壁免捫摸。","山木日陰陰，結跏歸舊林。","一向石門裏，任君春草深。"]', '["山中燕子龕，路劇羊腸惡。","裂地競盤屈，插天多峭崿。","瀑泉吼而噴，怪石看欲落。","伯禹訪未知，五丁愁不鑿。","上人無生緣，生长居紫閣。","六时自搥磬，一饮常带索。","種田燒白云，斫漆响丹壑。","行隨拾栗猿，归对巢松鹤。","时許山神請，偶逢洞仙博。","救世多慈悲，即心無行作。","周商倦積阻，蜀物多淹泊。","巖腹乍旁穿，澗脣时外拓。","橋因倒樹架，柵值垂藤縛。","鸟道悉已平，龙宮爲之涸。","跳波誰揭厲，絕壁免捫摸。","山木日陰陰，結跏归旧林。","一向石门裏，任君春草深。"]', '诗', 'shi', '', NULL, '燕子龕禪師 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5c07374-f4da-464b-9ada-768ab54a26ca', '羽林騎閨人', '羽林騎閨人', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["秋月臨高城，城中管弦思。","離人堂上愁，稚子階前戲。","出門復暎戶，望望青絲騎。","行人過欲盡，狂夫終不至。","左右寂無言，相看共垂淚。"]', '["秋月臨高城，城中管弦思。","離人堂上愁，稚子階前戲。","出门复暎戶，望望青絲騎。","行人過欲尽，狂夫終不至。","左右寂無言，相看共垂泪。"]', '诗', 'shi', '', NULL, '羽林騎閨人 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb64acc5-84e1-47a7-ab81-7be5a12ad200', '偶然作六首 一', '偶然作六首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["楚國有狂夫，茫然無心想。","散髪不冠帶，行歌南陌上。","孔丘與之言，仁義莫能獎。","未嘗肯問天，何事須擊壤。","復笑采薇人，胡爲乃長往。"]', '["楚国有狂夫，茫然無心想。","散髪不冠带，行歌南陌上。","孔丘與之言，仁義莫能獎。","未嘗肯问天，何事須擊壤。","复笑采薇人，胡爲乃长往。"]', '诗', 'shi', '', NULL, '偶然作六首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d960d46-327f-477c-a222-a211a6903034', '偶然作六首 二', '偶然作六首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["田舍有老翁，垂白衡門裏。","有時農事閑，斗酒呼鄰里。","喧聒茅簷下，或坐或復起。","短褐不爲薄，園葵固足美。","動則長子孫，不曾向城市。","五帝與三王，古來稱天子。","干戈將揖讓，畢竟何者是。","得意苟爲樂，野田安足鄙。","且當放懷去，行行沒餘齒。"]', '["田舍有老翁，垂白衡门裏。","有时農事闲，斗酒呼鄰里。","喧聒茅簷下，或坐或复起。","短褐不爲薄，园葵固足美。","动則长子孫，不曾向城市。","五帝與三王，古来稱天子。","干戈將揖讓，畢竟何者是。","得意苟爲乐，野田安足鄙。","且當放懷去，行行沒餘齒。"]', '诗', 'shi', '', NULL, '偶然作六首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('979dd74e-b664-4042-9e94-8d2e9d92e2bd', '偶然作六首 三', '偶然作六首 三', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["日夕見太行，沈吟未能去。","問君何以然，世網嬰我故。","小妹日成長，兄弟未有娶。","家貧祿既薄，儲蓄非有素。","幾回欲奮飛，踟躕復相顧。","孫登長嘯臺，松竹有遺處。","相去詎幾許，故人在中路。","愛染日已薄，禪寂日已固。","忽乎吾將行，寧俟歲云暮。"]', '["日夕见太行，沈吟未能去。","问君何以然，世網嬰我故。","小妹日成长，兄弟未有娶。","家貧祿既薄，儲蓄非有素。","幾回欲奮飞，踟躕复相顧。","孫登长嘯台，松竹有遺处。","相去詎幾許，故人在中路。","愛染日已薄，禪寂日已固。","忽乎吾將行，寧俟歲云暮。"]', '诗', 'shi', '', NULL, '偶然作六首 三 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1841dee-c465-42ed-83ec-a1e6c2ca8113', '偶然作六首 四', '偶然作六首 四', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["陶潛任天真，其性頗躭酒。","自從棄官來，家貧不能有。","九月九日時，菊花空滿手。","中心竊自思，儻有人送否。","白衣攜壺觴，果來遺老叟。","且喜得斟酌，安問升與斗。","奮衣野田中，今日嗟無負。","兀傲迷東西，蓑笠不能守。","傾倒強行行，酣歌歸五柳。","生事不曾問，肯媿家中婦。"]', '["陶潛任天真，其性頗躭酒。","自從棄官来，家貧不能有。","九月九日时，菊花空满手。","中心竊自思，儻有人送否。","白衣携壺觴，果来遺老叟。","且喜得斟酌，安问升與斗。","奮衣野田中，今日嗟無負。","兀傲迷东西，蓑笠不能守。","傾倒強行行，酣歌归五柳。","生事不曾问，肯媿家中婦。"]', '诗', 'shi', '', NULL, '偶然作六首 四 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4811841a-3063-4975-8f52-1420de15563a', '偶然作六首 五', '偶然作六首 五', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["趙女彈箜篌，復能邯鄲舞。","夫壻輕薄兒，鬬雞事齊主。","黃金買歌笑，用錢不復數。","許史相經過，高門盈四牡。","客舍有儒生，昂藏出鄒魯。","讀書三十年，腰間無尺組。","被服聖人教，一生自窮苦。"]', '["趙女彈箜篌，复能邯鄲舞。","夫壻轻薄兒，鬬雞事齊主。","黄金買歌笑，用錢不复數。","許史相經過，高门盈四牡。","客舍有儒生，昂藏出鄒魯。","读书三十年，腰间無尺組。","被服聖人教，一生自窮苦。"]', '诗', 'shi', '', NULL, '偶然作六首 五 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aad4f966-3ebe-4a5e-8765-ad80069cb851', '偶然作六首 六', '偶然作六首 六', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["老來懶賦詩，惟有老相隨。","宿世謬詞客，前身應畫師。","不能捨餘習，偶被世人知。","名字本皆是，此心還不知。"]', '["老来懶賦诗，惟有老相隨。","宿世謬词客，前身應畫師。","不能捨餘習，偶被世人知。","名字本皆是，此心還不知。"]', '诗', 'shi', '', NULL, '偶然作六首 六 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a99b9221-deac-4bf0-a6fa-31ce258ffcf8', '寓言二首 一', '寓言二首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["朱紱誰家子，無乃金張孫。","驪駒從白馬，出入銅龍門。","問爾何功德，多承明主恩。","鬬雞平樂館，射雉上林園。","曲陌車騎盛，高堂珠翠繁。","奈何軒冕貴，不與布衣言。"]', '["朱紱誰家子，無乃金張孫。","驪駒從白马，出入銅龙门。","问爾何功德，多承明主恩。","鬬雞平乐館，射雉上林园。","曲陌车騎盛，高堂珠翠繁。","奈何軒冕貴，不與布衣言。"]', '诗', 'shi', '', NULL, '寓言二首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1531bb4-4994-4f5b-a0cc-99bc730ef23e', '寓言二首 二', '寓言二首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["君家御溝上，垂柳夾朱門。","列鼎會中貴，鳴珂朝至尊。","生死在八議，窮達由一言。","須識苦寒士，莫矜狐白溫。"]', '["君家御溝上，垂柳夾朱门。","列鼎會中貴，鳴珂朝至尊。","生死在八議，窮達由一言。","須識苦寒士，莫矜狐白溫。"]', '诗', 'shi', '', NULL, '寓言二首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99e91369-92a3-4dcf-900c-e1424e2b8457', '冬夜書懷', '冬夜书懷', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["冬宵寒且永，夜漏宮中發。","草白靄繁霜，木衰澄清月。","麗服暎頹顏，朱燈照華髪。","漢家方尚少，顧影慙朝謁。"]', '["冬宵寒且永，夜漏宮中發。","草白靄繁霜，木衰澄清月。","丽服暎頹顏，朱灯照华髪。","漢家方尚少，顧影慙朝謁。"]', '诗', 'shi', '', NULL, '冬夜書懷 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d119d041-829b-49c0-b8ae-66b2c58375c3', '送康太守', '送康太守', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["城下滄江水，江邊黃鶴樓。","朱闌將粉堞，江水映悠悠。","鐃吹發夏口，使君居上頭。","郭門隱楓岸，候吏趨蘆洲。","何異臨川郡，還勞康樂侯。"]', '["城下滄江水，江邊黄鹤楼。","朱闌將粉堞，江水映悠悠。","鐃吹發夏口，使君居上头。","郭门隐楓岸，候吏趨蘆洲。","何異臨川郡，還勞康乐侯。"]', '诗', 'shi', '', NULL, '送康太守 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee598cce-2501-42b3-8d77-1de2d9b58870', '送權二', '送權二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["高人不可有，清論復何深。","一見如舊識，一言知道心。","明時當薄宦，解薜去中林。","芳草空隱處，白雲餘故岑。","韓侯久攜手，河嶽共幽尋。","悵別千餘里，臨堂鳴素琴。"]', '["高人不可有，清論复何深。","一见如旧識，一言知道心。","明时當薄宦，解薜去中林。","芳草空隐处，白云餘故岑。","韓侯久携手，河嶽共幽尋。","悵別千餘里，臨堂鳴素琴。"]', '诗', 'shi', '', NULL, '送權二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffdfd373-9e00-4759-b90d-f6d8da4a1d86', '休假還舊業便使', '休假還旧業便使', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["謝病始告歸，依依入桑梓。","家人皆竚立，相候衡門裏。","時輩皆長年，成人舊童子。","上堂嘉慶畢，顧與姻親齒。","論舊忽餘悲，目存皆相喜。","田園轉蕪沒，但有寒泉水。","衰柳日蕭條，秋光清邑里。","入門乍如客，休騎非便止。","中飲顧王程，離憂從此始。"]', '["謝病始告归，依依入桑梓。","家人皆竚立，相候衡门裏。","时輩皆长年，成人旧童子。","上堂嘉慶畢，顧與姻親齒。","論旧忽餘悲，目存皆相喜。","田园轉蕪沒，但有寒泉水。","衰柳日蕭條，秋光清邑里。","入门乍如客，休騎非便止。","中饮顧王程，離憂從此始。"]', '诗', 'shi', '', NULL, '休假還舊業便使 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('821e9913-0746-4dc1-a151-28d8e511df86', '歎白髪', '歎白髪', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["我年一何長，鬢髪日已白。","俛仰天地間，能爲幾時客。","惆悵故山雲，俳徊空日夕。","何事與時人，東城復南陌。"]', '["我年一何长，鬢髪日已白。","俛仰天地间，能爲幾时客。","惆悵故山云，俳徊空日夕。","何事與时人，东城复南陌。"]', '诗', 'shi', '', NULL, '歎白髪 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afc6f8c0-c818-411e-828f-1df966913431', '別弟妹二首 一', '別弟妹二首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["兩妹日成長，雙鬟將及人。","已能持寶瑟，自解掩羅巾。","念昔別時小，未知疎與親。","今來始離恨，拭淚方殷勤。"]', '["兩妹日成长，雙鬟將及人。","已能持寶瑟，自解掩羅巾。","念昔別时小，未知疎與親。","今来始離恨，拭泪方殷勤。"]', '诗', 'shi', '', NULL, '別弟妹二首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d35e7dd-79cc-4d70-acda-d1cc9eab8fbf', '別弟妹二首 二', '別弟妹二首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["小弟更孩幼，歸來不相識。","同居雖漸慣，見人猶未覓。","宛作越人語，殊甘水鄉食。","別此最爲難，淚盡有餘憶。"]', '["小弟更孩幼，归来不相識。","同居雖漸慣，见人猶未覓。","宛作越人語，殊甘水乡食。","別此最爲难，泪尽有餘憶。"]', '诗', 'shi', '', NULL, '別弟妹二首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41355750-b4e1-4c5a-8fc6-17f4e8a7049e', '哭殷遙', '哭殷遙', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["人生能幾何，畢竟歸無形。","念君等爲死，萬事傷人情。","慈母未及葬，一女纔十齡。","泱漭寒郊外，蕭條聞哭聲。","浮雲爲蒼茫，飛鳥不能鳴。","行人何寂寞，白日自淒清。","憶昔君在時，問我學無生。","勸君苦不早，令君無所成。","故人各有贈，又不及生平。","負爾非一途，慟哭返柴荆。"]', '["人生能幾何，畢竟归無形。","念君等爲死，万事傷人情。","慈母未及葬，一女纔十齡。","泱漭寒郊外，蕭條闻哭声。","浮云爲蒼茫，飞鸟不能鳴。","行人何寂寞，白日自淒清。","憶昔君在时，问我学無生。","勸君苦不早，令君無所成。","故人各有贈，又不及生平。","負爾非一途，慟哭返柴荆。"]', '诗', 'shi', '', NULL, '哭殷遙 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44b2376c-e68d-4b0d-a57a-564d868445cc', '故南陽夫人樊氏挽歌', '故南陽夫人樊氏挽歌', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["石窌恩榮重，金吾車騎盛。","將朝每贈言，入室還相敬。","疊鼓秋城動，懸旌寒日映。","不言長不歸，環珮猶將聽。"]', '["石窌恩榮重，金吾车騎盛。","將朝每贈言，入室還相敬。","叠鼓秋城动，懸旌寒日映。","不言长不归，环珮猶將听。"]', '诗', 'shi', '', NULL, '故南陽夫人樊氏挽歌 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc7cd11c-5e72-4620-a4ad-1f2aba14b7eb', '夷門歌', '夷门歌', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["七雄雄雌猶未分，攻城殺將何紛紛。","秦兵益圍邯鄲急，魏王不救平原君。","公子爲嬴停駟馬，執轡愈恭意愈下。","亥爲屠肆鼓刀人，嬴乃夷門抱關者。","非但慷慨獻良謀，意氣兼將身命酬。","向風刎頸送公子，七十老翁何所求。"]', '["七雄雄雌猶未分，攻城殺將何紛紛。","秦兵益圍邯鄲急，魏王不救平原君。","公子爲嬴停駟马，執轡愈恭意愈下。","亥爲屠肆鼓刀人，嬴乃夷门抱关者。","非但慷慨獻良謀，意氣兼將身命酬。","向风刎頸送公子，七十老翁何所求。"]', '诗', 'shi', '', NULL, '夷門歌 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9afcb446-145c-44aa-b9e6-d0c9adce4fac', '隴頭吟', '隴头吟', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["長安少年遊俠客，夜上戍樓看太白。","隴頭明月迥臨關，隴上行人夜吹笛。","關西老將不勝愁，駐馬聽之雙淚流。","身經大小百餘戰，麾下偏裨萬戶侯。","蘇武纔爲典屬國，節旄落盡海西頭。"]', '["长安少年游俠客，夜上戍楼看太白。","隴头明月迥臨关，隴上行人夜吹笛。","关西老將不勝愁，駐马听之雙泪流。","身經大小百餘戰，麾下偏裨万戶侯。","蘇武纔爲典屬国，節旄落尽海西头。"]', '诗', 'shi', '', NULL, '隴頭吟 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5d66aff-b6ae-48cc-9160-16b096d4ea49', '老將行', '老將行', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["少年十五二十時，步行奪得胡馬射。","射殺中山白額虎，肯數鄴下黃鬚兒。","一身轉戰三千里，一劒曾當百萬師。","漢兵奮迅如霹靂，虜騎崩騰畏蒺藜。","衞青不敗由天幸，李廣無功緣數奇。","自從棄置便衰朽，世事磋跎成白首。","昔時飛箭無全目，今日垂楊生左肘。","路傍時賣故侯瓜，門前學種先生柳。","蒼茫古木連窮巷，寥落寒山對虛牖。","誓令疏勒出飛泉，不似潁川空使酒。","賀蘭山下陣如雲，羽檄交馳日夕聞。","節使三河募年少，詔書五道出將軍。","試拂鐵衣如雪色，聊持寶劒動星文。","願得燕弓射天將，恥令越甲鳴吳軍。","莫嫌舊日雲中守，猶堪一戰取功勳。"]', '["少年十五二十时，步行奪得胡马射。","射殺中山白額虎，肯數鄴下黄鬚兒。","一身轉戰三千里，一劒曾當百万師。","漢兵奮迅如霹靂，虜騎崩腾畏蒺藜。","衞青不敗由天幸，李廣無功緣數奇。","自從棄置便衰朽，世事磋跎成白首。","昔时飞箭無全目，今日垂楊生左肘。","路傍时賣故侯瓜，门前学種先生柳。","蒼茫古木連窮巷，寥落寒山对虛牖。","誓令疏勒出飞泉，不似潁川空使酒。","賀蘭山下陣如云，羽檄交驰日夕闻。","節使三河募年少，詔书五道出將軍。","試拂鐵衣如雪色，聊持寶劒动星文。","願得燕弓射天將，恥令越甲鳴吳軍。","莫嫌旧日云中守，猶堪一戰取功勳。"]', '诗', 'shi', '', NULL, '老將行 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26836213-01c0-4a22-8d81-dc8a0e0793b2', '燕支行', '燕支行', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["漢家天將才且雄，來時謁帝明光宮。","萬乘親推雙闕下，千官出餞五陵東。","誓辭甲第金門裏，身作長城玉塞中。","衞霍才堪一騎將，朝廷不數貳師功。","趙魏燕韓多勁卒，關西俠少何咆勃。","報讐只是聞嘗膽，飲酒不曾妨刮骨。","畫戟雕戈白日寒，連旗大斾黃塵沒。","疊鼓遙翻瀚海波，鳴笳亂動天山月。","麒麟錦帶佩吳鉤，颯沓青驪躍紫騮。","拔劒已斷天驕臂，歸鞍共飲月支頭。","漢兵大呼一當百，虜騎相看哭且愁。","教戰雖令赴湯火，終知上將先伐謀。"]', '["漢家天將才且雄，来时謁帝明光宮。","万乘親推雙闕下，千官出餞五陵东。","誓辞甲第金门裏，身作长城玉塞中。","衞霍才堪一騎將，朝廷不數貳師功。","趙魏燕韓多勁卒，关西俠少何咆勃。","報讐只是闻嘗膽，饮酒不曾妨刮骨。","畫戟雕戈白日寒，連旗大斾黄塵沒。","叠鼓遙翻瀚海波，鳴笳亂动天山月。","麒麟錦带佩吳鉤，颯沓青驪躍紫騮。","拔劒已斷天驕臂，归鞍共饮月支头。","漢兵大呼一當百，虜騎相看哭且愁。","教戰雖令赴湯火，終知上將先伐謀。"]', '诗', 'shi', '', NULL, '燕支行 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b847cf5-16b1-449d-a436-e5995c6433c4', '桃源行', '桃源行', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["漁舟逐水愛山春，兩岸桃花夾去津。","坐看紅樹不知遠，行盡青溪不見人。","山口潛行始隈隩，山開曠望旋平陸。","遙看一處攢雲樹，近入千家散花竹。","樵客初傳漢姓名，居人未改秦衣服。","居人共住武陵源，還從物外起田園。","月明松下房櫳靜，日出雲中雞犬喧。","驚聞俗客爭來集，競引還家問都邑。","平明閭巷埽花開，薄暮漁樵乘水入。","初因避地去人間，及至成仙遂不還。","峽裏誰知有人事，世中遙望空雲山。","不疑靈境難聞見，塵心未盡思鄉縣。","出洞無論隔山水，辭家終擬長游衍。","自謂經過舊不迷，安知峰壑今來變。","當時只記入山深，青溪幾曲到雲林。","春來遍是桃花水，不辨仙源何處尋。"]', '["漁舟逐水愛山春，兩岸桃花夾去津。","坐看紅樹不知远，行尽青溪不见人。","山口潛行始隈隩，山开曠望旋平陸。","遙看一处攢云樹，近入千家散花竹。","樵客初傳漢姓名，居人未改秦衣服。","居人共住武陵源，還從物外起田园。","月明松下房櫳静，日出云中雞犬喧。","驚闻俗客爭来集，競引還家问都邑。","平明閭巷埽花开，薄暮漁樵乘水入。","初因避地去人间，及至成仙遂不還。","峽裏誰知有人事，世中遙望空云山。","不疑靈境难闻见，塵心未尽思乡縣。","出洞無論隔山水，辞家終擬长游衍。","自謂經過旧不迷，安知峰壑今来变。","當时只記入山深，青溪幾曲到云林。","春来遍是桃花水，不辨仙源何处尋。"]', '诗', 'shi', '', NULL, '桃源行 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4925c861-b0f8-4b2f-923e-9cba2df1323e', '洛陽女兒行', '洛陽女兒行', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["洛陽女兒對門居，纔可容顏十五餘。","良人玉勒乘驄馬，侍女金盤鱠鯉魚。","畫閣朱樓盡相望，紅桃綠柳垂簷向。","羅幃送上七香車，寶扇迎歸九華帳。","狂夫富貴在青春，意氣驕奢劇季倫。","自憐碧玉親教舞，不惜珊瑚持與人。","春窗曙滅九微火，九微片片飛花璅。","戲罷曾無理曲時，妝成秪是薰香坐。","城中相識盡繁華，日夜經過趙李家。","誰憐越女顏如玉，貧賤江頭自浣紗。"]', '["洛陽女兒对门居，纔可容顏十五餘。","良人玉勒乘驄马，侍女金盤鱠鯉鱼。","畫閣朱楼尽相望，紅桃綠柳垂簷向。","羅幃送上七香车，寶扇迎归九华帳。","狂夫富貴在青春，意氣驕奢劇季倫。","自怜碧玉親教舞，不惜珊瑚持與人。","春窗曙滅九微火，九微片片飞花璅。","戲罷曾無理曲时，妝成秪是薰香坐。","城中相識尽繁华，日夜經過趙李家。","誰怜越女顏如玉，貧賤江头自浣紗。"]', '诗', 'shi', '', NULL, '洛陽女兒行 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cccfccae-0f64-4573-91bc-acb8b452b10f', '同崔傅答賢弟', '同崔傅答賢弟', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["洛陽才子姑蘇客，桂苑殊非故鄉陌。","九江楓樹幾回青，一片揚州五湖白。","揚州時有下江兵，蘭陵鎮前吹笛聲。","夜火人歸富春郭，秋風鶴唳石頭城。","周郎陸弟爲儔侶，對舞前溪歌白紵。","曲几書留小史家，草堂棋賭山陰墅。","衣冠若話外臺臣，先數夫君席上珍。","更聞臺閣求三語，遙想風流第一人。"]', '["洛陽才子姑蘇客，桂苑殊非故乡陌。","九江楓樹幾回青，一片揚州五湖白。","揚州时有下江兵，蘭陵鎮前吹笛声。","夜火人归富春郭，秋风鹤唳石头城。","周郎陸弟爲儔侶，对舞前溪歌白紵。","曲几书留小史家，草堂棋賭山陰墅。","衣冠若話外台臣，先數夫君席上珍。","更闻台閣求三語，遙想风流第一人。"]', '诗', 'shi', '', NULL, '同崔傅答賢弟 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14831423-609e-4625-8bac-e9feb8e295a6', '贈吳官', '贈吳官', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["長安客舍熱如煮，無箇茗糜難御暑。","空搖白團其諦苦，欲向縹囊還歸旅。","江鄉鯖鮓不寄來，秦人湯餅那堪許。","不如儂家任挑達，草屩撈蝦富春渚。"]', '["长安客舍熱如煮，無箇茗糜难御暑。","空搖白團其諦苦，欲向縹囊還归旅。","江乡鯖鮓不寄来，秦人湯餅那堪許。","不如儂家任挑達，草屩撈蝦富春渚。"]', '诗', 'shi', '', NULL, '贈吳官 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eff5a666-c3a6-4448-b913-f49e2c83154f', '故人張諲工詩善易卜兼能丹青草隸頃以詩見贈聊獲酬之', '故人張諲工诗善易卜兼能丹青草隸頃以诗见贈聊獲酬之', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["不逐城東遊俠兒，隱囊紗帽坐彈棋。","蜀中夫子時開卦，洛下書生解詠詩。","藥闌花逕衡門裏，時復據梧聊隱几。","屏風誤點惑孫郎，團扇草書輕內史。","故園高枕度三春，永日垂帷絕四鄰。","自想蔡邕今已老，更將書籍使何人。"]', '["不逐城东游俠兒，隐囊紗帽坐彈棋。","蜀中夫子时开卦，洛下书生解詠诗。","藥闌花逕衡门裏，时复據梧聊隐几。","屏风誤点惑孫郎，團扇草书轻內史。","故园高枕度三春，永日垂帷絕四鄰。","自想蔡邕今已老，更將书籍使何人。"]', '诗', 'shi', '', NULL, '故人張諲工詩善易卜兼能丹青草隸頃以詩見贈聊獲酬之 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f232909-cb6c-4da8-afde-d3ff9fcea204', '送崔五太守', '送崔五太守', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["長安廄吏來到門，朱文露網動行軒。","黃花縣西九折坂，玉樹宮南五丈原。","襃斜谷中不容幰，唯有白雲當露冕。","子午山裏杜鵑啼，嘉陵水頭行客飯。","劒門忽斷蜀川開，萬井雙流滿眼來。","霧中遠樹刀州出，天際澄江巴字回。","使君年紀三十餘，少年白皙專城居。","欲持畫省郎官筆，回與臨邛父老書。"]', '["长安廄吏来到门，朱文露網动行軒。","黄花縣西九折坂，玉樹宮南五丈原。","襃斜谷中不容幰，唯有白云當露冕。","子午山裏杜鵑啼，嘉陵水头行客飯。","劒门忽斷蜀川开，万井雙流满眼来。","霧中远樹刀州出，天際澄江巴字回。","使君年紀三十餘，少年白皙專城居。","欲持畫省郎官笔，回與臨邛父老书。"]', '诗', 'shi', '', NULL, '送崔五太守 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5a19b2c-d215-4b3e-8b8c-29d9da7bccce', '寒食城東即事', '寒食城东即事', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["清溪一道穿桃李，演漾綠蒲涵白芷。","溪上人家凡幾家，落花半落東流水。","蹴鞠屢過飛鳥上，鞦韆競出垂楊裏。","少年分日作遨遊，不用清明兼上巳。"]', '["清溪一道穿桃李，演漾綠蒲涵白芷。","溪上人家凡幾家，落花半落东流水。","蹴鞠屢過飞鸟上，鞦韆競出垂楊裏。","少年分日作遨游，不用清明兼上巳。"]', '诗', 'shi', '', NULL, '寒食城東即事 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c1c99a1-8547-4ba2-8042-faf0dd239d45', '不遇詠', '不遇詠', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["北闕獻書寢不報，南山種田時不登。","百人會中身不預，五侯門前心不能。","身投河朔飲君酒，家在茂陵平安否。","且此登山復臨水，莫問春風動楊柳。","今人昨人多自私，我心不說君應知。","濟人然後拂衣去，肯作徒爾一男兒。"]', '["北闕獻书寢不報，南山種田时不登。","百人會中身不預，五侯门前心不能。","身投河朔饮君酒，家在茂陵平安否。","且此登山复臨水，莫问春风动楊柳。","今人昨人多自私，我心不说君應知。","濟人然後拂衣去，肯作徒爾一男兒。"]', '诗', 'shi', '', NULL, '不遇詠 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c1f36cc-dc3f-44a7-ab1c-34f97e057e19', '贈裴迪', '贈裴迪', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["不相見，不相見來久。","日日泉水頭，常憶同攜手。","攜手本同心，復歎忽分襟。","相憶今如此，相思深不深。"]', '["不相见，不相见来久。","日日泉水头，常憶同携手。","携手本同心，复歎忽分襟。","相憶今如此，相思深不深。"]', '诗', 'shi', '', NULL, '贈裴迪 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d7b188a-e9bb-41f3-b7ab-7e070b3e026e', '青雀歌', '青雀歌', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["青雀翅羽短，未能遠食玉山禾。","猶勝黃雀爭上下，唧唧空倉復若何。"]', '["青雀翅羽短，未能远食玉山禾。","猶勝黄雀爭上下，唧唧空倉复若何。"]', '诗', 'shi', '', NULL, '青雀歌 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52c39451-5a14-4c62-a790-0a69d52662e6', '黃雀癡', '黄雀癡', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["黃雀癡，黃雀癡，謂言青鷇是我兒。","一一口銜食，養得成毛衣。","到大啁啾解游颺，各自東西南北飛。","薄暮空巢上，羇雌獨自歸。","鳳凰九雛亦如此，慎莫愁思顦顇損容輝。"]', '["黄雀癡，黄雀癡，謂言青鷇是我兒。","一一口銜食，養得成毛衣。","到大啁啾解游颺，各自东西南北飞。","薄暮空巢上，羇雌独自归。","鳳凰九雛亦如此，慎莫愁思顦顇損容輝。"]', '诗', 'shi', '', NULL, '黃雀癡 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18c9eef7-5cf2-4f88-873a-e46708007e7f', '新秦郡松樹歌', '新秦郡松樹歌', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["青青山上松，數里不見今更逢。","不見君，心相憶，此心向君君應識。","爲君顏色高且閑，亭亭迥出浮雲間。"]', '["青青山上松，數里不见今更逢。","不见君，心相憶，此心向君君應識。","爲君顏色高且闲，亭亭迥出浮云间。"]', '诗', 'shi', '', NULL, '新秦郡松樹歌 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f651e3ed-d3ff-4bbf-aae9-8e914cfe9780', '楡林郡歌', '楡林郡歌', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["山頭松柏林，山下泉聲傷客心。","千里萬里春草色，黃河東流流不息。","黃龍戍上游俠兒，愁逢漢使不相識。"]', '["山头松柏林，山下泉声傷客心。","千里万里春草色，黄河东流流不息。","黄龙戍上游俠兒，愁逢漢使不相識。"]', '诗', 'shi', '', NULL, '楡林郡歌 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ce06de3-1f97-464c-aac1-8dd5653e84f6', '問寇校書雙谿', '问寇校书雙谿', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["君家少室西，爲復少室東。","別來幾日今春風，新買雙谿定何似。"]', '["君家少室西，爲复少室东。","別来幾日今春风，新買雙谿定何似。"]', '诗', 'shi', '', NULL, '問寇校書雙谿 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c14dd5ba-9b76-484a-a6d9-850663f9a90c', '寄崇梵僧', '寄崇梵僧', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["崇梵僧，崇梵僧，秋歸覆釜春不還。","落花啼鳥紛紛亂，澗戶山窗寂寂閑。","峽裏誰知有人事，郡中遙望空雲山。"]', '["崇梵僧，崇梵僧，秋归覆釜春不還。","落花啼鸟紛紛亂，澗戶山窗寂寂闲。","峽裏誰知有人事，郡中遙望空云山。"]', '诗', 'shi', '', NULL, '寄崇梵僧 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb33081b-2ad0-4b9f-9e31-c9940ba378b8', '同比部楊員外十五夜遊有懷靜者季', '同比部楊員外十五夜游有懷静者季', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["承明少休沐，建禮省文書。","夜漏行人息，歸鞍落日餘。","懸知三五夕，萬戶千門闢。","夜出曙翻歸，傾城滿南陌。","陌頭馳騁盡繁華，王孫公子五侯家。","由來月明如白日，共道春燈勝百花。","聊看侍中千寶騎，強識小婦七香車。","香車寶馬共喧闐，箇裏多情俠少年。","競向長楊柳市北，肯過精舍竹林前。","獨有仙郎心寂寞，却將宴坐爲行樂。","儻覺忘懷共往來，幸霑同舍甘藜藿。"]', '["承明少休沐，建禮省文书。","夜漏行人息，归鞍落日餘。","懸知三五夕，万戶千门闢。","夜出曙翻归，傾城满南陌。","陌头驰騁尽繁华，王孫公子五侯家。","由来月明如白日，共道春灯勝百花。","聊看侍中千寶騎，強識小婦七香车。","香车寶马共喧闐，箇裏多情俠少年。","競向长楊柳市北，肯過精舍竹林前。","独有仙郎心寂寞，却將宴坐爲行乐。","儻覺忘懷共往来，幸霑同舍甘藜藿。"]', '诗', 'shi', '', NULL, '同比部楊員外十五夜遊有懷靜者季 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74e84c15-4f58-436b-9640-b673db2df2da', '荅張五弟', '荅張五弟', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["終南有茅屋，前對終南山。","終年無客常閉關，終日無心長自閑。","不妨飲酒復垂釣，君但能來相往還。"]', '["終南有茅屋，前对終南山。","終年無客常閉关，終日無心长自闲。","不妨饮酒复垂釣，君但能来相往還。"]', '诗', 'shi', '', NULL, '荅張五弟 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13c5f0b5-b891-4847-999c-eb566db07ca0', '雪中憶李楫', '雪中憶李楫', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["積雪滿阡陌，故人不可期。","長安千門復萬户，何處躞蹀黄金羈。"]', '["積雪满阡陌，故人不可期。","长安千门复万户，何处躞蹀黄金羈。"]', '诗', 'shi', '', NULL, '雪中憶李楫 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d336b36a-0b88-422b-9a4e-4c695d168574', '送李睢陽', '送李睢陽', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["將置酒，思悲翁。","使君去，出城東。","麥漸漸，雉子斑。","槐陰陰，到潼關。","騎連連，車遲遲。","心中悲，宋又遠。","周間之，南淮夷。","東齊兒，碎碎織練與素絲。","遊人賈客信難持，五穀前熟方可爲。","下車閉閤君當思，天子當殿儼衣裳。","大官尚食陳羽觴，彤庭散綬垂鳴璫。","黃紙詔書出東廂，輕紈疊綺爛生光。","宗室子弟君最賢，分憂當爲百辟先。","布衣一言相爲死，何況聖主恩如天。","鸞聲噦噦魯侯旂，明年上計朝京師。","須憶今日斗酒別，慎勿富貴忘我爲。"]', '["將置酒，思悲翁。","使君去，出城东。","麦漸漸，雉子斑。","槐陰陰，到潼关。","騎連連，车遲遲。","心中悲，宋又远。","周间之，南淮夷。","东齊兒，碎碎织練與素絲。","游人賈客信难持，五穀前熟方可爲。","下车閉閤君當思，天子當殿儼衣裳。","大官尚食陳羽觴，彤庭散綬垂鳴璫。","黄紙詔书出东廂，轻紈叠綺爛生光。","宗室子弟君最賢，分憂當爲百辟先。","布衣一言相爲死，何況聖主恩如天。","鸾声噦噦魯侯旂，明年上計朝京師。","須憶今日斗酒別，慎勿富貴忘我爲。"]', '诗', 'shi', '', NULL, '送李睢陽 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c86dd14-c343-4536-9713-93ac4edbbf8e', '奉和聖製天長節賜宰臣歌應制', '奉和聖製天长節賜宰臣歌應制', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["太陽升兮照萬方，開閶闔兮臨玉堂。","儼冕旒兮垂衣裳，金天淨兮麗三光。","彤庭曙兮延八荒，德合天兮禮神徧。","靈芝生兮慶雲見，唐堯后兮稷卨臣。","匝宇宙兮華胥人，盡九服兮皆四鄰，乾降瑞兮坤降珍。"]', '["太陽升兮照万方，开閶闔兮臨玉堂。","儼冕旒兮垂衣裳，金天淨兮丽三光。","彤庭曙兮延八荒，德合天兮禮神徧。","靈芝生兮慶云见，唐堯后兮稷卨臣。","匝宇宙兮华胥人，尽九服兮皆四鄰，乾降瑞兮坤降珍。"]', '诗', 'shi', '', NULL, '奉和聖製天長節賜宰臣歌應制 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eff02ed-d245-4c86-bc91-6f67a72ac95c', '登樓歌', '登楼歌', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["聊上君兮高樓，飛甍鱗次兮在下。","俯十二兮通衢，綠槐參差兮車馬。","却瞻兮龍首，前眺兮宜春。","王畿鬱兮千里，山河壯兮咸秦。","舍人下兮青宮，據胡牀兮書空。","執戟疲於下位，老夫好隱兮牆東。","亦幸有張伯英草聖兮龍騰蚪躍，擺長雲兮捩迴風。","琥珀酒兮彫胡飯，君不御兮日將晚。","秋風兮吹衣，夕鳥兮爭返。","孤砧發兮東城，林薄暮兮蟬聲遠。","時不可兮再得，君何爲兮偃蹇。"]', '["聊上君兮高楼，飞甍鱗次兮在下。","俯十二兮通衢，綠槐參差兮车马。","却瞻兮龙首，前眺兮宜春。","王畿鬱兮千里，山河壯兮咸秦。","舍人下兮青宮，據胡牀兮书空。","執戟疲於下位，老夫好隐兮牆东。","亦幸有張伯英草聖兮龙腾蚪躍，擺长云兮捩迴风。","琥珀酒兮彫胡飯，君不御兮日將晚。","秋风兮吹衣，夕鸟兮爭返。","孤砧發兮东城，林薄暮兮蟬声远。","时不可兮再得，君何爲兮偃蹇。"]', '诗', 'shi', '', NULL, '登樓歌 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('179e62dd-8983-45c3-a3db-52d9bd1871af', '雙黃鵠歌送別', '雙黄鵠歌送別', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["天路來兮雙黃鵠，雲上飛兮水上宿。","撫翼和鳴整羽族，不得已，忽分飛。","家在玉京朝紫微，主人臨水送將歸。","悲笳嘹唳垂舞衣，賓欲散兮復相依。","幾往返兮極浦，尚裴回兮落暉。","岸上火兮相迎，將夜入兮邊城。","鞍馬歸兮佳人散，悵離憂兮獨含情。"]', '["天路来兮雙黄鵠，云上飞兮水上宿。","撫翼和鳴整羽族，不得已，忽分飞。","家在玉京朝紫微，主人臨水送將归。","悲笳嘹唳垂舞衣，賓欲散兮复相依。","幾往返兮極浦，尚裴回兮落暉。","岸上火兮相迎，將夜入兮邊城。","鞍马归兮佳人散，悵離憂兮独含情。"]', '诗', 'shi', '', NULL, '雙黃鵠歌送別 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86f8a6ad-c725-410f-8a90-d25413b3b82a', '贈徐中書望終南山歌', '贈徐中书望終南山歌', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["晚下兮紫微，悵塵事兮多違。","駐馬兮雙樹，望青山兮不歸。"]', '["晚下兮紫微，悵塵事兮多違。","駐马兮雙樹，望青山兮不归。"]', '诗', 'shi', '', NULL, '贈徐中書望終南山歌 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39096ae6-97b3-422e-a1c6-f725d8f5c105', '送友人歸山歌二首 一', '送友人归山歌二首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["山寂寂兮無人，又蒼蒼兮多木。","羣龍兮滿朝，君何爲兮空谷。","文寡和兮思深，道難知兮行獨。","悅石上兮流泉，與松間兮草屋。","入雲中兮養雞，上山頭兮抱犢。","神與棗兮如瓜，虎賣杏兮收穀。","愧不才兮妨賢，嫌既老兮貪祿。","誓解印兮相從，何詹尹兮何卜。"]', '["山寂寂兮無人，又蒼蒼兮多木。","羣龙兮满朝，君何爲兮空谷。","文寡和兮思深，道难知兮行独。","悅石上兮流泉，與松间兮草屋。","入云中兮養雞，上山头兮抱犢。","神與棗兮如瓜，虎賣杏兮收穀。","愧不才兮妨賢，嫌既老兮貪祿。","誓解印兮相從，何詹尹兮何卜。"]', '诗', 'shi', '', NULL, '送友人歸山歌二首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('837924d5-03d4-4133-8031-d1f042686d65', '送友人歸山歌二首 二', '送友人归山歌二首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["山中人兮欲歸，雲冥冥兮雨霏霏，水驚波兮翠菅靡。","白鷺忽兮翻飛，君不可兮褰衣。","山萬重兮一雲，混天地兮不分。","樹晻曖兮氛氳，猿不見兮空聞。","忽山西兮夕陽，見東臯兮遠村。","平蕪綠兮千里，眇惆悵兮思君。"]', '["山中人兮欲归，云冥冥兮雨霏霏，水驚波兮翠菅靡。","白鷺忽兮翻飞，君不可兮褰衣。","山万重兮一云，混天地兮不分。","樹晻曖兮氛氳，猿不见兮空闻。","忽山西兮夕陽，见东臯兮远村。","平蕪綠兮千里，眇惆悵兮思君。"]', '诗', 'shi', '', NULL, '送友人歸山歌二首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a6e884e-e9fb-4564-81f5-9b937d3c74b1', '魚山神女祠歌 迎神', '鱼山神女祠歌 迎神', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["坎坎擊鼓，魚山之下。","吹洞簫，望極浦，女巫進，紛屢舞。","陳瑤席，湛清酤，風淒淒兮夜雨。","不知神之來兮不來，使我心兮苦復苦。"]', '["坎坎擊鼓，鱼山之下。","吹洞簫，望極浦，女巫進，紛屢舞。","陳瑤席，湛清酤，风淒淒兮夜雨。","不知神之来兮不来，使我心兮苦复苦。"]', '诗', 'shi', '', NULL, '魚山神女祠歌 迎神 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfc946ec-a63e-44c4-82f8-09b02cc23ea0', '魚山神女祠歌 送神', '鱼山神女祠歌 送神', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["紛進舞兮堂前，目眷眷兮瓊筵。","來不言兮意不傳，作暮雨兮愁空山。","悲急管兮思繁弦，神之駕兮儼欲旋。","倏雲收兮雨歇，山青青兮水潺湲。"]', '["紛進舞兮堂前，目眷眷兮瓊筵。","来不言兮意不傳，作暮雨兮愁空山。","悲急管兮思繁弦，神之駕兮儼欲旋。","倏云收兮雨歇，山青青兮水潺湲。"]', '诗', 'shi', '', NULL, '魚山神女祠歌 送神 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7f7681d-2be9-4d46-8186-e3fe25b52634', '白黿渦', '白黿渦', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["南山之瀑水兮，激石瀥瀑似雷驚。","人相對兮，不聞語聲。","翻渦跳沫兮蒼苔濕，蘚老且厚，春草爲之不生。","獸不敢驚動，鳥不敢飛鳴。","白黿渦濤戲瀨兮，委身以縱橫。","王人之仁兮，不網不釣，得遂性以生成。"]', '["南山之瀑水兮，激石瀥瀑似雷驚。","人相对兮，不闻語声。","翻渦跳沫兮蒼苔濕，蘚老且厚，春草爲之不生。","獸不敢驚动，鸟不敢飞鳴。","白黿渦濤戲瀨兮，委身以縱橫。","王人之仁兮，不網不釣，得遂性以生成。"]', '诗', 'shi', '', NULL, '白黿渦 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5efed14-4e44-4656-9f21-c8e505dca5e2', '宋進馬哀詞', '宋進马哀词', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["背春涉夏兮，衆木藹以繁陰。","連金華與玉堂兮，宮閣鬱其沈沈。","百官並入兮，何語笑之啞啞。","君獨靜嘿以傷心，草王言兮不得辭。","我悲減思兮少時，僕夫命駕兮。","出閶闔，歷通逵，陌上人兮如故。","識不識兮往來，眼中不見兮吾兒。","驂紫騮兮從青驪，低光垂彩兮。","怳不知其所之，闢朱戶兮望華軒。","意斯子兮候門，忽思瘞兮城南。","心瞀亂兮重昏，仰訴天之不仁兮。","家唯一身，身止一子。","何胤嗣之不繁，就單尠而又死。","將清白兮遺誰，問詩禮兮已矣。","哀從中兮不可勝，豈暇料餘年兮復幾。","日黯黯兮頹曄，鳥翩翩兮疾飛。","邈窮天兮不返，疑有日兮來歸。","靜言思兮永絕，復驚叫兮沾衣。","客有弔之者曰：觀未始兮有物，同委蛻兮胡悲。","且延陵兮未至，況西河兮不知。","學無生兮庶可，幸能聽於吾師。"]', '["背春涉夏兮，衆木藹以繁陰。","連金华與玉堂兮，宮閣鬱其沈沈。","百官並入兮，何語笑之啞啞。","君独静嘿以傷心，草王言兮不得辞。","我悲減思兮少时，僕夫命駕兮。","出閶闔，歷通逵，陌上人兮如故。","識不識兮往来，眼中不见兮吾兒。","驂紫騮兮從青驪，低光垂彩兮。","怳不知其所之，闢朱戶兮望华軒。","意斯子兮候门，忽思瘞兮城南。","心瞀亂兮重昏，仰訴天之不仁兮。","家唯一身，身止一子。","何胤嗣之不繁，就單尠而又死。","將清白兮遺誰，问诗禮兮已矣。","哀從中兮不可勝，豈暇料餘年兮复幾。","日黯黯兮頹曄，鸟翩翩兮疾飞。","邈窮天兮不返，疑有日兮来归。","静言思兮永絕，复驚叫兮沾衣。","客有弔之者曰：观未始兮有物，同委蛻兮胡悲。","且延陵兮未至，況西河兮不知。","学無生兮庶可，幸能听於吾師。"]', '诗', 'shi', '', NULL, '宋進馬哀詞 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de77fb82-ebdd-4065-b58c-7b9106f8b218', '奉和聖製賜史供奉曲江讌應制', '奉和聖製賜史供奉曲江讌應制', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["侍從有鄒枚，瓊筵就水開。","言陪柏梁宴，新下建章來。","對酒山河滿，移舟草樹廻。","天文同麗日，駐景惜行杯。"]', '["侍從有鄒枚，瓊筵就水开。","言陪柏梁宴，新下建章来。","对酒山河满，移舟草樹廻。","天文同丽日，駐景惜行杯。"]', '诗', 'shi', '', NULL, '奉和聖製賜史供奉曲江讌應制 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35f90b91-f4ed-4776-80fe-d1eefb4ac7c9', '從岐王過楊氏別業應教', '從岐王過楊氏別業應教', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["楊子談經所，淮王載酒過。","興闌啼鳥換，坐久落花多。","逕轉廻銀燭，林開散玉珂。","嚴城時未啓，前路擁笙歌。"]', '["楊子談經所，淮王載酒過。","兴闌啼鸟換，坐久落花多。","逕轉廻銀燭，林开散玉珂。","嚴城时未啓，前路擁笙歌。"]', '诗', 'shi', '', NULL, '從岐王過楊氏別業應教 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c40e93c2-8d43-4a93-9687-6c0b5d45376b', '從岐王夜宴衞家山池應教', '從岐王夜宴衞家山池應教', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["座客香貂滿，宮娃綺幔張。","澗花輕粉色，山月少燈光。","積翠紗窗暗，飛泉繡戶涼。","還將歌舞出，歸路莫愁長。"]', '["座客香貂满，宮娃綺幔張。","澗花轻粉色，山月少灯光。","積翠紗窗暗，飞泉繡戶涼。","還將歌舞出，归路莫愁长。"]', '诗', 'shi', '', NULL, '從岐王夜宴衞家山池應教 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba12b5ab-ce4e-4a10-bd9d-a476ebe14289', '早朝', '早朝', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["柳暗百花明，春深五鳳城。","城烏睥睨曉，宮井轆轤聲。","方朔金門侍，班姬玉輦迎。","仍聞遣方士，東海訪蓬瀛。"]', '["柳暗百花明，春深五鳳城。","城烏睥睨晓，宮井轆轤声。","方朔金门侍，班姬玉輦迎。","仍闻遣方士，东海訪蓬瀛。"]', '诗', 'shi', '', NULL, '早朝 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba54ac5b-a131-4af6-a7e0-938db34b82fb', '同崔員外秋宵寓直', '同崔員外秋宵寓直', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["建禮高秋夜，承明候曉過。","九門寒漏徹，萬井曙鐘多。","月迥藏珠斗，雲消出絳河。","更慙衰朽質，南陌共鳴珂。"]', '["建禮高秋夜，承明候晓過。","九门寒漏徹，万井曙鐘多。","月迥藏珠斗，云消出絳河。","更慙衰朽質，南陌共鳴珂。"]', '诗', 'shi', '', NULL, '同崔員外秋宵寓直 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2b4e8ca-92e3-4101-8a54-739b8f1d8184', '輞川閑居贈裴秀才迪', '輞川闲居贈裴秀才迪', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["寒山轉蒼翠，秋水日潺湲。","倚杖柴門外，臨風聽暮蟬。","渡頭餘落日，墟里上孤煙。","復值接輿醉，狂歌五柳前。"]', '["寒山轉蒼翠，秋水日潺湲。","倚杖柴门外，臨风听暮蟬。","渡头餘落日，墟里上孤煙。","复值接輿醉，狂歌五柳前。"]', '诗', 'shi', '', NULL, '輞川閑居贈裴秀才迪 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f61aa962-4d0c-4cd1-b96b-4c515fe4e229', '寄荆州張丞相', '寄荆州張丞相', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["所思竟何在，悵望深荆門。","舉世無相識，終身思舊恩。","方將與農圃，藝植老丘園。","目盡南飛鴈，何由寄一言。"]', '["所思竟何在，悵望深荆门。","舉世無相識，終身思旧恩。","方將與農圃，藝植老丘园。","目尽南飞鴈，何由寄一言。"]', '诗', 'shi', '', NULL, '寄荆州張丞相 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e4d001d-ec19-4bef-886b-a49267ec88c8', '冬晚對雪憶胡居士家', '冬晚对雪憶胡居士家', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["寒更傳曉箭，清鏡覽衰顏。","隔牖風驚竹，開門雪滿山。","灑空深巷靜，積素廣庭閑。","借問袁安舍，翛然尚閉關。"]', '["寒更傳晓箭，清镜覽衰顏。","隔牖风驚竹，开门雪满山。","灑空深巷静，積素廣庭闲。","借问袁安舍，翛然尚閉关。"]', '诗', 'shi', '', NULL, '冬晚對雪憶胡居士家 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91b9a8a5-a751-4edc-8d7d-9ba0ff428022', '和尹諫議史館山池', '和尹諫議史館山池', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["雲館接天居，霓裳侍玉除。","春池百子外，芳樹萬年餘。","洞有仙人籙，山藏太史書。","君恩深漢帝，且莫上空虛。"]', '["云館接天居，霓裳侍玉除。","春池百子外，芳樹万年餘。","洞有仙人籙，山藏太史书。","君恩深漢帝，且莫上空虛。"]', '诗', 'shi', '', NULL, '和尹諫議史館山池 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6688fe24-3774-4619-90c3-53f950a45bc7', '奉和楊駙馬六郎秋夜即事', '奉和楊駙马六郎秋夜即事', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["高樓月似霜，秋夜鬱金堂。","對坐彈盧女，同看舞鳳凰。","少兒多送酒，小玉更焚香。","結束平陽騎，明朝入建章。"]', '["高楼月似霜，秋夜鬱金堂。","对坐彈盧女，同看舞鳳凰。","少兒多送酒，小玉更焚香。","結束平陽騎，明朝入建章。"]', '诗', 'shi', '', NULL, '奉和楊駙馬六郎秋夜即事 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('982ea77f-d54e-4520-84f6-e97d07590d24', '酬虞部蘇員外過藍田別業不見留之作', '酬虞部蘇員外過藍田別業不见留之作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["貧居依谷口，喬木帶荒村。","石路枉廻駕，山家誰候門。","漁舟膠凍浦，獵火燒寒原。","唯有白雲外，疎鐘聞夜猿。"]', '["貧居依谷口，喬木带荒村。","石路枉廻駕，山家誰候门。","漁舟膠凍浦，獵火燒寒原。","唯有白云外，疎鐘闻夜猿。"]', '诗', 'shi', '', NULL, '酬虞部蘇員外過藍田別業不見留之作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('656d7352-c966-4e3c-a716-31a5cf090fcd', '酬比部楊員外暮宿琴臺朝躋書閣率爾見贈之作', '酬比部楊員外暮宿琴台朝躋书閣率爾见贈之作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["舊簡拂塵看，鳴琴候月彈。","桃源迷漢姓，松樹有秦官。","空谷歸人少，青山背日寒。","羨君棲隱處，遙望白雲端。"]', '["旧簡拂塵看，鳴琴候月彈。","桃源迷漢姓，松樹有秦官。","空谷归人少，青山背日寒。","羨君棲隐处，遙望白云端。"]', '诗', 'shi', '', NULL, '酬比部楊員外暮宿琴臺朝躋書閣率爾見贈之作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5198b849-a7e1-41d8-8374-65023370cd27', '酬嚴少尹徐舍人見過不遇', '酬嚴少尹徐舍人见過不遇', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["公門暇日少，窮巷故人稀。","偶值乘籃轝，非關避白衣。","不知炊黍谷，誰解埽荆扉。","君但傾茶椀，無妨騎馬歸。"]', '["公门暇日少，窮巷故人稀。","偶值乘籃轝，非关避白衣。","不知炊黍谷，誰解埽荆扉。","君但傾茶椀，無妨騎马归。"]', '诗', 'shi', '', NULL, '酬嚴少尹徐舍人見過不遇 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65e9c24b-bdbd-4ef9-9e14-012c8fde79b8', '酬張少府', '酬張少府', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["晚年唯好靜，萬事不關心。","自顧無長策，空知返舊林。","松風吹解帶，山月照彈琴。","君問窮通理，漁歌入浦深。"]', '["晚年唯好静，万事不关心。","自顧無长策，空知返旧林。","松风吹解带，山月照彈琴。","君问窮通理，漁歌入浦深。"]', '诗', 'shi', '', NULL, '酬張少府 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee7d6f1c-26d6-426e-91dc-5d7bd2189c77', '酬賀四贈葛巾之作', '酬賀四贈葛巾之作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["野巾傳惠好，茲貺重兼金。","嘉此幽棲物，能齊隱吏心。","早朝方暫挂，晚沐復來簪。","坐覺囂塵遠，思君共入林。"]', '["野巾傳惠好，茲貺重兼金。","嘉此幽棲物，能齊隐吏心。","早朝方暫挂，晚沐复来簪。","坐覺囂塵远，思君共入林。"]', '诗', 'shi', '', NULL, '酬賀四贈葛巾之作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b17ef599-916e-4d87-8f7c-c1076a9ff298', '送丘爲落第歸江東', '送丘爲落第归江东', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["憐君不得意，況復柳條春。","爲客黃金盡，還家白髮新。","五湖三畝宅，萬里一歸人。","知爾不能薦，羞稱獻納臣。"]', '["怜君不得意，況复柳條春。","爲客黄金尽，還家白髮新。","五湖三畝宅，万里一归人。","知爾不能薦，羞稱獻納臣。"]', '诗', 'shi', '', NULL, '送丘爲落第歸江東 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('611a726a-ada6-47be-8b94-cee54bb07429', '送李判官赴東江', '送李判官赴东江', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["聞道皇華使，方隨皁蓋臣。","封章通左語，冠冕化文身。","樹色分揚子，潮聲滿富春。","遙知辨璧吏，恩到泣珠人。"]', '["闻道皇华使，方隨皁蓋臣。","封章通左語，冠冕化文身。","樹色分揚子，潮声满富春。","遙知辨璧吏，恩到泣珠人。"]', '诗', 'shi', '', NULL, '送李判官赴東江 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('684f6b6f-c85c-4f04-968e-2b7beefae631', '送封太守', '送封太守', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["忽解羊頭削，聊馳熊首轓。","揚舲發夏口，按節向吳門。","帆暎丹陽郭，楓攢赤岸村。","百村多候吏，露冕一何尊。"]', '["忽解羊头削，聊驰熊首轓。","揚舲發夏口，按節向吳门。","帆暎丹陽郭，楓攢赤岸村。","百村多候吏，露冕一何尊。"]', '诗', 'shi', '', NULL, '送封太守 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d30a7f2e-6471-4693-ba4b-34a61ab73587', '送嚴秀才還蜀', '送嚴秀才還蜀', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["寧親爲令子，似舅即賢甥。","別路經花縣，還鄉入錦城。","山臨青塞斷，江向白雲平。","獻賦何時至，明君憶長卿。"]', '["寧親爲令子，似舅即賢甥。","別路經花縣，還乡入錦城。","山臨青塞斷，江向白云平。","獻賦何时至，明君憶长卿。"]', '诗', 'shi', '', NULL, '送嚴秀才還蜀 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d00c9bb5-f0bd-4256-8ebf-adc87e90c16e', '送張判官赴河西', '送張判官赴河西', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["單車曾出塞，報國敢邀勳。","見逐張征虜，今思霍冠軍。","沙平連白雪，蓬卷入黃雲。","慷慨倚長劒，高歌一送君。"]', '["單车曾出塞，報国敢邀勳。","见逐張征虜，今思霍冠軍。","沙平連白雪，蓬卷入黄云。","慷慨倚长劒，高歌一送君。"]', '诗', 'shi', '', NULL, '送張判官赴河西 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d5d3072-6ffd-48c7-9f82-a4cebd7271a4', '送岐州源長史歸', '送岐州源长史归', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["握手一相送，心悲安可論。","秋風正蕭索，客散孟嘗門。","故驛通槐里，長亭下槿原。","征西舊旌節，從此向河源。"]', '["握手一相送，心悲安可論。","秋风正蕭索，客散孟嘗门。","故驛通槐里，长亭下槿原。","征西旧旌節，從此向河源。"]', '诗', 'shi', '', NULL, '送岐州源長史歸 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae0f0690-88e2-4f08-8e30-ab9e370a1164', '送張道士歸山', '送張道士归山', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["先生何處去，王屋訪茅君。","別婦留丹訣，驅雞入白雲。","人間若剩住，天上復離羣。","當作遼城鶴，仙歌使爾聞。"]', '["先生何处去，王屋訪茅君。","別婦留丹訣，驱雞入白云。","人间若剩住，天上复離羣。","當作遼城鹤，仙歌使爾闻。"]', '诗', 'shi', '', NULL, '送張道士歸山 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('709fec89-040a-4bd4-bded-75c329c91dce', '同崔興宗送衡嶽瑗公南歸', '同崔兴宗送衡嶽瑗公南归', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["言從石菌閣，新下穆陵關。","獨向池陽去，白雲留故山。","綻衣秋日裏，洗鉢古松間。","一施傳心法，唯將戒定還。"]', '["言從石菌閣，新下穆陵关。","独向池陽去，白云留故山。","綻衣秋日裏，洗鉢古松间。","一施傳心法，唯將戒定還。"]', '诗', 'shi', '', NULL, '同崔興宗送衡嶽瑗公南歸 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68a713ee-c23e-499f-be71-218e8c364da5', '送錢少府還藍田', '送錢少府還藍田', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["草色日向好，桃源人去稀。","手持平子賦，目送老萊衣。","每候山櫻發，時同海燕歸。","今年寒食酒，應是返柴扉。"]', '["草色日向好，桃源人去稀。","手持平子賦，目送老萊衣。","每候山櫻發，时同海燕归。","今年寒食酒，應是返柴扉。"]', '诗', 'shi', '', NULL, '送錢少府還藍田 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9ec004c-e03b-4135-aa37-95bf49b86444', '送丘爲往唐州', '送丘爲往唐州', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["宛洛有風塵，君行多苦辛。","四愁連漢水，百口寄隨人。","槐色陰清晝，楊花惹暮春。","朝端肯相送，天子繡衣臣。"]', '["宛洛有风塵，君行多苦辛。","四愁連漢水，百口寄隨人。","槐色陰清晝，楊花惹暮春。","朝端肯相送，天子繡衣臣。"]', '诗', 'shi', '', NULL, '送丘爲往唐州 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0755edb-2d34-43e2-85d8-a75a715b65a0', '送元中丞轉運江淮', '送元中丞轉運江淮', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["薄賦歸天府，輕徭賴使臣。","歡霑賜帛老，恩及卷綃人。","去問珠官俗，來經石𧉧春。","東南御亭上，莫使有風塵。"]', '["薄賦归天府，轻徭賴使臣。","歡霑賜帛老，恩及卷綃人。","去问珠官俗，来經石𧉧春。","东南御亭上，莫使有风塵。"]', '诗', 'shi', '', NULL, '送元中丞轉運江淮 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2c5d189-883e-4d48-82fc-61d0a04236bf', '送崔九興宗遊蜀', '送崔九兴宗游蜀', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["送君從此去，轉覺故人稀。","徒御猶廻首，田園方掩扉。","出門當旅食，中路授寒衣。","江漢風流地，遊人何歲歸。"]', '["送君從此去，轉覺故人稀。","徒御猶廻首，田园方掩扉。","出门當旅食，中路授寒衣。","江漢风流地，游人何歲归。"]', '诗', 'shi', '', NULL, '送崔九興宗遊蜀 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b56a658b-696b-448a-93a2-1bb65f90b6c1', '送崔興宗', '送崔兴宗', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["已恨親皆遠，誰憐友復稀。","君王未西顧，遊宦盡東歸。","塞迥山河淨，天長雲樹微。","方同菊花節，相待洛陽扉。"]', '["已恨親皆远，誰怜友复稀。","君王未西顧，游宦尽东归。","塞迥山河淨，天长云樹微。","方同菊花節，相待洛陽扉。"]', '诗', 'shi', '', NULL, '送崔興宗 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a845660-3346-4206-9336-1e6b7153db6d', '送平澹然判官', '送平澹然判官', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["不識陽關路，新從定遠侯。","黃雲斷春色，畫角起邊愁。","瀚海經年到，交河出塞流。","須令外國使，知飲月氏頭。"]', '["不識陽关路，新從定远侯。","黄云斷春色，畫角起邊愁。","瀚海經年到，交河出塞流。","須令外国使，知饮月氏头。"]', '诗', 'shi', '', NULL, '送平澹然判官 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb6bf278-e522-47eb-8259-c710c0704379', '送劉司直赴安西', '送劉司直赴安西', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["絕域陽關道，胡沙與塞塵。","三春時有雁，萬里少行人。","苜蓿隨天馬，葡萄逐漢臣。","當令外國懼，不敢覓和親。"]', '["絕域陽关道，胡沙與塞塵。","三春时有雁，万里少行人。","苜蓿隨天马，葡萄逐漢臣。","當令外国懼，不敢覓和親。"]', '诗', 'shi', '', NULL, '送劉司直赴安西 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6891896-fb80-4094-9f60-9fc3fe1c63ec', '送趙都督赴代州得青字', '送趙都督赴代州得青字', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["天官動將星，漢上柳條青。","萬里鳴刁斗，三軍出井陘。","忘身辭鳳闕，報國取龍庭。","豈學書生輩，窗間老一經。"]', '["天官动將星，漢上柳條青。","万里鳴刁斗，三軍出井陘。","忘身辞鳳闕，報国取龙庭。","豈学书生輩，窗间老一經。"]', '诗', 'shi', '', NULL, '送趙都督赴代州得青字 王維 shi');
